   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'inde'), 'Le 18 décembre au matin, six Hunter du No. 17 Squadron, menés par le Sqn Ldr Jayawant Singh, détruisent à la roquette et au canon la station radio de Bambolim ; un détachement du même escadron assure la défense aérienne depuis Sambre.', 'On the morning of 18 December six Hunters of No. 17 Squadron, led by Sqn Ldr Jayawant Singh, destroyed the Bambolim wireless station with rockets and cannon; a detachment of the same squadron flew air defence from Sambre.', 'https://www.bharat-rakshak.com/IAF/history/1961goa/overview-goa/
https://en.wikipedia.org/wiki/Indian_annexation_of_Goa');
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1961-12-10', 'day', 'Nehru exclut le statu quo', 'Nehru rules out the status quo', 'Le Premier ministre indien déclare que le maintien de Goa sous domination portugaise est « une impossibilité ».', 'The Indian Prime Minister declared that continued Portuguese rule in Goa was "an impossibility".', NULL::int, 'https://en.wikipedia.org/wiki/Indian_annexation_of_Goa' FROM wars w WHERE w.name = 'Annexion de Goa'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1961-12-17', 'day', 'Début de l’opération *Vijay*', 'Operation *Vijay* begins', 'Les hostilités s’ouvrent à 9 h 45 à Maulinguém ; dans la journée, un Vampire de reconnaissance survole Dabolim et revient touché par cinq projectiles.', 'Hostilities opened at 09:45 at Maulinguém; during the day a reconnaissance Vampire overflew Dabolim and came back with five hits.', NULL::int, 'https://en.wikipedia.org/wiki/Indian_annexation_of_Goa' FROM wars w WHERE w.name = 'Annexion de Goa'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
