       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1961-12-17', 'day', 'Un Constellation atterrit à Goa', 'A Constellation lands in Goa', 'Faute d’autorisation de survol pour un avion militaire, un Constellation de la TAP se pose à 18 h : il devait apporter des grenades antichars, il apporte des saucisses.', 'With no overflight rights for a military aircraft, a TAP Constellation landed at 18:00: it was meant to bring anti-tank grenades and brought sausages instead.', NULL::int, 'https://en.wikipedia.org/wiki/Indian_annexation_of_Goa' FROM wars w WHERE w.name = 'Annexion de Goa'
