INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1961-12-18', 'day', 'Les Canberra bombardent Dabolim', 'Canberras bomb Dabolim', 'Douze Canberra du No. 35 Squadron larguent 63 000 livres de bombes sur la piste, puis huit du No. 16 Squadron frappent à leur tour, en épargnant l’aérogare.', 'Twelve Canberras of No. 35 Squadron dropped 63,000 lb of bombs on the runway, followed by eight from No. 16 Squadron, sparing the terminal.', (SELECT id FROM airplanes WHERE name = 'English Electric Canberra'), 'https://www.bharat-rakshak.com/IAF/history/1961goa/overview-goa/' FROM wars w WHERE w.name = 'Annexion de Goa'
