INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'colombie', 1, 'État colombien', 'Colombian state', 'Forces armées et police de Colombie (dont la Fuerza Aérea Colombiana, devenue Fuerza Aeroespacial Colombiana), soutenues par les États-Unis', 'Colombian armed forces and police (including the Colombian Air Force, now the Colombian Aerospace Force), backed by the United States' FROM wars w WHERE w.name = 'Conflit armé colombien'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'guerillas', 2, 'Guérillas', 'Guerrillas', 'FARC-EP (jusqu’en 2017), ELN, M-19 (jusqu’en 1990), EPL, puis dissidences des FARC', 'FARC-EP (until 2017), ELN, M-19 (until 1990), EPL, then FARC dissident groups' FROM wars w WHERE w.name = 'Conflit armé colombien'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Conflit armé colombien' AND s.side_key NOT IN ('colombie', 'guerillas');
