INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1964-05-27', 'day', 'L’assaut sur Marquetalia', 'The assault on Marquetalia', 'L’armée attaque l’enclave communiste de Marquetalia ; ses survivants fondent les FARC, et cette date est retenue comme le début du conflit.', 'The army attacks the communist enclave of Marquetalia; its survivors found the FARC, and the date is taken as the start of the conflict.', NULL::int, 'https://en.wikipedia.org/wiki/Colombian_conflict' FROM wars w WHERE w.name = 'Conflit armé colombien'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
