SELECT w.id, DATE '2019-02-14', 'day', 'Attentat de Pulwama', 'Pulwama attack', 'Un attentat-suicide revendiqué par le Jaish-e-Mohammed tue une quarantaine de policiers paramilitaires indiens au Cachemire ; l''Inde promet une riposte.', 'A suicide bombing claimed by Jaish-e-Mohammed kills some 40 Indian paramilitary police in Kashmir; India vows to respond.', NULL::int, 'https://en.wikipedia.org/wiki/2019_India%E2%80%93Pakistan_border_skirmishes' FROM wars w WHERE w.name = 'Conflit indo-pakistanais de 2019'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
