INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'israel', 1, 'Israël', 'Israel', 'Israël (force aérienne israélienne, créée en mai 1948)', 'Israel (Israeli Air Force, formed in May 1948)' FROM wars w WHERE w.name = 'Conflit israélo-arabe'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'pays-arabes', 2, 'États arabes', 'Arab states', 'Égypte, Syrie, Jordanie, Irak, Liban, avec des renforts d''autres pays arabes en 1948 et 1973 (Arabie saoudite, Libye, Algérie…) ; puis, à partir des années 1980, des mouvements armés (OLP, Hezbollah, Hamas)', 'Egypt, Syria, Jordan, Iraq, Lebanon, with reinforcements from other Arab countries in 1948 and 1973 (Saudi Arabia, Libya, Algeria…); then, from the 1980s, armed movements (the PLO, Hezbollah, Hamas)' FROM wars w WHERE w.name = 'Conflit israélo-arabe'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Conflit israélo-arabe' AND s.side_key NOT IN ('israel', 'pays-arabes');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'israel'), role = 'Principal avion d''attaque israélien à partir de 1967 : il mène l''essentiel des frappes de la guerre d''usure, paie le plus lourd tribut au Kippour (53 perdus, surtout aux missiles sol-air) et combat encore au Liban en 1982 ; dernier emploi en 2012 au-dessus de Gaza.', role_en = 'Israel''s main attack aircraft from 1967: it flew most of the War of Attrition strikes, paid the heaviest price in 1973 (53 lost, mostly to SAMs) and fought again in Lebanon in 1982; it was last used over Gaza in 2012.', sources = 'https://en.wikipedia.org/wiki/McDonnell_Douglas_A-4_Skyhawk
