   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'pays-arabes'), 'Chasseur-bombardier égyptien des années 1950 : des Vampire sont abattus par des Meteor israéliens le 1er septembre 1955, puis attaquent les Israéliens au col de Mitla pendant Suez, où l''Égypte en perd quatre en combat aérien.', 'Egypt''s fighter-bomber of the 1950s: Vampires were shot down by Israeli Meteors on 1 September 1955, then attacked Israeli forces at the Mitla Pass during Suez, where Egypt lost four in air combat.', 'https://en.wikipedia.org/wiki/De_Havilland_Vampire
https://en.wikipedia.org/wiki/Gloster_Meteor');
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1948-06-03', 'day', 'Premières victoires de la chasse israélienne', 'First Israeli fighter victories', 'Cinq jours après la première mission des S-199 contre une colonne égyptienne, Modi Alon abat deux C-47 égyptiens qui venaient de bombarder Tel-Aviv.', 'Five days after the S-199s'' first mission against an Egyptian column, Modi Alon shot down two Egyptian C-47s that had just bombed Tel Aviv.', (SELECT id FROM airplanes WHERE name = 'Avia S-199'), 'https://en.wikipedia.org/wiki/Avia_S-199' FROM wars w WHERE w.name = 'Conflit israélo-arabe'
