INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1956-10-28', 'day', 'Opération *Tarnegol*', 'Operation *Tarnegol*', 'À la veille de la crise de Suez, un Meteor NF.13 israélien abat de nuit un Il-14 égyptien transportant des officiers supérieurs ; le maréchal Amer, visé, voyageait dans un autre avion.', 'On the eve of the Suez Crisis, an Israeli Meteor NF.13 shot down at night an Egyptian Il-14 carrying senior officers; Field Marshal Amer, the intended target, was on another aircraft.', (SELECT id FROM airplanes WHERE name = 'Gloster Meteor'), 'https://en.wikipedia.org/wiki/Gloster_Meteor' FROM wars w WHERE w.name = 'Conflit israélo-arabe'
