INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'tchad-france', 1, 'Tchad et France', 'Chad and France', 'Tchad (gouvernement Malloum en 1978, puis FAN et FANT d''Hissène Habré), France (opérations Tacaud, Manta et Épervier) ; appui du Zaïre et des États-Unis', 'Chad (Malloum government in 1978, then Hissène Habré''s FAN and FANT), France (Operations Tacaud, Manta and Épervier); support from Zaire and the United States' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'libye', 2, 'Libye', 'Libya', 'Libye et ses alliés tchadiens (FAP de Goukouni Oueddei, GUNT, CDR) ; Légion islamique panafricaine', 'Libya and its Chadian allies (Goukouni Oueddei''s FAP, the GUNT, the CDR); the Pan-African Islamic Legion' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Conflit tchado-libyen' AND s.side_key NOT IN ('tchad-france', 'libye');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'tchad-france'), role = 'Fer de lance de l''armée de l''air française au Tchad : huit Jaguar appuient les combats d''Ati et de Djedaa en 1978, d''autres frappent une colonne près de Ziguey en janvier 1984. Ils détruisent la piste de Ouadi Doum le 16 février 1986, puis son radar au missile Martel le 7 janvier 1987.', role_en = 'The spearhead of French air power in Chad: eight Jaguars supported the fighting at Ati and Djedaa in 1978, and others struck a column near Ziguey in January 1984. They wrecked the Ouadi Doum runway on 16 February 1986, then its radar with a Martel missile on 7 January 1987.', sources = 'https://en.wikipedia.org/wiki/SEPECAT_Jaguar
