INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1978-02-20', 'day', 'Giscard d''Estaing déclenche *Tacaud*', 'Giscard d''Estaing launches *Tacaud*', 'Deux jours après la chute de Faya-Largeau, le président français décide l''opération *Tacaud* ; en avril, 2 500 soldats français sont au Tchad pour protéger la capitale.', 'Two days after Faya-Largeau fell, the French president ordered Operation *Tacaud*; by April, 2,500 French troops were in Chad to protect the capital.', NULL::int, 'https://en.wikipedia.org/wiki/Chadian%E2%80%93Libyan_War' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1978-05-31', 'day', 'Un Jaguar abattu à Djedaa', 'A Jaguar shot down at Djedaa', 'Les Jaguar appuient l''assaut français contre les rebelles retranchés à Djedaa, au nord d''Ati ; l''un d''eux, manqué par un missile SA-7, est abattu par une mitrailleuse.', 'Jaguars supported the French assault on the rebels dug in at Djedaa, north of Ati; one of them, missed by an SA-7 missile, was brought down by machine-gun fire.', (SELECT id FROM airplanes WHERE name = 'Jaguar'), 'https://en.wikipedia.org/wiki/Op%C3%A9ration_Tacaud' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
