INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1980-10-09', 'day', 'Première mission des Tu-22 libyens', 'First Libyan Tu-22 mission', 'Les Tu-22 libyens effectuent leur première mission au-dessus du Tchad contre les forces d''Hissène Habré près de N''Djamena.', 'Libyan Tu-22s flew their first mission over Chad, against Hissène Habré''s forces near N''Djamena.', (SELECT id FROM airplanes WHERE name = 'Tu-22'), 'https://en.wikipedia.org/wiki/Tupolev_Tu-22' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
