INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1980-12-08', 'day', 'Bombardement de N''Djamena', 'N''Djamena under bombardment', 'Depuis Dougia, à 60 km de la capitale, des SF.260 et des hélicoptères Mi-25 libyens, rejoints le 12 par des Tu-22, attaquent N''Djamena, qui tombe le 16 décembre.', 'Operating from Dougia, 60 km from the capital, Libyan SF.260s and Mi-25 helicopters, joined by Tu-22s on the 12th, attacked N''Djamena, which fell on 16 December.', (SELECT id FROM airplanes WHERE name = 'SF.260'), 'https://en.wikipedia.org/wiki/SIAI-Marchetti_SF.260' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
