INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1983-08-01', 'month', 'Lancement de *Manta*', 'Operation *Manta* begins', 'Face aux bombardements libyens sur Faya-Largeau, la France envoie au Tchad des troupes et des Jaguar et trace une « ligne rouge » sur le 15e parallèle.', 'In response to the Libyan bombing of Faya-Largeau, France sent troops and Jaguars to Chad and drew a "Red Line" along the 15th parallel.', NULL::int, 'https://en.wikipedia.org/wiki/Operation_Manta' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
