INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1984-01-25', 'day', 'Le Jaguar du capitaine Croci abattu', 'Captain Croci''s Jaguar shot down', 'Lancés pour ralentir une importante colonne ennemie, vers Torodum, les Jaguar l''attaquent ; celui du capitaine Michel Croci, touché à basse altitude, percute une dune et son pilote est tué.', 'Sent to slow down a large enemy column near Torodum, the Jaguars attacked it; Captain Michel Croci''s aircraft was hit at low level and crashed into a dune, killing him.', (SELECT id FROM airplanes WHERE name = 'Jaguar'), 'https://fr.wikipedia.org/wiki/Op%C3%A9ration_Manta' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
