INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1986-02-16', 'day', 'Le raid sur Ouadi Doum', 'The Ouadi Doum raid', 'Onze Jaguar du 1/11 « Roussillon », escortés de Mirage F1, attaquent depuis Bangui la base libyenne de Ouadi Doum en un seul passage et rendent la piste inutilisable.', 'Eleven Jaguars of Escadron 1/11 Roussillon, escorted by Mirage F1s, struck the Libyan base of Ouadi Doum from Bangui in a single pass and put the runway out of use.', (SELECT id FROM airplanes WHERE name = 'Jaguar'), 'https://en.wikipedia.org/wiki/Ouadi_Doum_airstrike' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
