INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1986-02-17', 'day', 'Un Tu-22 bombarde N''Djamena', 'A Tu-22 bombs N''Djamena', 'En représailles, un Tu-22 libyen vole au ras du désert, puis bombarde l''aéroport de N''Djamena, fermé quelques heures ; il se serait écrasé avant de regagner Aozou.', 'In retaliation, a Libyan Tu-22 flew at desert-floor height, then bombed N''Djamena airport, closing it for several hours; it probably crashed before reaching Aouzou.', (SELECT id FROM airplanes WHERE name = 'Tu-22'), 'https://en.wikipedia.org/wiki/Tupolev_Tu-22' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
