INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1987-01-02', 'day', 'La prise de Fada', 'The capture of Fada', 'Les FANT d''Hassan Djamous enlèvent la base libyenne de Fada et ouvrent la « guerre des Toyota » ; l''aviation libyenne bombarde ensuite le matériel abandonné.', 'Hassan Djamous''s FANT seized the Libyan base at Fada, opening the "Toyota War"; the Libyan air force then bombed the abandoned equipment.', NULL::int, 'https://en.wikipedia.org/wiki/Battle_of_Fada' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
