INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1987-01-07', 'day', 'Seconde frappe : le radar détruit', 'Second strike: the radar destroyed', 'Après une tentative avortée la veille, un Jaguar détruit au missile Martel le radar de défense aérienne de Ouadi Doum, sous la couverture de Mirage F1.', 'After an aborted attempt the day before, a Jaguar destroyed Ouadi Doum''s air defence radar with a Martel missile, under Mirage F1 cover.', (SELECT id FROM airplanes WHERE name = 'Jaguar'), 'https://warriormaven.com/news/history/in-1987-the-french-air-force-staged-a-daring-raid-on-libyan-defenses' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
