INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1987-03-22', 'day', 'La chute de Ouadi Doum', 'The fall of Ouadi Doum', 'Après deux heures de combat, les FANT s''emparent de Ouadi Doum, la principale base aérienne libyenne au Tchad, et des avions qui s''y trouvent.', 'After two hours of fighting, the FANT seized Ouadi Doum, Libya''s main air base in Chad, along with the aircraft parked there.', NULL::int, 'https://fr.wikipedia.org/wiki/Guerre_des_Toyota' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
