INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1987-09-05', 'day', 'Le raid sur Maaten al-Sarra', 'The Maaten al-Sarra raid', 'En territoire libyen, les FANT s''emparent de la base aérienne de Maaten al-Sarra et y détruisent 26 appareils selon un bilan, 32 selon le Tchad.', 'Inside Libya, the FANT overran the Maaten al-Sarra air base and destroyed 26 aircraft there by one count, 32 according to Chad.', NULL::int, 'https://en.wikipedia.org/wiki/Battle_of_Maaten_al-Sarra' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
