INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1987-09-07', 'day', 'Un Tu-22 abattu par un Hawk', 'A Tu-22 downed by a Hawk', 'Deux Tu-22 libyens visent N''Djamena et Abéché ; celui de la capitale est abattu par une batterie Hawk française, l''autre rentre sans avoir largué ses bombes.', 'Two Libyan Tu-22s targeted N''Djamena and Abéché; the one over the capital was shot down by a French Hawk battery, the other returned without dropping its bombs.', (SELECT id FROM airplanes WHERE name = 'Tu-22'), 'https://en.wikipedia.org/wiki/Battle_of_Maaten_al-Sarra' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
