SELECT w.id, DATE '1987-09-11', 'day', 'Le cessez-le-feu', 'The ceasefire', 'Sous l''égide de l''Organisation de l''unité africaine, le Tchad et la Libye acceptent un cessez-le-feu qui met fin au conflit.', 'Under the auspices of the Organisation of African Unity, Chad and Libya accepted a ceasefire that ended the conflict.', NULL::int, 'https://en.wikipedia.org/wiki/Chadian%E2%80%93Libyan_War' FROM wars w WHERE w.name = 'Conflit tchado-libyen'
