INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'turquie', 1, 'Turquie', 'Turkey', 'Forces armées turques, gendarmerie, services de renseignement (MIT)', 'Turkish Armed Forces, Gendarmerie, intelligence service (MIT)' FROM wars w WHERE w.name = 'Conflit turco-kurde (PKK)'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'pkk', 2, 'PKK', 'PKK', 'Parti des travailleurs du Kurdistan et ses forces armées', 'Kurdistan Workers’ Party and its armed forces' FROM wars w WHERE w.name = 'Conflit turco-kurde (PKK)'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Conflit turco-kurde (PKK)' AND s.side_key NOT IN ('turquie', 'pkk');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'turquie'), role = 'Le drone lourd Akıncı fait ses débuts au combat en avril 2022 dans l’opération *Pençe-Kilit*, contre les positions du PKK de Metina, Zap et Avashin-Basyan, au nord de l’Irak, selon Baykar et le ministère turc de la Défense. Le PKK affirme en avoir abattu un en mars 2025.', role_en = 'The heavy Akıncı drone made its combat debut in April 2022 in Operation *Pençe-Kilit* (Claw-Lock), against PKK positions in the Metina, Zap and Avashin-Basyan areas of northern Iraq, according to Baykar and the Turkish Defence Ministry. The PKK claimed to have shot one down in March 2025.', sources = 'https://www.dailysabah.com/business/defense/anti-pkk-op-in-iraq-marks-first-engagement-for-turkish-combat-akinci-drone
https://en.wikipedia.org/wiki/Baykar_Bayraktar_Ak%C4%B1nc%C4%B1
