INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'commonwealth', 1, 'Malaisie et Commonwealth', 'Malaysia and the Commonwealth', 'Royaume-Uni, Malaisie, Brunei, Singapour, Australie, Nouvelle-Zélande', 'United Kingdom, Malaysia, Brunei, Singapore, Australia, New Zealand' FROM wars w WHERE w.name = 'Confrontation indonésio-malaisienne'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'indonesie', 2, 'Indonésie', 'Indonesia', 'Forces armées indonésiennes et volontaires, avec les insurgés de la révolte de Brunei et des communistes du Sarawak et de Malaisie', 'Indonesian armed forces and volunteers, with the Brunei rebels and Sarawak and Malaysian communists' FROM wars w WHERE w.name = 'Confrontation indonésio-malaisienne'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Confrontation indonésio-malaisienne' AND s.side_key NOT IN ('commonwealth', 'indonesie');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'commonwealth'), role = 'Les Javelin FAW.9 des 60e et 64e escadrons tiennent l’alerte à Tengah, Kuching et Labuan et interceptent des Tu-16 ; le 2 septembre 1964, l’un d’eux prend en chasse un C-130 indonésien qui s’abîme dans le détroit de Malacca.', role_en = 'The Javelin FAW.9s of Nos. 60 and 64 Squadrons stood alert at Tengah, Kuching and Labuan and intercepted Tu-16s; on 2 September 1964 one of them chased an Indonesian C-130 that crashed into the Strait of Malacca.', sources = 'https://www.rafmuseum.org.uk/documents/Research/RAF-Historical-Society-Journals/Journal-13-Seminar-Confrontation-with-Indonesia.pdf
https://en.wikipedia.org/wiki/Indonesia%E2%80%93Malaysia_confrontation
https://en.wikipedia.org/wiki/No._60_Squadron_RAF
https://en.wikipedia.org/wiki/Gloster_Javelin'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Gloster Javelin' AND w.name = 'Confrontation indonésio-malaisienne'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'commonwealth'), 'Les Javelin FAW.9 des 60e et 64e escadrons tiennent l’alerte à Tengah, Kuching et Labuan et interceptent des Tu-16 ; le 2 septembre 1964, l’un d’eux prend en chasse un C-130 indonésien qui s’abîme dans le détroit de Malacca.', 'The Javelin FAW.9s of Nos. 60 and 64 Squadrons stood alert at Tengah, Kuching and Labuan and intercepted Tu-16s; on 2 September 1964 one of them chased an Indonesian C-130 that crashed into the Strait of Malacca.', 'https://www.rafmuseum.org.uk/documents/Research/RAF-Historical-Society-Journals/Journal-13-Seminar-Confrontation-with-Indonesia.pdf
https://en.wikipedia.org/wiki/Indonesia%E2%80%93Malaysia_confrontation
https://en.wikipedia.org/wiki/No._60_Squadron_RAF
https://en.wikipedia.org/wiki/Gloster_Javelin');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'commonwealth'), role = 'Les Hastings du 48e escadron, basé à Changi, participent au pont aérien qui amène les Gurkhas à Brunei dès le 8 décembre 1962, puis relient Singapour à Kuching et larguent du ravitaillement aux troupes engagées contre les infiltrations indonésiennes.', role_en = 'The Hastings of No. 48 Squadron, based at Changi, joined the airlift that carried Gurkhas to Brunei from 8 December 1962, then linked Singapore with Kuching and dropped supplies to the troops opposing Indonesian infiltrations.', sources = 'https://www.rafmuseum.org.uk/documents/Research/RAF-Historical-Society-Journals/Journal-13-Seminar-Confrontation-with-Indonesia.pdf
https://en.wikipedia.org/wiki/Handley_Page_Hastings
https://en.wikipedia.org/wiki/No._48_Squadron_RAF'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Handley Page Hastings' AND w.name = 'Confrontation indonésio-malaisienne'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'commonwealth'), 'Les Hastings du 48e escadron, basé à Changi, participent au pont aérien qui amène les Gurkhas à Brunei dès le 8 décembre 1962, puis relient Singapour à Kuching et larguent du ravitaillement aux troupes engagées contre les infiltrations indonésiennes.', 'The Hastings of No. 48 Squadron, based at Changi, joined the airlift that carried Gurkhas to Brunei from 8 December 1962, then linked Singapore with Kuching and dropped supplies to the troops opposing Indonesian infiltrations.', 'https://www.rafmuseum.org.uk/documents/Research/RAF-Historical-Society-Journals/Journal-13-Seminar-Confrontation-with-Indonesia.pdf
https://en.wikipedia.org/wiki/Handley_Page_Hastings
https://en.wikipedia.org/wiki/No._48_Squadron_RAF');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'commonwealth'), role = 'Les Hunter FGA.9 du 20e escadron, aidés du 28e venu de Hong Kong, survolent Limbang en décembre 1962, gardent l’espace aérien de Bornéo depuis Kuching et Labuan, et mènent deux des trois frappes du conflit, au Johore (décembre 1964, mai 1965).', role_en = 'No. 20 Squadron''s Hunter FGA.9s, helped by No. 28 from Hong Kong, flew over Limbang in December 1962, guarded Borneo''s airspace from Kuching and Labuan, and flew two of the conflict''s three strikes, in Johore (December 1964, May 1965).', sources = 'https://www.rafmuseum.org.uk/documents/Research/RAF-Historical-Society-Journals/Journal-13-Seminar-Confrontation-with-Indonesia.pdf
https://en.wikipedia.org/wiki/No._20_Squadron_RAF
https://en.wikipedia.org/wiki/Hawker_Hunter'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Hawker Hunter' AND w.name = 'Confrontation indonésio-malaisienne'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'commonwealth'), 'Les Hunter FGA.9 du 20e escadron, aidés du 28e venu de Hong Kong, survolent Limbang en décembre 1962, gardent l’espace aérien de Bornéo depuis Kuching et Labuan, et mènent deux des trois frappes du conflit, au Johore (décembre 1964, mai 1965).', 'No. 20 Squadron''s Hunter FGA.9s, helped by No. 28 from Hong Kong, flew over Limbang in December 1962, guarded Borneo''s airspace from Kuching and Labuan, and flew two of the conflict''s three strikes, in Johore (December 1964, May 1965).', 'https://www.rafmuseum.org.uk/documents/Research/RAF-Historical-Society-Journals/Journal-13-Seminar-Confrontation-with-Indonesia.pdf
https://en.wikipedia.org/wiki/No._20_Squadron_RAF
https://en.wikipedia.org/wiki/Hawker_Hunter');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'commonwealth'), role = 'Deux Twin Pioneer posent des troupes sur un terrain sommaire à Seria lors de la révolte de Brunei ; ceux du 209e escadron et de l’aviation royale malaisienne desservent ensuite les petites pistes du Sarawak, essentiels dans les zones les plus reculées.', role_en = 'Two Twin Pioneers landed troops on rough ground at Seria during the Brunei revolt; those of No. 209 Squadron and the Royal Malaysian Air Force then served Sarawak''s small airstrips, vital in the remotest areas.', sources = 'https://www.rafmuseum.org.uk/documents/Research/RAF-Historical-Society-Journals/Journal-13-Seminar-Confrontation-with-Indonesia.pdf
https://en.wikipedia.org/wiki/Scottish_Aviation_Twin_Pioneer
https://en.wikipedia.org/wiki/Combat_operations_in_1964_during_the_Indonesian-Malaysian_Confrontation'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Scottish Aviation Twin Pioneer' AND w.name = 'Confrontation indonésio-malaisienne'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'commonwealth'), 'Deux Twin Pioneer posent des troupes sur un terrain sommaire à Seria lors de la révolte de Brunei ; ceux du 209e escadron et de l’aviation royale malaisienne desservent ensuite les petites pistes du Sarawak, essentiels dans les zones les plus reculées.', 'Two Twin Pioneers landed troops on rough ground at Seria during the Brunei revolt; those of No. 209 Squadron and the Royal Malaysian Air Force then served Sarawak''s small airstrips, vital in the remotest areas.', 'https://www.rafmuseum.org.uk/documents/Research/RAF-Historical-Society-Journals/Journal-13-Seminar-Confrontation-with-Indonesia.pdf
https://en.wikipedia.org/wiki/Scottish_Aviation_Twin_Pioneer
https://en.wikipedia.org/wiki/Combat_operations_in_1964_during_the_Indonesian-Malaysian_Confrontation');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'commonwealth'), role = 'Embarqués sur le *Centaur* (892e escadrille), les Sea Vixen patrouillent la côte est de la Malaisie du 1er au 11 septembre 1964, au moment du parachutage de Labis, puis mènent une patrouille anti-invasion en novembre ; ceux de l’*Ark Royal* opèrent depuis Singapour en 1965.', role_en = 'Embarked in HMS *Centaur* (892 Squadron), Sea Vixens patrolled Malaysia''s east coast from 1 to 11 September 1964, at the time of the Labis paradrop, then flew an anti-invasion patrol in November; those of HMS *Ark Royal* operated from Singapore in 1965.', sources = 'https://www.seavixen.org/correlation-squadrons-ships/892-sqn-to-hms-centaur-1963-to-1965
https://www.seavixen.org/correlation-squadrons-ships/890-sqn-to-hms-ark-royal-1964-1966
https://en.wikipedia.org/wiki/De_Havilland_Sea_Vixen
https://en.wikipedia.org/wiki/HMS_Centaur_(R06)'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Sea Vixen' AND w.name = 'Confrontation indonésio-malaisienne'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'commonwealth'), 'Embarqués sur le *Centaur* (892e escadrille), les Sea Vixen patrouillent la côte est de la Malaisie du 1er au 11 septembre 1964, au moment du parachutage de Labis, puis mènent une patrouille anti-invasion en novembre ; ceux de l’*Ark Royal* opèrent depuis Singapour en 1965.', 'Embarked in HMS *Centaur* (892 Squadron), Sea Vixens patrolled Malaysia''s east coast from 1 to 11 September 1964, at the time of the Labis paradrop, then flew an anti-invasion patrol in November; those of HMS *Ark Royal* operated from Singapore in 1965.', 'https://www.seavixen.org/correlation-squadrons-ships/892-sqn-to-hms-centaur-1963-to-1965
https://www.seavixen.org/correlation-squadrons-ships/890-sqn-to-hms-ark-royal-1964-1966
https://en.wikipedia.org/wiki/De_Havilland_Sea_Vixen
https://en.wikipedia.org/wiki/HMS_Centaur_(R06)');
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1962-12-08', 'day', 'Révolte de Brunei', 'Brunei revolt', 'Une insurrection soutenue par l’Indonésie éclate à Brunei ; trois Beverley et un Hastings y transportent dans la journée les premiers Gurkhas depuis Singapour.', 'An Indonesian-backed insurrection breaks out in Brunei; three Beverleys and a Hastings fly in the first Gurkhas from Singapore the same day.', (SELECT id FROM airplanes WHERE name = 'Handley Page Hastings'), 'https://www.rafmuseum.org.uk/documents/Research/RAF-Historical-Society-Journals/Journal-13-Seminar-Confrontation-with-Indonesia.pdf' FROM wars w WHERE w.name = 'Confrontation indonésio-malaisienne'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1963-01-20', 'day', '*Konfrontasi* proclamée', '*Konfrontasi* proclaimed', 'Le ministre indonésien des Affaires étrangères Subandrio annonce une politique de confrontation contre le projet de Malaisie.', 'Indonesian Foreign Minister Subandrio announces a policy of confrontation against the Malaysia project.', NULL::int, 'https://en.wikipedia.org/wiki/Indonesia%E2%80%93Malaysia_confrontation' FROM wars w WHERE w.name = 'Confrontation indonésio-malaisienne'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
