SELECT w.id, DATE '1964-09-02', 'day', 'Parachutage de Labis', 'Labis paradrop', 'Deux C-130 larguent 96 parachutistes au Johore ; un Javelin décolle de Tengah et le troisième Hercules s’abîme dans le détroit de Malacca.', 'Two C-130s drop 96 paratroopers in Johore; a Javelin scrambles from Tengah and the third Hercules crashes into the Strait of Malacca.', (SELECT id FROM airplanes WHERE name = 'Gloster Javelin'), 'https://www.rafmuseum.org.uk/documents/Research/RAF-Historical-Society-Journals/Journal-13-Seminar-Confrontation-with-Indonesia.pdf' FROM wars w WHERE w.name = 'Confrontation indonésio-malaisienne'
