INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-10-01', 'day', 'Coup d’État manqué à Jakarta', 'Failed coup in Jakarta', 'L’enlèvement et le meurtre de généraux, imputés au Parti communiste, mènent Suharto au pouvoir ; les infiltrations faiblissent nettement.', 'The kidnapping and murder of generals, blamed on the Communist Party, brings Suharto to power; infiltrations sharply decline.', NULL::int, 'https://en.wikipedia.org/wiki/Indonesia%E2%80%93Malaysia_confrontation' FROM wars w WHERE w.name = 'Confrontation indonésio-malaisienne'
