INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1966-02-01', 'month', 'Le Javelin de Kuching', 'The Kuching Javelin', 'Appelé par l’armée, un Javelin détaché à Kuching repère des infiltrés dans une clairière et les cloue au sol par des passes basses jusqu’à la capture de six d’entre eux.', 'Called in by the army, a Javelin detached to Kuching spots infiltrators in a clearing and pins them down with low passes until six are captured.', (SELECT id FROM airplanes WHERE name = 'Gloster Javelin'), 'https://www.rafmuseum.org.uk/documents/Research/RAF-Historical-Society-Journals/Journal-13-Seminar-Confrontation-with-Indonesia.pdf' FROM wars w WHERE w.name = 'Confrontation indonésio-malaisienne'
