INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'onu-gouvernement', 1, 'ONU et gouvernement congolais', 'UN and Congolese government', 'ONUC (Suède, Inde, Éthiopie, Irlande, Ghana, Italie, Iran, Philippines, Canada… ; transport aérien américain et britannique), Armée nationale congolaise et son aviation appuyée par la CIA, mercenaires de Mike Hoare, Belgique et États-Unis à Stanleyville (1964)', 'ONUC (Sweden, India, Ethiopia, Ireland, Ghana, Italy, Iran, the Philippines, Canada…; US and British airlift), Congolese National Army and its CIA-backed air force, Mike Hoare’s mercenaries, Belgium and the United States at Stanleyville (1964)' FROM wars w WHERE w.name = 'Crise congolaise'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
