INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'france-royaume-uni-israel', 1, 'France, Royaume-Uni et Israël', 'France, United Kingdom and Israel', 'France, Royaume-Uni, Israël', 'France, United Kingdom, Israel' FROM wars w WHERE w.name = 'Crise de Suez'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'egypte', 2, 'Égypte', 'Egypt', 'Égypte', 'Egypt' FROM wars w WHERE w.name = 'Crise de Suez'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Crise de Suez' AND s.side_key NOT IN ('france-royaume-uni-israel', 'egypte');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france-royaume-uni-israel'), role = 'Une centaine de Canberra de la RAF bombardent de nuit les aérodromes égyptiens depuis Malte et Chypre et assurent la reconnaissance ; ceux du 15e escadron frappent les Il-28 à Louxor le 2 novembre. Un Canberra PR.7 est abattu au-dessus de la Syrie le 6 novembre.', role_en = 'Around a hundred RAF Canberras bombed Egyptian airfields by night from Malta and Cyprus and flew reconnaissance; No. 15 Squadron’s hit the Il-28s at Luxor on 2 November. A Canberra PR.7 was shot down over Syria on 6 November.', sources = 'https://en.wikipedia.org/wiki/English_Electric_Canberra
