SELECT w.id, DATE '1956-11-04', 'day', 'Raid sur Louxor', 'Luxor raid', 'Treize F-84F français surprennent à Louxor les Il-28 égyptiens repliés ; avec une seconde vague, 17 appareils sont détruits, dont au moins dix Il-28, selon l’ACIG.', 'Thirteen French F-84Fs catch the Egyptian Il-28s withdrawn to Luxor; with a second wave, 17 aircraft are destroyed, at least ten of them Il-28s, according to ACIG.', (SELECT id FROM airplanes WHERE name = 'F-84F Thunderstreak'), 'https://acig.org/artman/publish/article_256.shtml' FROM wars w WHERE w.name = 'Crise de Suez'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1956-11-05', 'day', 'Parachutage sur El Gamil', 'Airborne assault on El Gamil', 'À l’aube, des Hastings et des Valetta de la RAF larguent le 3e bataillon du Parachute Regiment sur l’aérodrome d’El Gamil, à l’ouest de Port-Saïd.', 'At dawn, RAF Hastings and Valettas drop the 3rd Battalion, Parachute Regiment, on El Gamil airfield west of Port Said.', (SELECT id FROM airplanes WHERE name = 'Handley Page Hastings'), 'https://en.wikipedia.org/wiki/Handley_Page_Hastings' FROM wars w WHERE w.name = 'Crise de Suez'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1956-11-05', 'day', 'Les paras français sautent', 'French paratroopers jump', 'Partis de Tymbou, à Chypre, les Noratlas larguent le 2e RPC au sud de Port-Saïd le matin, puis près de Port-Fouad l’après-midi.', 'Flying from Tymbou in Cyprus, Noratlas transports drop the 2e RPC south of Port Said in the morning, then near Port Fuad in the afternoon.', (SELECT id FROM airplanes WHERE name = 'Nord Noratlas'), 'https://theatrum-belli.com/5-novembre-1956-les-francais-sautent-sur-port-said-crise-de-suez/' FROM wars w WHERE w.name = 'Crise de Suez'
