INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1956-11-06', 'day', 'Cessez-le-feu', 'Ceasefire', 'Le jour même du débarquement à Port-Saïd, Anthony Eden annonce le cessez-le-feu, qui entre en vigueur dans la nuit.', 'On the very day of the Port Said landings, Anthony Eden announces the ceasefire, which takes effect that night.', NULL::int, 'https://en.wikipedia.org/wiki/Suez_Crisis' FROM wars w WHERE w.name = 'Crise de Suez'
