INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1983-07-23', 'day', 'Embuscade de Thirunelveli et « Juillet noir »', 'Thirunelveli ambush and "Black July"', 'Les Tigres tendent une embuscade à une patrouille de l’armée près de Jaffna ; elle sert de prétexte au pogrom anti-tamoul de Colombo, début de la guerre.', 'The Tigers ambushed an army patrol near Jaffna; it became the pretext for the anti-Tamil pogrom in Colombo and marks the start of the war.', NULL::int, 'https://en.wikipedia.org/wiki/Sri_Lankan_Civil_War' FROM wars w WHERE w.name = 'Guerre civile du Sri Lanka'
