INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'haftar', 1, 'Camp de Haftar', 'Haftar’s camp', 'Armée nationale libyenne du maréchal Khalifa Haftar et Chambre des représentants de Tobrouk ; soutiens : Émirats arabes unis, Égypte, Russie (groupe Wagner)', 'Field Marshal Khalifa Haftar’s Libyan National Army and the Tobruk House of Representatives; backers: United Arab Emirates, Egypt, Russia (Wagner Group)' FROM wars w WHERE w.name = 'Guerre civile libyenne (2014-2020)'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'tripoli', 2, 'Gouvernements de Tripoli', 'Tripoli governments', 'Coalition *Aube de la Libye* et Congrès général national (2014-2016), puis gouvernement d’union nationale de Fayez el-Sarraj ; soutiens : Turquie, Qatar', '*Libya Dawn* coalition and General National Congress (2014-2016), then Fayez al-Sarraj’s Government of National Accord; backers: Turkey, Qatar' FROM wars w WHERE w.name = 'Guerre civile libyenne (2014-2020)'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'etats-unis', 3, 'États-Unis', 'United States', 'États-Unis : frappes contre l’État islamique et Al-Qaïda au Maghreb islamique, en appui du gouvernement d’union nationale à Syrte en 2016', 'United States: strikes against the Islamic State and al-Qaeda in the Islamic Maghreb, supporting the Government of National Accord at Sirte in 2016' FROM wars w WHERE w.name = 'Guerre civile libyenne (2014-2020)'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
