INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'salvador', 1, 'Gouvernement salvadorien', 'Salvadoran government', 'Forces armées du Salvador (dont la Fuerza Aérea Salvadoreña), soutenues par les États-Unis', 'Armed Forces of El Salvador (including the Salvadoran Air Force), backed by the United States' FROM wars w WHERE w.name = 'Guerre civile salvadorienne'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'fmln', 2, 'FMLN', 'FMLN', 'Front Farabundo Martí de libération nationale (FPL, ERP, RN, PCS, PRTC), soutenu par Cuba, le Nicaragua et l’Union soviétique', 'Farabundo Martí National Liberation Front (FPL, ERP, RN, PCS, PRTC), backed by Cuba, Nicaragua and the Soviet Union' FROM wars w WHERE w.name = 'Guerre civile salvadorienne'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
