INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'regime-allies', 1, 'Régime syrien et alliés', 'Syrian regime and allies', 'Syrie (régime Assad, jusqu''en décembre 2024), Russie, Iran, Hezbollah', 'Syria (Assad regime, until December 2024), Russia, Iran, Hezbollah' FROM wars w WHERE w.name = 'Guerre civile syrienne'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'coalition', 2, 'Coalition contre l''État islamique', 'Coalition against ISIS', 'États-Unis, Royaume-Uni, France, Australie, Canada, Allemagne, Pays-Bas, Belgique, Danemark, Jordanie, Arabie saoudite, Émirats arabes unis, Bahreïn, Qatar… (les États-Unis, le Royaume-Uni et la France frappent aussi le régime en 2017-2018)', 'United States, United Kingdom, France, Australia, Canada, Germany, Netherlands, Belgium, Denmark, Jordan, Saudi Arabia, United Arab Emirates, Bahrain, Qatar… (the US, UK and France also struck the regime in 2017–2018)' FROM wars w WHERE w.name = 'Guerre civile syrienne'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'israel', 3, 'Israël', 'Israel', 'Israël', 'Israel' FROM wars w WHERE w.name = 'Guerre civile syrienne'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'turquie', 4, 'Turquie', 'Turkey', 'Turquie et Armée nationale syrienne', 'Turkey and the Syrian National Army' FROM wars w WHERE w.name = 'Guerre civile syrienne'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
