UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Pendant la bataille de Kobané, le 9e escadron de B-1B largue environ 660 bombes, un tiers de celles qu''il largue en cinq mois. Le 14 avril 2018, des B-1B tirent 19 missiles JASSM sur le centre de Barzeh, à Damas ; le 2 février 2024, ils frappent des milices pro-iraniennes.', role_en = 'During the battle of Kobani, the 9th Bomb Squadron''s B-1Bs dropped about 660 bombs, a third of all those they dropped in five months. On 14 April 2018 B-1Bs fired 19 JASSMs at the Barzah centre in Damascus; on 2 February 2024 they struck pro-Iranian militias.', sources = 'https://www.airforcetimes.com/news/your-air-force/2015/08/23/inside-the-b-1-crew-that-pounded-isis-with-1800-bombs/
