UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Les F-15E frappent dès la première nuit en Syrie, puis abattent deux drones armés pro-régime près d''Al-Tanf, les 8 et 20 juin 2017. Ils frappent à Khasham en février 2018, contre plus de 75 cibles de l''EI le 8 décembre 2024 et lors de *Hawkeye Strike* en 2025-2026.', role_en = 'F-15Es struck on the first night in Syria, then shot down two armed pro-regime drones near al-Tanf on 8 and 20 June 2017. They struck at Khasham in February 2018, hit more than 75 ISIS targets on 8 December 2024 and flew in *Hawkeye Strike* in 2025–2026.', sources = 'https://www.centcom.mil/MEDIA/NEWS-ARTICLES/News-Article-View/Article/1219859/coalition-shoots-down-armed-uav-in-syria/
https://theaviationist.com/2017/06/09/u-s-f-15e-downs-iranian-built-syrian-drone-after-airstrike-on-u-s-led-forces/
