INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2012-07-24', 'day', 'Premières attaques d''avions du régime', 'First regime fixed-wing attacks', 'Des L-39 d''entraînement attaquent les insurgés à la roquette, à la bombe et au canon : après les hélicoptères, l''aviation à réaction du régime entre dans la guerre.', 'L-39 trainers attack insurgents with rockets, bombs and guns: after the helicopters, the regime’s jets enter the war.', (SELECT id FROM airplanes WHERE name = 'Aero L-39 Albatros'), 'https://en.wikipedia.org/wiki/Syrian_Arab_Air_Force' FROM wars w WHERE w.name = 'Guerre civile syrienne'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
