INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'coalition-saoudienne', 1, 'Coalition menée par l''Arabie saoudite', 'Saudi-led coalition', 'Arabie saoudite, Émirats arabes unis (fin de mission annoncée en décembre 2025), Bahreïn, Koweït, Qatar, Jordanie, Maroc (2015-2019), Égypte, Soudan, aux côtés du gouvernement yéménite reconnu', 'Saudi Arabia, United Arab Emirates (end of mission announced in December 2025), Bahrain, Kuwait, Qatar, Jordan, Morocco (2015–2019), Egypt, Sudan, alongside Yemen''s recognised government' FROM wars w WHERE w.name = 'Guerre civile yéménite'
