UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-royaume-uni'), role = 'Partis de Whiteman (Missouri), des B-2 frappent le 16 octobre 2024 cinq dépôts d''armes souterrains des Houthis, leur premier combat depuis 2017 ; au printemps 2025, ceux déployés à Diego Garcia (six au moins) participent à *Rough Rider*.', role_en = 'Flying from Whiteman, Missouri, B-2s struck five underground Houthi weapons stores on 16 October 2024, their first combat since 2017; in spring 2025, those deployed to Diego Garcia (at least six) took part in *Rough Rider*.', sources = 'https://www.aljazeera.com/news/2024/10/17/us-says-b2-bombers-launched-precision-strikes-against-houthis-in-yemen
https://www.twz.com/air/b-2-spirits-deployed-to-diego-garcia-have-been-striking-houthi-targets-in-yemen
https://www.airandspaceforces.com/1000-targets-trump-campaign-houthi-centcom/'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'B-2 Spirit' AND w.name = 'Guerre civile yéménite'
