UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition-saoudienne'), role = 'Les Wing Loong des Émirats et de l''Arabie saoudite surveillent et frappent les Houthis ; une frappe de drone attribuée à un Wing Loong tue Saleh al-Sammad, chef politique houthi, en avril 2018. Les Houthis en revendiquent plusieurs abattus, de septembre 2016 à avril 2024.', role_en = 'Emirati and Saudi Wing Loongs watched and struck the Houthis; a drone strike attributed to a Wing Loong killed Houthi political leader Saleh al-Sammad in April 2018. The Houthis claimed several shot down, from September 2016 to April 2024.', sources = 'https://en.wikipedia.org/wiki/CAIG_Wing_Loong
