INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2014-09-21', 'day', 'Les Houthis maîtres de Sanaa', 'The Houthis take Sanaa', 'Après des combats qui font des centaines de morts dans la capitale, un accord signé avec le gouvernement livre de fait Sanaa aux Houthis ; le Premier ministre démissionne.', 'After fighting that kills hundreds in the capital, an agreement signed with the government effectively hands Sanaa to the Houthis; the prime minister resigns.', NULL::int, 'https://fr.wikipedia.org/wiki/Guerre_civile_y%C3%A9m%C3%A9nite' FROM wars w WHERE w.name = 'Guerre civile yéménite'
