INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'portugal', 1, 'Portugal', 'Portugal', 'Força Aérea Portuguesa (dont les troupes parachutistes), Armée de terre et Marine portugaises, avec de nombreux soldats recrutés sur place', 'Portuguese Air Force (including its paratroopers), Portuguese Army and Navy, with many locally recruited soldiers' FROM wars w WHERE w.name = 'Guerre coloniale portugaise'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'independantistes', 2, 'Mouvements indépendantistes', 'Independence movements', 'MPLA, FNLA (ex-UPA) et UNITA en Angola, PAIGC en Guinée, FRELIMO au Mozambique, sans aviation', 'MPLA, FNLA (formerly UPA) and UNITA in Angola, PAIGC in Guinea, FRELIMO in Mozambique, with no air arm' FROM wars w WHERE w.name = 'Guerre coloniale portugaise'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
