INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'coalition', 1, 'Coalition internationale et Irak', 'International coalition and Iraq', 'États-Unis, Royaume-Uni, France, Australie, Canada, Allemagne, Italie, Pays-Bas, Belgique, Danemark, Jordanie, Arabie saoudite, Émirats arabes unis, Bahreïn, Qatar, Irak (armée et peshmergas kurdes), Forces démocratiques syriennes ; la Syrie rejoint la coalition en novembre 2025', 'United States, United Kingdom, France, Australia, Canada, Germany, Italy, Netherlands, Belgium, Denmark, Jordan, Saudi Arabia, United Arab Emirates, Bahrain, Qatar, Iraq (army and Kurdish Peshmerga), Syrian Democratic Forces; Syria joined the coalition in November 2025' FROM wars w WHERE w.name = 'Guerre contre l''État islamique'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre contre l''État islamique' AND s.side_key NOT IN ('coalition');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Livrés à l''Irak à partir du 5 novembre 2015, les L-159 du 115e escadron frappent l''EI à Falloujah en mai 2016, puis aux abords sud de Mossoul en octobre-novembre 2016 ; remisés vers 2017-2018, ils reprennent fin 2021 des frappes à la bombe non guidée contre des repaires de l''EI.', role_en = 'Delivered to Iraq from 5 November 2015, No. 115 Squadron''s L-159s struck ISIS at Fallujah in May 2016, then on the southern outskirts of Mosul in October–November 2016; stored around 2017–2018, they resumed strikes with unguided bombs against ISIS hideouts from late 2021.', sources = 'https://en.wikipedia.org/wiki/Aero_L-159_Alca
