UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Deux Rafale signent le 19 septembre 2014 la première frappe française, au sud de Mossoul ; basés aux Émirats, en Jordanie ou sur le *Charles-de-Gaulle*, ils frappent la Syrie à partir du 27 septembre 2015 et visent encore deux objectifs de l''EI dans le centre de la Syrie le 29 décembre 2024.', role_en = 'Two Rafales flew the first French strike, south of Mosul, on 19 September 2014; based in the UAE, Jordan or aboard the *Charles de Gaulle*, they struck Syria from 27 September 2015 and were still hitting two ISIS targets in central Syria on 29 December 2024.', sources = 'https://fr.wikipedia.org/wiki/Op%C3%A9ration_Chammal'
  FROM airplanes a, wars w
