INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2014-08-08', 'day', 'Premières frappes américaines près d''Erbil', 'First US strikes near Erbil', 'Deux F/A-18 du porte-avions *George H.W. Bush* détruisent une pièce d''artillerie de l''EI qui pilonne les défenseurs kurdes d''Erbil : la campagne aérienne commence.', 'Two F/A-18s from the carrier *George H.W. Bush* destroy an ISIS artillery piece shelling Erbil''s Kurdish defenders: the air campaign begins.', NULL::int, 'https://www.pbs.org/newshour/politics/pentagon-u-s-launches-first-airstrikes-iraq' FROM wars w WHERE w.name = 'Guerre contre l''État islamique'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2014-09-19', 'day', 'Première frappe française', 'First French strike', 'Deux Rafale, soutenus par un ravitailleur et un Atlantique 2, détruisent un dépôt logistique de l''EI au sud de Mossoul : l''opération *Chammal* entre dans sa phase offensive.', 'Two Rafales, supported by a tanker and an Atlantique 2, destroy an ISIS logistics depot south of Mosul: Operation *Chammal* goes on the offensive.', (SELECT id FROM airplanes WHERE name = 'Rafale'), 'https://fr.wikipedia.org/wiki/Op%C3%A9ration_Chammal' FROM wars w WHERE w.name = 'Guerre contre l''État islamique'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
