INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'coalition', 1, 'Coalition et gouvernement afghan', 'Coalition and Afghan government', 'États-Unis, Royaume-Uni, France, Allemagne, Italie, Canada, Pays-Bas, Belgique, Danemark, Norvège, Australie et les autres pays de l''OTAN et de la FIAS (51 pays), Alliance du Nord puis République islamique d''Afghanistan', 'United States, United Kingdom, France, Germany, Italy, Canada, the Netherlands, Belgium, Denmark, Norway, Australia and the other NATO and ISAF nations (51 countries), the Northern Alliance and then the Islamic Republic of Afghanistan' FROM wars w WHERE w.name = 'Guerre d''Afghanistan'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'talibans', 2, 'Talibans et al-Qaïda', 'Taliban and al-Qaeda', 'Émirat islamique d''Afghanistan (talibans), al-Qaïda et groupes insurgés alliés', 'Islamic Emirate of Afghanistan (Taliban), al-Qaeda and allied insurgent groups' FROM wars w WHERE w.name = 'Guerre d''Afghanistan'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre d''Afghanistan' AND s.side_key NOT IN ('coalition', 'talibans');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Engagés pendant *Anaconda* en mars 2002, mieux protégés que les hélicoptères contre les tirs du sol, les A-10 s''installent ensuite à Bagram et y assurent pendant des années l''appui aérien rapproché, renforcé lors des offensives d''été.', role_en = 'Committed during *Anaconda* in March 2002, and better protected than helicopters against ground fire, A-10s then moved to Bagram and provided close air support from there for years, surging for the summer offensives.', sources = 'https://www2.ljworld.com/news/2002/mar/25/a10_thunderbolt_ii_jets/
https://www.af.mil/News/Article-Display/Article/130023/bagram-a-10s-surge-for-summer-offensives/'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'A-10 Thunderbolt II' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Engagés pendant *Anaconda* en mars 2002, mieux protégés que les hélicoptères contre les tirs du sol, les A-10 s''installent ensuite à Bagram et y assurent pendant des années l''appui aérien rapproché, renforcé lors des offensives d''été.', 'Committed during *Anaconda* in March 2002, and better protected than helicopters against ground fire, A-10s then moved to Bagram and provided close air support from there for years, surging for the summer offensives.', 'https://www2.ljworld.com/news/2002/mar/25/a10_thunderbolt_ii_jets/
https://www.af.mil/News/Article-Display/Article/130023/bagram-a-10s-surge-for-summer-offensives/');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Les AC-130 frappent dès octobre 2001 (objectif Rhino, Kunduz, révolte de Qala-i-Jangi) et appuient les forces spéciales pendant *Anaconda*. Le 3 octobre 2015, un AC-130U détruit par erreur l''hôpital de Médecins sans frontières de Kunduz : 42 morts selon l''ONG.', role_en = 'AC-130s struck from October 2001 (Objective Rhino, Kunduz, the Qala-i-Jangi uprising) and supported special forces during *Anaconda*. On 3 October 2015 an AC-130U mistakenly destroyed the Médecins Sans Frontières hospital in Kunduz: 42 dead according to the charity.', sources = 'https://en.wikipedia.org/wiki/United_States_invasion_of_Afghanistan
https://www.airandspaceforces.com/article/0202enduring/
https://en.wikipedia.org/wiki/Operation_Anaconda
https://www.msf.org/kunduz-hospital-attack-depth'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'AC-130 Spectre' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Les AC-130 frappent dès octobre 2001 (objectif Rhino, Kunduz, révolte de Qala-i-Jangi) et appuient les forces spéciales pendant *Anaconda*. Le 3 octobre 2015, un AC-130U détruit par erreur l''hôpital de Médecins sans frontières de Kunduz : 42 morts selon l''ONG.', 'AC-130s struck from October 2001 (Objective Rhino, Kunduz, the Qala-i-Jangi uprising) and supported special forces during *Anaconda*. On 3 October 2015 an AC-130U mistakenly destroyed the Médecins Sans Frontières hospital in Kunduz: 42 dead according to the charity.', 'https://en.wikipedia.org/wiki/United_States_invasion_of_Afghanistan
https://www.airandspaceforces.com/article/0202enduring/
https://en.wikipedia.org/wiki/Operation_Anaconda
https://www.msf.org/kunduz-hospital-attack-depth');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Quatre AMX italiens remplacent les Tornado en novembre 2009 et opèrent dans l''ouest du pays jusqu''en juin 2014 : reconnaissance, analyse de quelque 1 300 objectifs dès 2010 et frappes, comme la destruction de relais radio talibans dans les districts de Bakwa et Gulistan.', role_en = 'Four Italian AMXs replaced the Tornados in November 2009 and operated in the west of the country until June 2014: reconnaissance, analysis of some 1,300 targets by 2010, and strikes such as the destruction of Taliban radio relays in the Bakwa and Gulistan districts.', sources = 'https://aviationnews.eu/news/2009/11/italian-amxs-head-to-afghanistan-on-november-4/
https://www.aeronautica.difesa.it/en/news/afghanistan-amx-distruggono-antenne-dei-ribelli/
https://archivio.blitzquotidiano.it/cronaca-mondo/afghanistan-ultima-missione-quattro-amx-1880162'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'AMX International AMX' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Quatre AMX italiens remplacent les Tornado en novembre 2009 et opèrent dans l''ouest du pays jusqu''en juin 2014 : reconnaissance, analyse de quelque 1 300 objectifs dès 2010 et frappes, comme la destruction de relais radio talibans dans les districts de Bakwa et Gulistan.', 'Four Italian AMXs replaced the Tornados in November 2009 and operated in the west of the country until June 2014: reconnaissance, analysis of some 1,300 targets by 2010, and strikes such as the destruction of Taliban radio relays in the Bakwa and Gulistan districts.', 'https://aviationnews.eu/news/2009/11/italian-amxs-head-to-afghanistan-on-november-4/
https://www.aeronautica.difesa.it/en/news/afghanistan-amx-distruggono-antenne-dei-ribelli/
https://archivio.blitzquotidiano.it/cronaca-mondo/afghanistan-ultima-missione-quattro-amx-1880162');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Les Harrier des Marines rejoignent les frappes dès novembre 2001, puis opèrent depuis Camp Bastion, où un raid taliban détruit six AV-8B du VMA-211 le 14 septembre 2012. Les AV-8B italiens du *Garibaldi* volent aussi en 2001-2002.', role_en = 'Marine Harriers joined the strikes in November 2001, then operated from Camp Bastion, where a Taliban raid destroyed six VMA-211 AV-8Bs on 14 September 2012. Italian AV-8Bs from the *Garibaldi* also flew in 2001-2002.', sources = 'https://www.globalsecurity.org/military/library/news/2001/11/mil-011104-usmc1.htm
https://www.airandspaceforces.com/article/0202enduring/
https://en.wikipedia.org/wiki/September_2012_raid_on_Camp_Bastion
https://en.wikipedia.org/wiki/Italian_aircraft_carrier_Giuseppe_Garibaldi
https://www.strategypage.com/qnd/afghan/articles/20020215.aspx'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'AV-8B Harrier II' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Les Harrier des Marines rejoignent les frappes dès novembre 2001, puis opèrent depuis Camp Bastion, où un raid taliban détruit six AV-8B du VMA-211 le 14 septembre 2012. Les AV-8B italiens du *Garibaldi* volent aussi en 2001-2002.', 'Marine Harriers joined the strikes in November 2001, then operated from Camp Bastion, where a Taliban raid destroyed six VMA-211 AV-8Bs on 14 September 2012. Italian AV-8Bs from the *Garibaldi* also flew in 2001-2002.', 'https://www.globalsecurity.org/military/library/news/2001/11/mil-011104-usmc1.htm
https://www.airandspaceforces.com/article/0202enduring/
https://en.wikipedia.org/wiki/September_2012_raid_on_Camp_Bastion
https://en.wikipedia.org/wiki/Italian_aircraft_carrier_Giuseppe_Garibaldi
https://www.strategypage.com/qnd/afghan/articles/20020215.aspx');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Lancé à la main par les fantassins, il sert au niveau de la compagnie : en 2010, dans la province de Khost, des soldats du 1-187th Infantry l''envoient repérer les tireurs de mortier après une attaque contre la FOB Boris. Les Danois l''emploient aussi dans le Helmand.', role_en = 'Hand-launched by infantrymen, it served at company level: in 2010 in Khost province, soldiers of the 1-187th Infantry flew it to spot the mortar crews behind an attack on FOB Boris. Danish troops also used it in Helmand.', sources = 'https://www.army.mil/article/45399/rpa_provides_soldiers_birds_eye_view_of_battlefield
https://en.wikipedia.org/wiki/AeroVironment_RQ-11_Raven'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'AeroVironment RQ-11 Raven' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Lancé à la main par les fantassins, il sert au niveau de la compagnie : en 2010, dans la province de Khost, des soldats du 1-187th Infantry l''envoient repérer les tireurs de mortier après une attaque contre la FOB Boris. Les Danois l''emploient aussi dans le Helmand.', 'Hand-launched by infantrymen, it served at company level: in 2010 in Khost province, soldiers of the 1-187th Infantry flew it to spot the mortar crews behind an attack on FOB Boris. Danish troops also used it in Helmand.', 'https://www.army.mil/article/45399/rpa_provides_soldiers_birds_eye_view_of_battlefield
https://en.wikipedia.org/wiki/AeroVironment_RQ-11_Raven');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Munition rôdeuse fournie en urgence : 75 exemplaires livrés fin 2012 aux soldats américains, jugés « très efficaces » contre les équipes de poseurs d''engins piégés et de mortiers ; plus de 4 000 sont déployés en Afghanistan jusqu''à la fin d''*Enduring Freedom*.', role_en = 'A rush-fielded loitering munition: 75 were supplied to US soldiers in late 2012 and judged "very effective" against IED and mortar teams; more than 4,000 were deployed in Afghanistan by the end of *Enduring Freedom*.', sources = 'https://en.wikipedia.org/wiki/AeroVironment_Switchblade'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'AeroVironment Switchblade' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Munition rôdeuse fournie en urgence : 75 exemplaires livrés fin 2012 aux soldats américains, jugés « très efficaces » contre les équipes de poseurs d''engins piégés et de mortiers ; plus de 4 000 sont déployés en Afghanistan jusqu''à la fin d''*Enduring Freedom*.', 'A rush-fielded loitering munition: 75 were supplied to US soldiers in late 2012 and judged "very effective" against IED and mortar teams; more than 4,000 were deployed in Afghanistan by the end of *Enduring Freedom*.', 'https://en.wikipedia.org/wiki/AeroVironment_Switchblade');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Lors de l''évacuation d''août 2021, les Voyager de la RAF ramènent les évacués du Golfe vers le Royaume-Uni (370 dès le 16 août), un KC-30A australien ravitaille en huit sorties les chasseurs qui couvrent Kaboul et le KC-330 sud-coréen participe à l''opération *Miracle*.', role_en = 'During the August 2021 evacuation, RAF Voyagers flew evacuees from the Gulf to Britain (370 on 16 August), an Australian KC-30A refuelled the fighters covering Kabul in eight sorties, and South Korea''s KC-330 joined Operation *Miracle*.', sources = 'https://en.wikipedia.org/wiki/Operation_Pitting
https://www.defence.gov.au/news-events/news/2021-09-10/adf-plays-vital-role-humanitarian-airlift
https://en.wikipedia.org/wiki/Airbus_A330_MRTT'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Airbus A330 MRTT' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Lors de l''évacuation d''août 2021, les Voyager de la RAF ramènent les évacués du Golfe vers le Royaume-Uni (370 dès le 16 août), un KC-30A australien ravitaille en huit sorties les chasseurs qui couvrent Kaboul et le KC-330 sud-coréen participe à l''opération *Miracle*.', 'During the August 2021 evacuation, RAF Voyagers flew evacuees from the Gulf to Britain (370 on 16 August), an Australian KC-30A refuelled the fighters covering Kabul in eight sorties, and South Korea''s KC-330 joined Operation *Miracle*.', 'https://en.wikipedia.org/wiki/Operation_Pitting
https://www.defence.gov.au/news-events/news/2021-09-10/adf-plays-vital-role-humanitarian-airlift
https://en.wikipedia.org/wiki/Airbus_A330_MRTT');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Pilier européen du pont aérien d''août 2021 : la Luftwaffe évacue 5 347 personnes de Kaboul vers Tachkent en 37 vols (avec ses A310), la RAF en assure 31 vols, l''armée de l''air française l''engage dans l''opération *Apagan* et la Belgique et le Luxembourg via Islamabad.', role_en = 'The European backbone of the August 2021 airlift: the Luftwaffe flew 5,347 people from Kabul to Tashkent in 37 flights (with its A310s), the RAF flew 31 A400M flights, France used it in Operation *Apagan*, and Belgium and Luxembourg via Islamabad.', sources = 'https://www.bundeswehr.de/de/meldungen/evakuierung-afghanistan
https://en.wikipedia.org/wiki/Operation_Pitting
https://key.aero/article/how-france-readied-its-airbus-a400m-fleet-war
https://gouvernement.lu/fr/actualites/toutes_actualites/communiques/2021/08-aout/19-a400m-afghanistan.html'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Airbus A400M Atlas' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Pilier européen du pont aérien d''août 2021 : la Luftwaffe évacue 5 347 personnes de Kaboul vers Tachkent en 37 vols (avec ses A310), la RAF en assure 31 vols, l''armée de l''air française l''engage dans l''opération *Apagan* et la Belgique et le Luxembourg via Islamabad.', 'The European backbone of the August 2021 airlift: the Luftwaffe flew 5,347 people from Kabul to Tashkent in 37 flights (with its A310s), the RAF flew 31 A400M flights, France used it in Operation *Apagan*, and Belgium and Luxembourg via Islamabad.', 'https://www.bundeswehr.de/de/meldungen/evakuierung-afghanistan
https://en.wikipedia.org/wiki/Operation_Pitting
https://key.aero/article/how-france-readied-its-airbus-a400m-fleet-war
https://gouvernement.lu/fr/actualites/toutes_actualites/communiques/2021/08-aout/19-a400m-afghanistan.html');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Deux C-27J italiens assurent le transport intra-théâtre de l''OTAN de septembre 2008 à janvier 2009. Puis, d''août 2011 à juin 2012, la Garde nationale américaine en déploie à Kandahar : plus de 3 200 missions, 25 000 passagers et 1 400 t de fret.', role_en = 'Two Italian C-27Js flew NATO in-theatre airlift from September 2008 to January 2009. From August 2011 to June 2012 the US Air National Guard flew them from Kandahar: over 3,200 missions, 25,000 passengers and 1,400 tons of cargo.', sources = 'https://en.wikipedia.org/wiki/Alenia_C-27J_Spartan'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Alenia C-27J Spartan' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Deux C-27J italiens assurent le transport intra-théâtre de l''OTAN de septembre 2008 à janvier 2009. Puis, d''août 2011 à juin 2012, la Garde nationale américaine en déploie à Kandahar : plus de 3 200 missions, 25 000 passagers et 1 400 t de fret.', 'Two Italian C-27Js flew NATO in-theatre airlift from September 2008 to January 2009. From August 2011 to June 2012 the US Air National Guard flew them from Kandahar: over 3,200 missions, 25,000 passengers and 1,400 tons of cargo.', 'https://en.wikipedia.org/wiki/Alenia_C-27J_Spartan');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Affrétés par l''OTAN dans le cadre du contrat SALIS (2006), des An-124 de Volga-Dnepr et d''Antonov Airlines relient chaque semaine l''Allemagne à l''Afghanistan ; en 2021, la Bundeswehr en emploie pour rapatrier son matériel lors du retrait.', role_en = 'Chartered by NATO under the SALIS contract (2006), An-124s of Volga-Dnepr and Antonov Airlines flew weekly between Germany and Afghanistan; in 2021 the Bundeswehr used them to bring its equipment home during the withdrawal.', sources = 'https://www.flightglobal.com/russian-ukrainian-partnership-to-provide-an-124s-for-nato-duty/66494.article
https://www.nato.int/cps/en/natohq/topics_50107.htm
https://www.bundeswehr.de/de/meldungen/an-124-gelandet-heisse-abzug-afghanistan-begonnen-5083608'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Antonov An-124 Ruslan' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Affrétés par l''OTAN dans le cadre du contrat SALIS (2006), des An-124 de Volga-Dnepr et d''Antonov Airlines relient chaque semaine l''Allemagne à l''Afghanistan ; en 2021, la Bundeswehr en emploie pour rapatrier son matériel lors du retrait.', 'Chartered by NATO under the SALIS contract (2006), An-124s of Volga-Dnepr and Antonov Airlines flew weekly between Germany and Afghanistan; in 2021 the Bundeswehr used them to bring its equipment home during the withdrawal.', 'https://www.flightglobal.com/russian-ukrainian-partnership-to-provide-an-124s-for-nato-duty/66494.article
https://www.nato.int/cps/en/natohq/topics_50107.htm
https://www.bundeswehr.de/de/meldungen/an-124-gelandet-heisse-abzug-afghanistan-begonnen-5083608');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Huit B-1B de Diego Garcia détruisent d''abord les objectifs fixes, puis passent à l''appui des troupes au sol dès fin octobre 2001 ; avec 4 % des sorties, ils larguent 2 800 JDAM, plus que tous les autres avions réunis selon Flight. Un B-1B s''abîme en mer près de Diego Garcia le 12 décembre 2001.', role_en = 'Eight B-1Bs from Diego Garcia first destroyed fixed targets, then switched to ground support by late October 2001; with 4 per cent of sorties they dropped 2,800 JDAMs, more than all other aircraft combined according to Flight. A B-1B crashed into the sea off Diego Garcia on 12 December 2001.', sources = 'https://www.flightglobal.com/ageing-aircraft-prove-their-worth/45870.article
https://www.ellsworth.af.mil/News/Features/Display/Article/217603/bones-over-southwest-asia-part-iii
https://www.airandspaceforces.com/this-day-in-airpower/december-12-2001'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'B-1 Lancer' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Huit B-1B de Diego Garcia détruisent d''abord les objectifs fixes, puis passent à l''appui des troupes au sol dès fin octobre 2001 ; avec 4 % des sorties, ils larguent 2 800 JDAM, plus que tous les autres avions réunis selon Flight. Un B-1B s''abîme en mer près de Diego Garcia le 12 décembre 2001.', 'Eight B-1Bs from Diego Garcia first destroyed fixed targets, then switched to ground support by late October 2001; with 4 per cent of sorties they dropped 2,800 JDAMs, more than all other aircraft combined according to Flight. A B-1B crashed into the sea off Diego Garcia on 12 December 2001.', 'https://www.flightglobal.com/ageing-aircraft-prove-their-worth/45870.article
https://www.ellsworth.af.mil/News/Features/Display/Article/217603/bones-over-southwest-asia-part-iii
https://www.airandspaceforces.com/this-day-in-airpower/december-12-2001');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Aux premiers jours d''*Enduring Freedom*, en octobre 2001, des B-2 décollent de Whiteman (Missouri) pour frapper des cibles en Afghanistan et rentrer sans escale, ravitaillés en vol : l''une de leurs plus longues missions.', role_en = 'In the opening days of *Enduring Freedom* in October 2001, B-2s flew from Whiteman, Missouri, to strike targets in Afghanistan and back non-stop with aerial refuelling, one of the type''s longest missions.', sources = 'https://en.wikipedia.org/wiki/Northrop_B-2_Spirit'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'B-2 Spirit' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Aux premiers jours d''*Enduring Freedom*, en octobre 2001, des B-2 décollent de Whiteman (Missouri) pour frapper des cibles en Afghanistan et rentrer sans escale, ravitaillés en vol : l''une de leurs plus longues missions.', 'In the opening days of *Enduring Freedom* in October 2001, B-2s flew from Whiteman, Missouri, to strike targets in Afghanistan and back non-stop with aerial refuelling, one of the type''s longest missions.', 'https://en.wikipedia.org/wiki/Northrop_B-2_Spirit');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Dix B-52H basés à Diego Garcia frappent dès octobre 2001 avec bombes Mk 82 et JDAM. Le 5 novembre, un B-52 appuie la charge de cavalerie de Dostom à Baluch ; le 5 décembre, une JDAM tombée trop près tue trois Bérets verts et cinq Afghans.', role_en = 'Ten B-52Hs based on Diego Garcia struck from October 2001 with Mk 82 bombs and JDAMs. On 5 November a B-52 supported Dostum''s cavalry charge at Baluch; on 5 December a JDAM that fell short killed three Green Berets and five Afghans.', sources = 'https://www.airandspaceforces.com/article/0202enduring/
https://en.wikipedia.org/wiki/United_States_invasion_of_Afghanistan'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'B-52 Stratofortress' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Dix B-52H basés à Diego Garcia frappent dès octobre 2001 avec bombes Mk 82 et JDAM. Le 5 novembre, un B-52 appuie la charge de cavalerie de Dostom à Baluch ; le 5 décembre, une JDAM tombée trop près tue trois Bérets verts et cinq Afghans.', 'Ten B-52Hs based on Diego Garcia struck from October 2001 with Mk 82 bombs and JDAMs. On 5 November a B-52 supported Dostum''s cavalry charge at Baluch; on 5 December a JDAM that fell short killed three Green Berets and five Afghans.', 'https://www.airandspaceforces.com/article/0202enduring/
https://en.wikipedia.org/wiki/United_States_invasion_of_Afghanistan');
