UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Loué à partir de juillet 2007 par l''armée britannique (32nd Regiment Royal Artillery), il vole depuis Camp Bastion, jusqu''à neuf appareils et cinq vols par jour, et dépasse 70 000 heures au-dessus de l''Afghanistan en 2013 avant d''être relevé par le Watchkeeper en 2014.', role_en = 'Leased by the British Army (32nd Regiment Royal Artillery) from July 2007, it flew from Camp Bastion, up to nine aircraft and five flights a day, passing 70,000 hours over Afghanistan in 2013 before Watchkeeper took over in 2014.', sources = 'https://en.wikipedia.org/wiki/Elbit_Hermes_450'
