UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Avion de renseignement des forces spéciales de l''US Air Force, engagé à partir de juin 2006. En août 2021, un détachement basé à l''aéroport de Kaboul surveille sans relâche la foule et l''approche des talibans pendant l''évacuation, sous le feu.', role_en = 'The US Air Force special operations ISR aircraft, in combat from June 2006. In August 2021 a detachment at Kabul airport kept constant watch over the crowds and approaching Taliban during the evacuation, under fire.', sources = 'https://en.wikipedia.org/wiki/Pilatus_U-28_Draco'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Pilatus U-28A Draco' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Avion de renseignement des forces spéciales de l''US Air Force, engagé à partir de juin 2006. En août 2021, un détachement basé à l''aéroport de Kaboul surveille sans relâche la foule et l''approche des talibans pendant l''évacuation, sous le feu.', 'The US Air Force special operations ISR aircraft, in combat from June 2006. In August 2021 a detachment at Kabul airport kept constant watch over the crowds and approaching Taliban during the evacuation, under fire.', 'https://en.wikipedia.org/wiki/Pilatus_U-28_Draco');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Encore au stade de prototype, il est engagé dès novembre 2001 pour la reconnaissance à haute altitude au-dessus de l''Afghanistan ; une version de relais de communications (EQ-4B) s''écrase près de Jalalabad le 21 août 2011.', role_en = 'Still a developmental prototype, it was committed from November 2001 to high-altitude reconnaissance over Afghanistan; a communications-relay EQ-4B crashed near Jalalabad on 21 August 2011.', sources = 'https://en.wikipedia.org/wiki/Northrop_Grumman_RQ-4_Global_Hawk'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'RQ-4 Global Hawk' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Encore au stade de prototype, il est engagé dès novembre 2001 pour la reconnaissance à haute altitude au-dessus de l''Afghanistan ; une version de relais de communications (EQ-4B) s''écrase près de Jalalabad le 21 août 2011.', 'Still a developmental prototype, it was committed from November 2001 to high-altitude reconnaissance over Afghanistan; a communications-relay EQ-4B crashed near Jalalabad on 21 August 2011.', 'https://en.wikipedia.org/wiki/Northrop_Grumman_RQ-4_Global_Hawk');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Trois compagnies de l''US Army l''emploient en rotation en Irak puis en Afghanistan ; à Kandahar, la Task Force Copperhead l''équipe d''un radar miniature pour détecter les engins piégés au profit des forces de la coalition et afghanes.', role_en = 'Three US Army companies rotated it through Iraq and then Afghanistan; at Kandahar, Task Force Copperhead fitted it with a miniature radar to detect roadside bombs for coalition and Afghan forces.', sources = 'https://www.army.mil/article/56711/pioneer_platform_soars_to_battlefield_success
https://www.dvidshub.net/image/2133600/uav-mq-5b-hunter-launch-and-recovery-kandahar-airfield
https://en.wikipedia.org/wiki/IAI_RQ-5_Hunter'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'RQ-5 Hunter' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Trois compagnies de l''US Army l''emploient en rotation en Irak puis en Afghanistan ; à Kandahar, la Task Force Copperhead l''équipe d''un radar miniature pour détecter les engins piégés au profit des forces de la coalition et afghanes.', 'Three US Army companies rotated it through Iraq and then Afghanistan; at Kandahar, Task Force Copperhead fitted it with a miniature radar to detect roadside bombs for coalition and Afghan forces.', 'https://www.army.mil/article/56711/pioneer_platform_soars_to_battlefield_success
https://www.dvidshub.net/image/2133600/uav-mq-5b-hunter-launch-and-recovery-kandahar-airfield
https://en.wikipedia.org/wiki/IAI_RQ-5_Hunter');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Absent de la campagne de 2001-2002, il devient ensuite l''œil des brigades de l''US Army ; le VMU-2 des Marines en déploie un détachement en 2009 et l''armée australienne l''emploie à partir de mai 2012.', role_en = 'Absent from the 2001-2002 campaign, it later became the eye of US Army brigades; Marine squadron VMU-2 deployed a detachment in 2009 and the Australian Army flew it there from May 2012.', sources = 'https://en.wikipedia.org/wiki/AAI_RQ-7_Shadow'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'RQ-7 Shadow' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Absent de la campagne de 2001-2002, il devient ensuite l''œil des brigades de l''US Army ; le VMU-2 des Marines en déploie un détachement en 2009 et l''armée australienne l''emploie à partir de mai 2012.', 'Absent from the 2001-2002 campaign, it later became the eye of US Army brigades; Marine squadron VMU-2 deployed a detachment in 2009 and the Australian Army flew it there from May 2012.', 'https://en.wikipedia.org/wiki/AAI_RQ-7_Shadow');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Embarqués dès *Héraclès* sur le *Charles de Gaulle*, les Rafale M sont rejoints en mars 2007 par trois Rafale de l''armée de l''Air à Douchanbé. Le 28 mars 2007, un Rafale M F2 de la flottille 12F tire sa première bombe guidée laser, au profit de soldats néerlandais ; ils opèrent ensuite de Kandahar.', role_en = 'Embarked on the *Charles de Gaulle* from *Héraclès* onwards, Navy Rafale Ms were joined in March 2007 by three Air Force Rafales at Dushanbe. On 28 March 2007 a Rafale M F2 of Flottille 12F dropped its first laser-guided bomb, for Dutch troops; Rafales later flew from Kandahar.', sources = 'https://prod-site-internet-minarm-admin.cloud.defense.gouv.fr/sites/default/files/cesm/bm-59-rafale-afghanistan.pdf
https://fr.wikipedia.org/wiki/Mission_H%C3%A9racl%C3%A8s
https://www.flightglobal.com/rafales-go-to-afghanistan-as-french-commitment-grows/72411.article
https://en.wikipedia.org/wiki/Dassault_Mirage_2000N/2000D'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Rafale' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Embarqués dès *Héraclès* sur le *Charles de Gaulle*, les Rafale M sont rejoints en mars 2007 par trois Rafale de l''armée de l''Air à Douchanbé. Le 28 mars 2007, un Rafale M F2 de la flottille 12F tire sa première bombe guidée laser, au profit de soldats néerlandais ; ils opèrent ensuite de Kandahar.', 'Embarked on the *Charles de Gaulle* from *Héraclès* onwards, Navy Rafale Ms were joined in March 2007 by three Air Force Rafales at Dushanbe. On 28 March 2007 a Rafale M F2 of Flottille 12F dropped its first laser-guided bomb, for Dutch troops; Rafales later flew from Kandahar.', 'https://prod-site-internet-minarm-admin.cloud.defense.gouv.fr/sites/default/files/cesm/bm-59-rafale-afghanistan.pdf
https://fr.wikipedia.org/wiki/Mission_H%C3%A9racl%C3%A8s
https://www.flightglobal.com/rafales-go-to-afghanistan-as-french-commitment-grows/72411.article
https://en.wikipedia.org/wiki/Dassault_Mirage_2000N/2000D');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Avion de surveillance du sol de la RAF (5 Squadron), il effectue le 15 novembre 2008 sa première sortie opérationnelle au-dessus de l''Afghanistan au profit de l''armée britannique, mission qui justifie son maintien en service.', role_en = 'The RAF''s ground-surveillance aircraft (No. 5 Squadron) flew its first operational sortie over Afghanistan for the British Army on 15 November 2008, a mission that justified keeping it in service.', sources = 'https://en.wikipedia.org/wiki/Raytheon_Sentinel'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Raytheon Sentinel R1' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Avion de surveillance du sol de la RAF (5 Squadron), il effectue le 15 novembre 2008 sa première sortie opérationnelle au-dessus de l''Afghanistan au profit de l''armée britannique, mission qui justifie son maintien en service.', 'The RAF''s ground-surveillance aircraft (No. 5 Squadron) flew its first operational sortie over Afghanistan for the British Army on 15 November 2008, a mission that justified keeping it in service.', 'https://en.wikipedia.org/wiki/Raytheon_Sentinel');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Drone tactique du Canada (CU-161) de 2003 au 18 avril 2009, des Pays-Bas et de la France : le 61e régiment d''artillerie l''emploie de fin 2008 à 2012 pour le renseignement et la reconnaissance d''itinéraires, avec sa 100e mission le 15 mai 2009 depuis Tora.', role_en = 'A tactical drone flown by Canada (CU-161) from 2003 to 18 April 2009, the Netherlands and France: the 61st Artillery Regiment used it from late 2008 to 2012 for intelligence and route reconnaissance, flying its 100th mission from Tora on 15 May 2009.', sources = 'https://en.wikipedia.org/wiki/Sagem_Sperwer
https://theatrum-belli.com/la-dga-commande-des-drones-tactiques-sdti-sperwer-de-sagem/
https://www.shephardmedia.com/news/uv-online/french-army-completes-100th-flight-of-it/'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Sagem Sperwer' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Drone tactique du Canada (CU-161) de 2003 au 18 avril 2009, des Pays-Bas et de la France : le 61e régiment d''artillerie l''emploie de fin 2008 à 2012 pour le renseignement et la reconnaissance d''itinéraires, avec sa 100e mission le 15 mai 2009 depuis Tora.', 'A tactical drone flown by Canada (CU-161) from 2003 to 18 April 2009, the Netherlands and France: the 61st Artillery Regiment used it from late 2008 to 2012 for intelligence and route reconnaissance, flying its 100th mission from Tora on 15 May 2009.', 'https://en.wikipedia.org/wiki/Sagem_Sperwer
https://theatrum-belli.com/la-dga-commande-des-drones-tactiques-sdti-sperwer-de-sagem/
https://www.shephardmedia.com/news/uv-online/french-army-completes-100th-flight-of-it/');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Depuis le *Charles de Gaulle*, les Super Étendard frappent l''Afghanistan à partir du 19 décembre 2001 (140 missions pendant *Héraclès*), appuient *Anaconda* en mars 2002 et désignent au laser les cibles des Rafale ; ils reviennent en 2004, 2006, 2007, 2008 et 2010-2011.', role_en = 'Flying from the *Charles de Gaulle*, Super Étendards struck Afghanistan from 19 December 2001 (140 missions during *Héraclès*), supported *Anaconda* in March 2002 and laser-designated targets for Rafales; they returned in 2004, 2006, 2007, 2008 and 2010-2011.', sources = 'https://fr.wikipedia.org/wiki/Mission_H%C3%A9racl%C3%A8s
https://en.wikipedia.org/wiki/Dassault-Breguet_Super_%C3%89tendard'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Super Étendard' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Depuis le *Charles de Gaulle*, les Super Étendard frappent l''Afghanistan à partir du 19 décembre 2001 (140 missions pendant *Héraclès*), appuient *Anaconda* en mars 2002 et désignent au laser les cibles des Rafale ; ils reviennent en 2004, 2006, 2007, 2008 et 2010-2011.', 'Flying from the *Charles de Gaulle*, Super Étendards struck Afghanistan from 19 December 2001 (140 missions during *Héraclès*), supported *Anaconda* in March 2002 and laser-designated targets for Rafales; they returned in 2004, 2006, 2007, 2008 and 2010-2011.', 'https://fr.wikipedia.org/wiki/Mission_H%C3%A9racl%C3%A8s
https://en.wikipedia.org/wiki/Dassault-Breguet_Super_%C3%89tendard');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Jusqu''à huit C-160 de la Luftwaffe, basés à Termez (Ouzbékistan) puis à Mazar-i-Charif, ravitaillent le contingent allemand de la FIAS dans le nord du pays. Deux Transall français opèrent depuis Douchanbé (Tadjikistan). L''A400M les relève à partir de 2014.', role_en = 'Up to eight Luftwaffe C-160s, based at Termez in Uzbekistan and then Mazar-i-Sharif, supplied the German ISAF contingent in the north of the country. Two French Transalls operated from Dushanbe, Tajikistan. The A400M took over from 2014.', sources = 'https://en.wikipedia.org/wiki/Termez_Airport
https://www.bundeswehr.de/de/mediathek/grossgeraet-bundeswehr-afghanistan-5097728
https://en.wikipedia.org/wiki/French_forces_in_Afghanistan'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Transall C-160' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Jusqu''à huit C-160 de la Luftwaffe, basés à Termez (Ouzbékistan) puis à Mazar-i-Charif, ravitaillent le contingent allemand de la FIAS dans le nord du pays. Deux Transall français opèrent depuis Douchanbé (Tadjikistan). L''A400M les relève à partir de 2014.', 'Up to eight Luftwaffe C-160s, based at Termez in Uzbekistan and then Mazar-i-Sharif, supplied the German ISAF contingent in the north of the country. Two French Transalls operated from Dushanbe, Tajikistan. The A400M took over from 2014.', 'https://en.wikipedia.org/wiki/Termez_Airport
https://www.bundeswehr.de/de/mediathek/grossgeraet-bundeswehr-afghanistan-5097728
https://en.wikipedia.org/wiki/French_forces_in_Afghanistan');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Les U-2 survolent l''Afghanistan avant les premières frappes et fournissent le détail nécessaire à la planification d''octobre 2001. De janvier à mars 2010, le 99th Expeditionary Reconnaissance Squadron y vole près de 200 sorties de combat au profit de plus de 70 unités au contact.', role_en = 'U-2s overflew Afghanistan before the first strikes and provided the detail needed to plan the October 2001 campaign. From January to March 2010 the 99th Expeditionary Reconnaissance Squadron flew nearly 200 combat sorties there, supporting more than 70 troops-in-contact events.', sources = 'https://www.airandspaceforces.com/article/0202enduring/
https://www.afcent.af.mil/News/Article/220502/deployed-dragon-lady-swoops-in-low-for-a-closer-look-at-counterinsurgency'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'U-2 Dragon Lady' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Les U-2 survolent l''Afghanistan avant les premières frappes et fournissent le détail nécessaire à la planification d''octobre 2001. De janvier à mars 2010, le 99th Expeditionary Reconnaissance Squadron y vole près de 200 sorties de combat au profit de plus de 70 unités au contact.', 'U-2s overflew Afghanistan before the first strikes and provided the detail needed to plan the October 2001 campaign. From January to March 2010 the 99th Expeditionary Reconnaissance Squadron flew nearly 200 combat sorties there, supporting more than 70 troops-in-contact events.', 'https://www.airandspaceforces.com/article/0202enduring/
https://www.afcent.af.mil/News/Article/220502/deployed-dragon-lady-swoops-in-low-for-a-closer-look-at-counterinsurgency');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Les MV-22 du VMM-261 arrivent en novembre 2009 ; le 4 décembre, l''opération *Cobra''s Anger* dépose environ 1 000 Marines et 150 soldats afghans dans la vallée de Now Zad (Helmand). Ils servent ensuite surtout à l''évacuation sanitaire, jusqu''au retrait de 2014.', role_en = 'VMM-261''s MV-22s arrived in November 2009; on 4 December *Cobra''s Anger* inserted about 1,000 Marines and 150 Afghan soldiers into the Now Zad valley in Helmand. They later flew mostly casualty evacuation until the 2014 drawdown.', sources = 'https://en.wikipedia.org/wiki/Bell_Boeing_V-22_Osprey'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'V-22 Osprey' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Les MV-22 du VMM-261 arrivent en novembre 2009 ; le 4 décembre, l''opération *Cobra''s Anger* dépose environ 1 000 Marines et 150 soldats afghans dans la vallée de Now Zad (Helmand). Ils servent ensuite surtout à l''évacuation sanitaire, jusqu''au retrait de 2014.', 'VMM-261''s MV-22s arrived in November 2009; on 4 December *Cobra''s Anger* inserted about 1,000 Marines and 150 Afghan soldiers into the Now Zad valley in Helmand. They later flew mostly casualty evacuation until the 2014 drawdown.', 'https://en.wikipedia.org/wiki/Bell_Boeing_V-22_Osprey');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Depuis une base du Moyen-Orient, les VC10 ravitailleurs de la RAF ravitaillent en vol les avions de combat de l''OTAN au-dessus de l''Afghanistan, jusqu''à leur dernière sortie opérationnelle en septembre 2013, après 47 ans de service.', role_en = 'Flying from a Middle East base, RAF VC10 tankers refuelled NATO combat aircraft over Afghanistan until their last operational sortie in September 2013, after 47 years of service.', sources = 'https://www.gov.uk/government/news/final-flight-of-the-vc10
https://www.gov.uk/government/news/article-raf-technicians-commended-for-keeping-tanker-flying-over-afghanistan'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Vickers VC10' AND w.name = 'Guerre d''Afghanistan'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Depuis une base du Moyen-Orient, les VC10 ravitailleurs de la RAF ravitaillent en vol les avions de combat de l''OTAN au-dessus de l''Afghanistan, jusqu''à leur dernière sortie opérationnelle en septembre 2013, après 47 ans de service.', 'Flying from a Middle East base, RAF VC10 tankers refuelled NATO combat aircraft over Afghanistan until their last operational sortie in September 2013, after 47 years of service.', 'https://www.gov.uk/government/news/final-flight-of-the-vc10
https://www.gov.uk/government/news/article-raf-technicians-commended-for-keeping-tanker-flying-over-afghanistan');
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2001-10-07', 'day', 'Début d''*Enduring Freedom*', '*Enduring Freedom* begins', 'Bombardiers, avions embarqués et missiles de croisière frappent 31 objectifs. La défense aérienne talibane, ses MiG-21 et ses Su-22 sont détruits dès la première nuit, et la CIA mène sa première frappe avec un Predator armé.', 'Bombers, carrier aircraft and cruise missiles hit 31 targets. The Taliban air defences, MiG-21s and Su-22s were destroyed on the first night, and the CIA carried out its first strike with an armed Predator.', NULL::int, 'https://en.wikipedia.org/wiki/United_States_invasion_of_Afghanistan' FROM wars w WHERE w.name = 'Guerre d''Afghanistan'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2001-11-13', 'day', 'Chute de Kaboul', 'Fall of Kabul', 'Trois jours après Mazar-i-Charif, l''Alliance du Nord entre dans Kaboul, ouverte par des semaines de frappes guidées depuis le sol par les forces spéciales.', 'Three days after Mazar-i-Sharif, the Northern Alliance entered Kabul, its way opened by weeks of strikes guided from the ground by special forces.', NULL::int, 'https://en.wikipedia.org/wiki/United_States_invasion_of_Afghanistan' FROM wars w WHERE w.name = 'Guerre d''Afghanistan'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2001-12-17', 'day', 'Fin de la bataille de Tora Bora', 'Battle of Tora Bora ends', 'Après un mois de bombardements sur les grottes de Tora Bora, commencés le 16 novembre, la bataille s''achève, mais Oussama ben Laden a fui vers le Pakistan.', 'After a month of bombing of the Tora Bora caves, begun on 16 November, the battle ended, but Osama bin Laden had escaped into Pakistan.', NULL::int, 'https://en.wikipedia.org/wiki/United_States_invasion_of_Afghanistan' FROM wars w WHERE w.name = 'Guerre d''Afghanistan'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
