INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'france', 1, 'France', 'France', 'Armée de l’Air, Aéronautique navale, Aviation légère de l’Armée de terre (ALAT)', 'French Air Force, Naval Aviation, Army Light Aviation (ALAT)' FROM wars w WHERE w.name = 'Guerre d''Algérie'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'fln-aln', 2, 'FLN et ALN', 'FLN and ALN', 'Front de libération nationale et Armée de libération nationale, sans aviation, avec des bases arrière en Tunisie et au Maroc', 'National Liberation Front and National Liberation Army, with no air arm, relying on rear bases in Tunisia and Morocco' FROM wars w WHERE w.name = 'Guerre d''Algérie'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre d''Algérie' AND s.side_key NOT IN ('france', 'fln-aln');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), role = 'Achetés pour remplacer les P-47, les Skyraider de la 20e escadre de chasse (escadrons 1/20 « Aurès-Nementcha », 2/20 « Ouarsenis », 3/20 « Oranie ») assurent l’appui rapproché aux roquettes, aux bombes et au napalm de 1960 à la fin de la guerre.', role_en = 'Bought to replace the P-47s, the Skyraiders of the 20th Fighter Wing (squadrons 1/20 "Aurès-Nementcha", 2/20 "Ouarsenis" and 3/20 "Oranie") flew close support with rockets, bombs and napalm from 1960 until the end of the war.', sources = 'https://en.wikipedia.org/wiki/Douglas_A-1_Skyraider
https://fr.wikipedia.org/wiki/Douglas_AD_Skyraider
https://www.oocities.org/zvika47.geo/fr-af-1960.htm'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'A-1 Skyraider' AND w.name = 'Guerre d''Algérie'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), 'Achetés pour remplacer les P-47, les Skyraider de la 20e escadre de chasse (escadrons 1/20 « Aurès-Nementcha », 2/20 « Ouarsenis », 3/20 « Oranie ») assurent l’appui rapproché aux roquettes, aux bombes et au napalm de 1960 à la fin de la guerre.', 'Bought to replace the P-47s, the Skyraiders of the 20th Fighter Wing (squadrons 1/20 "Aurès-Nementcha", 2/20 "Ouarsenis" and 3/20 "Oranie") flew close support with rockets, bombs and napalm from 1960 until the end of the war.', 'https://en.wikipedia.org/wiki/Douglas_A-1_Skyraider
