UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), role = 'Des Mystère IVA des 2e, 5e, 8e et 12e escadres viennent en détachement en Algérie pour protéger l’espace aérien contre une éventuelle intrusion égyptienne ou libyenne ; en 1958, une force d’intervention de Mystère IVA est installée à Tébessa.', role_en = 'Mystère IVAs of the 2nd, 5th, 8th and 12th Fighter Wings rotated through Algeria to guard its airspace against possible Egyptian or Libyan intrusions; in 1958, a Mystère IVA intervention force was set up at Tébessa.', sources = 'https://avions-de-la-guerre-d-algerie.over-blog.com/article-gamd-454-mystere-iv-90188337.html
