UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), role = 'Jamais basé en permanence en Algérie, il y vient à partir de 1959 en détachements de quelques jours, relevés chaque mois à Bône, Boufarik et Télergma, pour la défense aérienne de l’Est algérien contre d’éventuels chasseurs venus de Libye ou d’Égypte.', role_en = 'Never permanently based in Algeria, it came from 1959 in detachments of a few days, relieved monthly at Bône, Boufarik and Télergma, to defend the airspace of eastern Algeria against possible fighters from Libya or Egypt.', sources = 'https://fr.wikipedia.org/wiki/Dassault_Super_Myst%C3%A8re_B2
https://avions-de-la-guerre-d-algerie.over-blog.com/article-le-gamd-smb-2-super-mystere-b2-87495659.html'
