 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Super Mystère B2' AND w.name = 'Guerre d''Algérie'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), 'Jamais basé en permanence en Algérie, il y vient à partir de 1959 en détachements de quelques jours, relevés chaque mois à Bône, Boufarik et Télergma, pour la défense aérienne de l’Est algérien contre d’éventuels chasseurs venus de Libye ou d’Égypte.', 'Never permanently based in Algeria, it came from 1959 in detachments of a few days, relieved monthly at Bône, Boufarik and Télergma, to defend the airspace of eastern Algeria against possible fighters from Libya or Egypt.', 'https://fr.wikipedia.org/wiki/Dassault_Super_Myst%C3%A8re_B2
https://avions-de-la-guerre-d-algerie.over-blog.com/article-le-gamd-smb-2-super-mystere-b2-87495659.html');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), role = 'Quelque 150 T-28A rachetés aux États-Unis sont remotorisés et armés par Sud-Aviation sous le nom de Fennec. De 1959 à 1962, ils remplacent les MS.733A et une partie des T-6 dans les escadrilles d’aviation légère d’appui, avec mitrailleuses, roquettes et bombes.', role_en = 'Some 150 T-28As bought from the United States were re-engined and armed by Sud-Aviation as the Fennec. From 1959 to 1962 they replaced the MS.733As and some of the T-6s in the light air support squadrons, carrying machine guns, rockets and bombs.', sources = 'https://fr.wikipedia.org/wiki/North_American_T-28_Trojan
