INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1954-11-01', 'day', 'La « Toussaint rouge »', 'The "Red All Saints'' Day"', 'Dans la nuit, le FLN déclenche une série d’attentats et d’attaques, dont celle de la caserne de Batna : c’est le début de l’insurrection.', 'During the night, the FLN launched a wave of bombings and attacks, including one on the Batna barracks: the uprising had begun.', NULL::int, 'https://fr.wikipedia.org/wiki/Guerre_d%27Alg%C3%A9rie' FROM wars w WHERE w.name = 'Guerre d''Algérie'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1955-08-20', 'day', 'Soulèvement du Constantinois', 'Constantinois uprising', 'Après les massacres d’El Halia, la répression est massive : l’aviation bombarde les douars des environs, et le nombre de victimes se compte par milliers.', 'After the El Halia massacre, the repression was massive: aircraft bombed the surrounding villages, and the victims numbered in the thousands.', NULL::int, 'https://fr.wikipedia.org/wiki/Guerre_d%27Alg%C3%A9rie' FROM wars w WHERE w.name = 'Guerre d''Algérie'
