       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1956-01-01', 'year', 'Premiers missiles filoguidés tirés d’un avion', 'First wire-guided missiles fired from an aircraft', 'Des Flamant MD 311 du GOM 86 tirent des missiles antichars SS.11 contre des grottes fortifiées au fond des gorges : un premier emploi au combat qui ouvre la voie aux hélicoptères antichars.', 'Flamant MD 311s of GOM 86 fired SS.11 anti-tank missiles at fortified caves deep in mountain gorges, a combat first that paved the way for anti-tank helicopters.', (SELECT id FROM airplanes WHERE name = 'Dassault MD 315 Flamant'), 'https://en.wikipedia.org/wiki/Dassault_MD_315_Flamant' FROM wars w WHERE w.name = 'Guerre d''Algérie'
