INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1956-10-22', 'day', 'Détournement de l’avion des chefs du FLN', 'FLN leaders'' aircraft diverted', 'Le DC-3 marocain qui conduit Ben Bella et quatre autres dirigeants du FLN de Rabat à Tunis est contraint de se poser à Alger ; ils restent emprisonnés jusqu’à la fin de la guerre.', 'The Moroccan DC-3 carrying Ben Bella and four other FLN leaders from Rabat to Tunis was forced to land in Algiers; they were held prisoner until the end of the war.', NULL::int, 'https://en.wikipedia.org/wiki/Algerian_War' FROM wars w WHERE w.name = 'Guerre d''Algérie'
