INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1957-07-01', 'month', 'Début de la ligne Morice', 'Morice Line begins', 'Un barrage électrifié et miné est édifié le long de la frontière tunisienne ; l’aviation, basée à Bône et à Tébessa, intervient sur chaque tentative de franchissement.', 'An electrified, mined barrier went up along the Tunisian border; aircraft based at Bône and Tébessa responded to each crossing attempt.', NULL::int, 'https://fr.wikipedia.org/wiki/Ligne_Morice' FROM wars w WHERE w.name = 'Guerre d''Algérie'
