INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1958-01-21', 'day', 'Début de la bataille des frontières', 'Battle of the Frontiers begins', 'Jusqu’au 28 mai 1958, l’ALN tente en vain de faire franchir les barrages à ses unités venues de Tunisie ; parachutistes, blindés et aviation les interceptent.', 'Until 28 May 1958, the ALN tried in vain to push its units from Tunisia across the barriers; paratroopers, armour and aircraft intercepted them.', NULL::int, 'https://fr.wikipedia.org/wiki/Guerre_d%27Alg%C3%A9rie' FROM wars w WHERE w.name = 'Guerre d''Algérie'
