INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1958-02-08', 'day', 'Bombardement de Sakiet Sidi Youssef', 'Bombing of Sakiet Sidi Youssef', 'Onze B-26, six Corsair de la flottille 12F et huit Mistral frappent ce village tunisien qui abrite l’ALN ; le raid fait plus de 70 morts civils et déclenche une crise internationale.', 'Eleven B-26s, six Corsairs of Flotilla 12F and eight Mistrals struck this Tunisian village sheltering the ALN; the raid killed more than 70 civilians and sparked an international crisis.', (SELECT id FROM airplanes WHERE name = 'F4U Corsair'), 'https://fr.wikipedia.org/wiki/Bombardement_de_Sakiet_Sidi_Youssef' FROM wars w WHERE w.name = 'Guerre d''Algérie'
