INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1959-01-01', 'year', 'Arrivée des T-28 Fennec', 'T-28 Fennecs arrive', 'Remotorisés et armés en France, les T-28 Fennec rejoignent les escadrilles d’aviation légère d’appui, où ils remplacent les Alcyon jusqu’à la fin de la guerre.', 'Re-engined and armed in France, T-28 Fennecs joined the light air support squadrons, replacing the Alcyons until the end of the war.', (SELECT id FROM airplanes WHERE name = 'T-28 Trojan'), 'https://fr.wikipedia.org/wiki/North_American_T-28_Trojan' FROM wars w WHERE w.name = 'Guerre d''Algérie'
