INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1959-07-22', 'day', 'Début de l’opération *Jumelles*', 'Operation *Jumelles* begins', 'Plus de 60 000 hommes, appuyés par les avions et les hélicoptères, investissent la Kabylie (wilaya III) : c’est la plus vaste opération de la guerre.', 'Over 60,000 troops, backed by aircraft and helicopters, moved into Kabylia (Wilaya III), the largest operation of the war.', NULL::int, 'https://fr.wikipedia.org/wiki/Op%C3%A9ration_Jumelles' FROM wars w WHERE w.name = 'Guerre d''Algérie'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1960-02-04', 'day', 'Premier Skyraider à Boufarik', 'First Skyraider at Boufarik', 'Le premier Skyraider de l’armée de l’Air arrive sur la base 142 de Boufarik ; la 20e escadre de chasse en alignera trois escadrons pour l’appui rapproché.', 'The French Air Force''s first Skyraider reached Air Base 142 at Boufarik; the 20th Fighter Wing would field three squadrons of them for close support.', (SELECT id FROM airplanes WHERE name = 'A-1 Skyraider'), 'https://fr.wikipedia.org/wiki/Douglas_AD_Skyraider' FROM wars w WHERE w.name = 'Guerre d''Algérie'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1960-10-28', 'day', 'Les Vautour à Oran', 'Vautours at Oran', 'Rééquipé de Vautour IIN à Oran-La Sénia, l’escadron Normandie-Niemen devient l’ECTT 2/6, chargé de la chasse de nuit au-dessus de l’Algérie.', 'Re-equipped with Vautour IINs at Oran-La Sénia, the Normandie-Niemen squadron became ECTT 2/6, tasked with night fighting over Algeria.', (SELECT id FROM airplanes WHERE name = 'Vautour II'), 'https://avions-de-la-guerre-d-algerie.over-blog.com/article-le-sncaso-so-4050-vautour-105853155.html' FROM wars w WHERE w.name = 'Guerre d''Algérie'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1962-03-19', 'day', 'Cessez-le-feu', 'Ceasefire', 'Au lendemain de la signature des accords d’Évian, le cessez-le-feu entre en vigueur à midi sur tout le territoire algérien.', 'The day after the Évian Accords were signed, the ceasefire came into force at noon across Algeria.', NULL::int, 'https://fr.wikipedia.org/wiki/Accords_d%27%C3%89vian' FROM wars w WHERE w.name = 'Guerre d''Algérie'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
DELETE FROM war_events e USING wars w
 WHERE e.war_id = w.id AND w.name = 'Guerre d''Algérie'
   AND (e.event_date, e.title) NOT IN ((DATE '1954-11-01', 'La « Toussaint rouge »'), (DATE '1955-08-20', 'Soulèvement du Constantinois'), (DATE '1956-01-01', 'Premiers missiles filoguidés tirés d’un avion'), (DATE '1956-10-22', 'Détournement de l’avion des chefs du FLN'), (DATE '1957-07-01', 'Début de la ligne Morice'), (DATE '1958-01-21', 'Début de la bataille des frontières'), (DATE '1958-02-08', 'Bombardement de Sakiet Sidi Youssef'), (DATE '1959-01-01', 'Arrivée des T-28 Fennec'), (DATE '1959-02-06', 'Lancement du plan Challe'), (DATE '1959-07-22', 'Début de l’opération *Jumelles*'), (DATE '1960-02-04', 'Premier Skyraider à Boufarik'), (DATE '1960-10-28', 'Les Vautour à Oran'), (DATE '1962-03-19', 'Cessez-le-feu'));

-- ── Guerre d'Indochine ──
UPDATE wars SET outcome = 'La chute de Diên Biên Phu, le 7 mai 1954, précipite les accords de Genève du 21 juillet 1954 : la France se retire d’Indochine et le Vietnam est partagé de part et d’autre du 17e parallèle.',
       outcome_en = 'The fall of Dien Bien Phu on 7 May 1954 hastened the Geneva Accords of 21 July 1954: France withdrew from Indochina and Vietnam was divided along the 17th parallel.',
       context = 'Revenue en Indochine après la capitulation japonaise, la France veut y rétablir son autorité face au Viêt Minh, le front communiste dirigé par Hô Chi Minh et le général Võ Nguyên Giáp. Le 23 novembre 1946, la flotte française bombarde les quartiers vietnamiens de Haiphong ; le 19 décembre, le Viêt Minh attaque à Hanoï. Commence alors une guerre de huit ans, faite de guérilla dans les rizières du delta du Tonkin et de campagnes dans la jungle et les montagnes de la Haute Région et du Laos.

Le rapport de forces bascule avec la victoire communiste en Chine, en octobre 1949 : Pékin arme et forme le Viêt Minh, qui dispose bientôt de divisions, d’artillerie lourde et de canons antiaériens. En face, la France aligne au début de 1953 environ 200 000 hommes, épaulés par autant de soldats vietnamiens des États associés. La guerre de Corée fait de l’Indochine un front de la guerre froide : les États-Unis, qui fournissent du matériel à partir de 1950, financent jusqu’aux trois quarts de l’effort français en 1954.

Dans les airs, le combat est inégal mais d’un genre particulier. Le Viêt Minh n’a aucune aviation : l’armée de l’Air et l’Aéronavale ne livrent pas de combat aérien, mais appuient les troupes au sol, reconnaissent, et surtout transportent, parachutent et ravitaillent des garnisons isolées. Elles le font sous un climat éprouvant, de jour et à vue, faute d’aides radio et radar, avec des équipages trop peu nombreux.',
       context_en = 'Back in Indochina after the Japanese surrender, France set out to restore its authority against the Viet Minh, the communist-led front of Ho Chi Minh and General Vo Nguyen Giap. On 23 November 1946 the French fleet shelled the Vietnamese quarters of Haiphong; on 19 December the Viet Minh struck in Hanoi. Eight years of war followed, mixing guerrilla fighting in the rice paddies of the Tonkin delta with campaigns in the jungle and mountains of the northern highlands and Laos.

The balance shifted with the communist victory in China in October 1949: Beijing armed and trained the Viet Minh, which soon fielded divisions, heavy artillery and anti-aircraft guns. Against them, France had about 200,000 troops in early 1953, backed by as many Vietnamese soldiers of the Associated States. The Korean War turned Indochina into a Cold War front: the United States, supplying equipment from 1950, was paying up to three quarters of the cost of the French war by 1954.

In the air, the fight was lopsided but unusual. The Viet Minh had no air force, so the French Air Force and Naval Aviation fought no air battles. Instead they supported troops on the ground, flew reconnaissance and, above all, carried, parachuted and resupplied isolated garrisons. They did so in a punishing climate, by day and by eye for want of radio and radar aids, and with too few aircrews.',
       narrative = 'Les premières unités de chasse débarquent à Saïgon en novembre 1945 sans avions : elles reçoivent des Spitfire VIII et IX, tandis que des Junkers Ju 52 et des Dakota assurent le transport et, gréés pour l’occasion, le bombardement. Viennent ensuite des Mosquito, qui se dégradent vite sous ce climat, puis des Bell P-63 Kingcobra de 1949 à janvier 1951. Cette aviation disparate, absente de ce catalogue, vole de jour, à vue, depuis des terrains que la mousson ferme une partie de l’année.

L’aide américaine change l’échelle de la guerre aérienne. En octobre 1950, quarante Hellcat arrivent à Saïgon ; à la fin de l’année, plus de trente bombardiers B-26 Invader sont livrés, et les premiers F8F Bearcat suivent en février 1951. En janvier 1951, à Vĩnh Yên, l’aviation contribue de façon décisive à briser l’offensive de Giáp lors du plus important bombardement aérien de la guerre. Le commandement se répartit en trois groupements aériens tactiques (GATAC) Nord, Centre et Sud, puis un quatrième au Laos en 1953, et le rythme des sorties double en neuf mois.

La guerre devient aussi celle des ponts aériens. Du 16 octobre au 30 novembre 1952, Dakota militaires et civils et cargos Bristol 170 acheminent à Na San 15 000 hommes et 2 500 tonnes de fret ; le camp repousse l’assaut des 1er et 2 décembre et Giáp se retire le 4. Ce camp retranché ravitaillé par air devient un modèle. Au printemps 1953, face à l’invasion du Laos, les États-Unis prêtent en secret leurs premiers C-119 Flying Boxcar, pilotés par les Américains de la compagnie Civil Air Transport (CAT).

Le 20 novembre 1953, l’opération *Castor* largue les parachutistes sur Diên Biên Phu : 67 avions de transport en deux vagues, environ 9 000 hommes en trois jours. Le 13 mars 1954, l’artillerie du Viêt Minh pilonne la piste, détruit les chasseurs qui y stationnent et la rend vite inutilisable ; le dernier avion en décolle le 27 mars. Dès lors, tout arrive par parachute, sous une DCA de 37 mm qui oblige à larguer de plus en plus haut. Les C-119 lâchent aussi du napalm à partir du 24 mars, Invader, Bearcat, Hellcat, Helldiver puis Corsair de l’Aéronavale frappent autour du camp, et le pont aérien atteint 250 tonnes le 15 avril. Washington étudie un bombardement massif, l’opération *Vautour*, mais y renonce.

Diên Biên Phu tombe le 7 mai 1954. La bataille coûte à la France 62 avions perdus et 167 endommagés selon le décompte de Wikipédia en anglais, qui parle ailleurs de 62 appareils « détruits ou gravement endommagés ». La veille, les pilotes de la CAT James McGovern et Wallace Buford ont été abattus aux commandes de leur C-119 : ils sont les premiers Américains connus morts au combat au Vietnam. Les accords de Genève, signés le 21 juillet 1954, mettent fin à la guerre.',
       narrative_en = 'The first fighter units landed in Saigon in November 1945 without aircraft. They were issued Spitfire VIIIs and IXs, while Junkers Ju 52s and Dakotas handled transport and, suitably rigged, bombing. Mosquitos followed, quickly deteriorating in the climate, then Bell P-63 Kingcobras from 1949 to January 1951. This mixed force, absent from this catalogue, flew by day and by eye from airfields the monsoon closed for part of the year.

American aid changed the scale of the air war. In October 1950 forty Hellcats reached Saigon; by the end of the year more than thirty B-26 Invader bombers had been delivered, and the first F8F Bearcats followed in February 1951. In January 1951 at Vinh Yen, air power played a decisive part in breaking Giap''s offensive in the largest aerial bombardment of the war. Command was split into three tactical air groups (GATAC), North, Centre and South, with a fourth for Laos in 1953, and the sortie rate doubled in nine months.

The war also became one of air bridges. From 16 October to 30 November 1952, military and civilian Dakotas and Bristol 170 freighters carried 15,000 men and 2,500 tonnes of cargo into Na San; the camp threw back the assault of 1-2 December and Giap withdrew on the 4th. The air-supplied fortified camp became a model. In spring 1953, as the Viet Minh invaded Laos, the United States secretly lent its first C-119 Flying Boxcars, flown by Americans of the Civil Air Transport (CAT) airline.

On 20 November 1953, Operation *Castor* dropped paratroopers on Dien Bien Phu: 67 transports in two waves, some 9,000 men in three days. On 13 March 1954 Viet Minh artillery pounded the airstrip, destroyed the fighters based there and soon made it unusable; the last aircraft took off on 27 March. From then on everything came by parachute, under 37 mm flak that forced drops from ever higher altitudes. C-119s also dropped napalm from 24 March, Invaders, Bearcats, Hellcats, Helldivers and then Navy Corsairs struck around the camp, and the airlift peaked at 250 tons on 15 April. Washington studied a massive air strike, Operation *Vulture*, but backed away.

Dien Bien Phu fell on 7 May 1954. The battle cost France 62 aircraft lost and 167 damaged according to English Wikipedia, which elsewhere speaks of 62 aircraft "destroyed or severely damaged". The day before, CAT pilots James McGovern and Wallace Buford had been shot down in their C-119, the first Americans known to have died in combat in Vietnam. The Geneva Accords, signed on 21 July 1954, ended the war.',
       sources = 'https://en.wikipedia.org/wiki/First_Indochina_War
https://www.airandspaceforces.com/PDF/MagazineArchive/Documents/2004/August%202004/0804dien.pdf
https://archive.org/download/DTIC_ADA384883/DTIC_ADA384883_text.pdf
https://en.wikipedia.org/wiki/History_of_the_Arm%C3%A9e_de_l%27Air_(colonial_presence_1939%E2%80%931962)
https://www.persee.fr/doc/mat_0769-3206_1992_num_29_1_405020
https://en.wikipedia.org/wiki/Battle_of_Dien_Bien_Phu
https://fr.wikipedia.org/wiki/Bataille_de_Di%C3%AAn_Bi%C3%AAn_Phu
https://fr.wikipedia.org/wiki/Bataille_de_Na_San
https://fr.wikipedia.org/wiki/Grumman_F8F_Bearcat
https://www.upi.com/Archives/1954/04/21/Giant-US-airlift-aiding-French/9561555637791/
https://history.state.gov/historicaldocuments/frus1952-54v13p1/d764'
 WHERE name = 'Guerre d''Indochine'
   AND (outcome, outcome_en, context, context_en, narrative, narrative_en, sources) IS DISTINCT FROM ('La chute de Diên Biên Phu, le 7 mai 1954, précipite les accords de Genève du 21 juillet 1954 : la France se retire d’Indochine et le Vietnam est partagé de part et d’autre du 17e parallèle.', 'The fall of Dien Bien Phu on 7 May 1954 hastened the Geneva Accords of 21 July 1954: France withdrew from Indochina and Vietnam was divided along the 17th parallel.', 'Revenue en Indochine après la capitulation japonaise, la France veut y rétablir son autorité face au Viêt Minh, le front communiste dirigé par Hô Chi Minh et le général Võ Nguyên Giáp. Le 23 novembre 1946, la flotte française bombarde les quartiers vietnamiens de Haiphong ; le 19 décembre, le Viêt Minh attaque à Hanoï. Commence alors une guerre de huit ans, faite de guérilla dans les rizières du delta du Tonkin et de campagnes dans la jungle et les montagnes de la Haute Région et du Laos.

