INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'france', 1, 'France et États associés', 'France and the Associated States', 'Armée de l’air et Aéronavale françaises, aviation naissante de l’État du Viêt Nam ; avions et mécaniciens prêtés par les États-Unis, équipages américains de la Civil Air Transport (CAT)', 'French Air Force and Naval Aviation, the fledgling air arm of the State of Vietnam; aircraft and mechanics lent by the United States, American crews of Civil Air Transport (CAT)' FROM wars w WHERE w.name = 'Guerre d''Indochine'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'viet-minh', 2, 'Viêt Minh', 'Viet Minh', 'Viêt Minh et Armée populaire vietnamienne, sans aviation, armés et conseillés par la Chine (artillerie, canons antiaériens)', 'Viet Minh and the People''s Army of Vietnam, with no air force, armed and advised by China (artillery, anti-aircraft guns)' FROM wars w WHERE w.name = 'Guerre d''Indochine'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre d''Indochine' AND s.side_key NOT IN ('france', 'viet-minh');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), role = 'Environ 110 Invader arment les groupes de bombardement 1/19 Gascogne, 1/25 Tunisie et 1/91 Bourgogne et l’ERP 2/19 Armagnac. Depuis Cat Bi, ils bombardent et mitraillent autour de Diên Biên Phu, où la DCA en détruit sept.', role_en = 'Some 110 Invaders equipped bomber groups 1/19 Gascogne, 1/25 Tunisie and 1/91 Bourgogne and reconnaissance squadron 2/19 Armagnac. Flying from Cat Bi, they bombed and strafed around Dien Bien Phu, where flak destroyed seven.', sources = 'https://fr.wikipedia.org/wiki/Douglas_A-26_Invader
https://en.wikipedia.org/wiki/Douglas_A-26_Invader
https://archive.org/download/DTIC_ADA384883/DTIC_ADA384883_text.pdf
https://www.airandspaceforces.com/PDF/MagazineArchive/Documents/2004/August%202004/0804dien.pdf'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'A-26 Invader' AND w.name = 'Guerre d''Indochine'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), 'Environ 110 Invader arment les groupes de bombardement 1/19 Gascogne, 1/25 Tunisie et 1/91 Bourgogne et l’ERP 2/19 Armagnac. Depuis Cat Bi, ils bombardent et mitraillent autour de Diên Biên Phu, où la DCA en détruit sept.', 'Some 110 Invaders equipped bomber groups 1/19 Gascogne, 1/25 Tunisie and 1/91 Bourgogne and reconnaissance squadron 2/19 Armagnac. Flying from Cat Bi, they bombed and strafed around Dien Bien Phu, where flak destroyed seven.', 'https://fr.wikipedia.org/wiki/Douglas_A-26_Invader
https://en.wikipedia.org/wiki/Douglas_A-26_Invader
https://archive.org/download/DTIC_ADA384883/DTIC_ADA384883_text.pdf
https://www.airandspaceforces.com/PDF/MagazineArchive/Documents/2004/August%202004/0804dien.pdf');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), role = 'Des Bristol 170 de compagnies civiles affrétées par l’armée de l’air participent au pont aérien de Na San en 1952, puis acheminent à Diên Biên Phu, avec les Dakota, des chars M24 Chaffee démontés en décembre 1953.', role_en = 'Bristol 170s of civilian airlines chartered by the French Air Force joined the Na San air bridge in 1952, then, with the Dakotas, flew dismantled M24 Chaffee tanks into Dien Bien Phu in December 1953.', sources = 'https://fr.wikipedia.org/wiki/Bataille_de_Na_San
https://archive.org/download/DTIC_ADA384883/DTIC_ADA384883_text.pdf
https://edcoatesaircraftphotos.com/ac5/ROW%20Europe/F-BENV.html
https://museum.vhpa.org/history/story.html'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Bristol Freighter' AND w.name = 'Guerre d''Indochine'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), 'Des Bristol 170 de compagnies civiles affrétées par l’armée de l’air participent au pont aérien de Na San en 1952, puis acheminent à Diên Biên Phu, avec les Dakota, des chars M24 Chaffee démontés en décembre 1953.', 'Bristol 170s of civilian airlines chartered by the French Air Force joined the Na San air bridge in 1952, then, with the Dakotas, flew dismantled M24 Chaffee tanks into Dien Bien Phu in December 1953.', 'https://fr.wikipedia.org/wiki/Bataille_de_Na_San
https://archive.org/download/DTIC_ADA384883/DTIC_ADA384883_text.pdf
https://edcoatesaircraftphotos.com/ac5/ROW%20Europe/F-BENV.html
https://museum.vhpa.org/history/story.html');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), role = 'Prêtés en secret par l’USAF à partir d’avril 1953, aux couleurs françaises, les C-119 sont pilotés par l’armée de l’air et par les Américains de la CAT. À Diên Biên Phu, ils larguent vivres, munitions et napalm ; McGovern et Buford y sont abattus le 6 mai 1954.', role_en = 'Secretly lent by the USAF from April 1953 and painted in French markings, the C-119s were flown by French Air Force crews and by CAT Americans. Over Dien Bien Phu they dropped supplies, ammunition and napalm; McGovern and Buford were shot down there on 6 May 1954.', sources = 'https://archive.org/download/DTIC_ADA384883/DTIC_ADA384883_text.pdf
https://www.airandspaceforces.com/PDF/MagazineArchive/Documents/2004/August%202004/0804dien.pdf
https://en.wikipedia.org/wiki/Battle_of_Dien_Bien_Phu
https://fr.wikipedia.org/wiki/Bataille_de_Di%C3%AAn_Bi%C3%AAn_Phu
https://en.wikipedia.org/wiki/Fairchild_C-119_Flying_Boxcar'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'C-119 Flying Boxcar' AND w.name = 'Guerre d''Indochine'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), 'Prêtés en secret par l’USAF à partir d’avril 1953, aux couleurs françaises, les C-119 sont pilotés par l’armée de l’air et par les Américains de la CAT. À Diên Biên Phu, ils larguent vivres, munitions et napalm ; McGovern et Buford y sont abattus le 6 mai 1954.', 'Secretly lent by the USAF from April 1953 and painted in French markings, the C-119s were flown by French Air Force crews and by CAT Americans. Over Dien Bien Phu they dropped supplies, ammunition and napalm; McGovern and Buford were shot down there on 6 May 1954.', 'https://archive.org/download/DTIC_ADA384883/DTIC_ADA384883_text.pdf
https://www.airandspaceforces.com/PDF/MagazineArchive/Documents/2004/August%202004/0804dien.pdf
https://en.wikipedia.org/wiki/Battle_of_Dien_Bien_Phu
https://fr.wikipedia.org/wiki/Bataille_de_Di%C3%AAn_Bi%C3%AAn_Phu
https://en.wikipedia.org/wiki/Fairchild_C-119_Flying_Boxcar');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), role = 'Le 20 avril 1954, des C-124 de l’US Air Force embarquent à Orly plus de 600 parachutistes coloniaux, puis des renforts en Afrique du Nord, et les déposent en Indochine sur des terrains hors des zones de combat, pour soutenir la défense de Diên Biên Phu.', role_en = 'On 20 April 1954, US Air Force C-124s loaded more than 600 French colonial paratroopers at Orly, then reinforcements in North Africa, and flew them to Indochina, landing outside the combat zones, to bolster the defence of Dien Bien Phu.', sources = 'https://www.upi.com/Archives/1954/04/21/Giant-US-airlift-aiding-French/9561555637791/
https://history.state.gov/historicaldocuments/frus1952-54v13p1/d764
https://www.airandspaceforces.com/PDF/MagazineArchive/Magazine%20Documents/2007/February%202007/0207classics.pdf'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Douglas C-124 Globemaster II' AND w.name = 'Guerre d''Indochine'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), 'Le 20 avril 1954, des C-124 de l’US Air Force embarquent à Orly plus de 600 parachutistes coloniaux, puis des renforts en Afrique du Nord, et les déposent en Indochine sur des terrains hors des zones de combat, pour soutenir la défense de Diên Biên Phu.', 'On 20 April 1954, US Air Force C-124s loaded more than 600 French colonial paratroopers at Orly, then reinforcements in North Africa, and flew them to Indochina, landing outside the combat zones, to bolster the defence of Dien Bien Phu.', 'https://www.upi.com/Archives/1954/04/21/Giant-US-airlift-aiding-French/9561555637791/
https://history.state.gov/historicaldocuments/frus1952-54v13p1/d764
https://www.airandspaceforces.com/PDF/MagazineArchive/Magazine%20Documents/2007/February%202007/0207classics.pdf');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), role = 'Arrivés à Tourane le 17 avril 1954, les pilotes de la flottille 14F reçoivent le lendemain 25 Corsair AU-1 ex-Marines livrés par l’USS *Saipan*. En trois mois, ils effectuent 959 sorties de combat, notamment en appui de Diên Biên Phu.', role_en = 'Flotilla 14F pilots reached Tourane on 17 April 1954 and the next day received 25 ex-Marine AU-1 Corsairs delivered by USS *Saipan*. In three months they flew 959 combat sorties, notably in support of Dien Bien Phu.', sources = 'https://en.wikipedia.org/wiki/Vought_F4U_Corsair
https://ibiblio.org/hyperwar/OnlineLibrary/photos/images/h84000/h84051c.htm
https://en.wikipedia.org/wiki/Flottille_14F
https://www.airandspaceforces.com/PDF/MagazineArchive/Documents/2004/August%202004/0804dien.pdf'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'F4U Corsair' AND w.name = 'Guerre d''Indochine'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), 'Arrivés à Tourane le 17 avril 1954, les pilotes de la flottille 14F reçoivent le lendemain 25 Corsair AU-1 ex-Marines livrés par l’USS *Saipan*. En trois mois, ils effectuent 959 sorties de combat, notamment en appui de Diên Biên Phu.', 'Flotilla 14F pilots reached Tourane on 17 April 1954 and the next day received 25 ex-Marine AU-1 Corsairs delivered by USS *Saipan*. In three months they flew 959 combat sorties, notably in support of Dien Bien Phu.', 'https://en.wikipedia.org/wiki/Vought_F4U_Corsair
https://ibiblio.org/hyperwar/OnlineLibrary/photos/images/h84000/h84051c.htm
https://en.wikipedia.org/wiki/Flottille_14F
https://www.airandspaceforces.com/PDF/MagazineArchive/Documents/2004/August%202004/0804dien.pdf');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), role = 'Livré à partir de février 1951, le Bearcat équipe les groupes de chasse en chasseur-bombardier et avion de reconnaissance : bombes, roquettes, napalm. Ceux basés à Diên Biên Phu sont détruits au sol ou chassés dès le 13 mars 1954.', role_en = 'Delivered from February 1951, the Bearcat equipped the fighter groups as a fighter-bomber and reconnaissance aircraft: bombs, rockets, napalm. Those based at Dien Bien Phu were destroyed on the ground or driven off from 13 March 1954.', sources = 'https://fr.wikipedia.org/wiki/Grumman_F8F_Bearcat
https://en.wikipedia.org/wiki/Grumman_F8F_Bearcat
https://archive.org/download/DTIC_ADA384883/DTIC_ADA384883_text.pdf
https://www.airandspaceforces.com/PDF/MagazineArchive/Documents/2004/August%202004/0804dien.pdf'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'F8F Bearcat' AND w.name = 'Guerre d''Indochine'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france'), 'Livré à partir de février 1951, le Bearcat équipe les groupes de chasse en chasseur-bombardier et avion de reconnaissance : bombes, roquettes, napalm. Ceux basés à Diên Biên Phu sont détruits au sol ou chassés dès le 13 mars 1954.', 'Delivered from February 1951, the Bearcat equipped the fighter groups as a fighter-bomber and reconnaissance aircraft: bombs, rockets, napalm. Those based at Dien Bien Phu were destroyed on the ground or driven off from 13 March 1954.', 'https://fr.wikipedia.org/wiki/Grumman_F8F_Bearcat
https://en.wikipedia.org/wiki/Grumman_F8F_Bearcat
https://archive.org/download/DTIC_ADA384883/DTIC_ADA384883_text.pdf
https://www.airandspaceforces.com/PDF/MagazineArchive/Documents/2004/August%202004/0804dien.pdf');
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1946-12-19', 'day', 'Le soulèvement de Hanoï', 'The Hanoi uprising', 'Le Viêt Minh attaque les Français à Hanoï : c’est le début de la guerre d’Indochine, un mois après le bombardement de Haiphong.', 'The Viet Minh attacked the French in Hanoi, starting the Indochina War a month after the shelling of Haiphong.', NULL::int, 'https://en.wikipedia.org/wiki/First_Indochina_War' FROM wars w WHERE w.name = 'Guerre d''Indochine'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1951-01-01', 'month', 'Vĩnh Yên', 'Vinh Yen', 'L’aviation contribue à briser l’offensive de Giáp vers le delta du Tonkin, lors du plus important bombardement aérien de la guerre.', 'Air power helped break Giap''s offensive towards the Tonkin delta in the largest aerial bombardment of the war.', NULL::int, 'https://en.wikipedia.org/wiki/First_Indochina_War' FROM wars w WHERE w.name = 'Guerre d''Indochine'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1951-02-01', 'month', 'Arrivée des Bearcat', 'The Bearcats arrive', 'Une première tranche de 44 F8F Bearcat cédés par les États-Unis est livrée à Saïgon, suivie de 46 autres en mars.', 'A first batch of 44 F8F Bearcats supplied by the United States was delivered to Saigon, followed by 46 more in March.', (SELECT id FROM airplanes WHERE name = 'F8F Bearcat'), 'https://fr.wikipedia.org/wiki/Grumman_F8F_Bearcat' FROM wars w WHERE w.name = 'Guerre d''Indochine'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1952-12-04', 'day', 'Na San tient', 'Na San holds', 'Ravitaillé par un pont aérien depuis le 16 octobre, le camp retranché a repoussé l’assaut général des 1er et 2 décembre ; Giáp retire ses divisions.', 'Supplied by an air bridge since 16 October, the fortified camp had repelled the general assault of 1-2 December; Giap withdrew his divisions.', NULL::int, 'https://fr.wikipedia.org/wiki/Bataille_de_Na_San' FROM wars w WHERE w.name = 'Guerre d''Indochine'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1953-04-01', 'month', 'Les premiers C-119 prêtés', 'First C-119s on loan', 'Face à l’invasion du Laos, le Pentagone prête six C-119 aux forces françaises, pilotés par des civils américains de la CAT.', 'With Laos under invasion, the Pentagon lent six C-119s to French forces, flown by American civilians of CAT.', (SELECT id FROM airplanes WHERE name = 'C-119 Flying Boxcar'), 'https://archive.org/download/DTIC_ADA384883/DTIC_ADA384883_text.pdf' FROM wars w WHERE w.name = 'Guerre d''Indochine'
