INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1954-04-21', 'day', 'Le pont aérien depuis la France', 'The airlift from France', 'Washington annonce que l’US Air Force transporte des renforts français vers l’Indochine ; la veille, des parachutistes ont embarqué à Orly dans des C-124.', 'Washington announced that the US Air Force was flying French reinforcements to Indochina; the day before, paratroopers had boarded C-124s at Orly.', (SELECT id FROM airplanes WHERE name = 'Douglas C-124 Globemaster II'), 'https://www.upi.com/Archives/1954/04/21/Giant-US-airlift-aiding-French/9561555637791/' FROM wars w WHERE w.name = 'Guerre d''Indochine'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1954-05-06', 'day', 'McGovern et Buford abattus', 'McGovern and Buford shot down', 'Touché par la DCA lors d’un largage sur Diên Biên Phu, le C-119 des pilotes de la CAT s’écrase en territoire tenu par le Viêt Minh.', 'Hit by flak on a Dien Bien Phu airdrop, the CAT pilots'' C-119 crashed in Viet Minh-held territory.', (SELECT id FROM airplanes WHERE name = 'C-119 Flying Boxcar'), 'https://www.airandspaceforces.com/PDF/MagazineArchive/Documents/2004/August%202004/0804dien.pdf' FROM wars w WHERE w.name = 'Guerre d''Indochine'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
