INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1954-05-07', 'day', 'Chute de Diên Biên Phu', 'Fall of Dien Bien Phu', 'Après 56 jours de siège, le camp retranché tombe ; l’aviation n’a pu ni le ravitailler suffisamment ni faire taire l’artillerie adverse.', 'After a 56-day siege the fortress fell; air power had been able neither to supply it adequately nor to silence the enemy guns.', NULL::int, 'https://en.wikipedia.org/wiki/Battle_of_Dien_Bien_Phu' FROM wars w WHERE w.name = 'Guerre d''Indochine'
