INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'coalition', 1, 'Coalition', 'Coalition', 'États-Unis, Royaume-Uni, Australie, Pologne et forces kurdes (invasion de 2003), puis Force multinationale en Irak et nouvelles forces de sécurité irakiennes', 'United States, United Kingdom, Australia, Poland and Kurdish forces (2003 invasion), then the Multi-National Force – Iraq and the new Iraqi security forces' FROM wars w WHERE w.name = 'Guerre d''Irak'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'irak', 2, 'Irak baasiste puis insurrection', 'Ba''athist Iraq, then the insurgency', 'Forces armées de Saddam Hussein (2003), puis groupes insurgés sunnites et chiites, dont al-Qaïda en Irak', 'Saddam Hussein''s armed forces (2003), then Sunni and Shia insurgent groups, including al-Qaeda in Iraq' FROM wars w WHERE w.name = 'Guerre d''Irak'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre d''Irak' AND s.side_key NOT IN ('coalition', 'irak');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Soixante A-10 appuient les troupes au sol et sont les premiers avions alliés basés en Irak (Tallil, 4 avril 2003). Le 7 avril, Kim Campbell ramène un A-10 criblé d''éclats ; le lendemain, un autre est abattu par un missile Roland. L''A-10C y est engagé dès 2007.', role_en = 'Sixty A-10s supported ground troops and were the first coalition aircraft based in Iraq (Tallil, 4 April 2003). On 7 April Kim Campbell nursed a flak-riddled A-10 home; the next day another was shot down by a Roland missile. The A-10C fought there from 2007.', sources = 'https://en.wikipedia.org/wiki/Fairchild_Republic_A-10_Thunderbolt_II
https://www.comw.org/pda/fulltext/oifcentaf.pdf
https://en.wikipedia.org/wiki/List_of_aviation_shootdowns_and_accidents_during_the_Iraq_War
https://en.wikipedia.org/wiki/Second_Battle_of_Fallujah'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'A-10 Thunderbolt II' AND w.name = 'Guerre d''Irak'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Soixante A-10 appuient les troupes au sol et sont les premiers avions alliés basés en Irak (Tallil, 4 avril 2003). Le 7 avril, Kim Campbell ramène un A-10 criblé d''éclats ; le lendemain, un autre est abattu par un missile Roland. L''A-10C y est engagé dès 2007.', 'Sixty A-10s supported ground troops and were the first coalition aircraft based in Iraq (Tallil, 4 April 2003). On 7 April Kim Campbell nursed a flak-riddled A-10 home; the next day another was shot down by a Roland missile. The A-10C fought there from 2007.', 'https://en.wikipedia.org/wiki/Fairchild_Republic_A-10_Thunderbolt_II
https://www.comw.org/pda/fulltext/oifcentaf.pdf
https://en.wikipedia.org/wiki/List_of_aviation_shootdowns_and_accidents_during_the_Iraq_War
