UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Les F/A-18E/F des VFA-14, VFA-41 et VFA-115 assurent frappes, escorte, appui rapproché et contrôle aérien avancé. Ceux du VFA-14 servent surtout de ravitailleurs, premier emploi du Super Hornet dans ce rôle. Leur baptême du feu date de novembre 2002, au-dessus de l''Irak.', role_en = 'VFA-14, VFA-41 and VFA-115 F/A-18E/Fs flew strike, escort, close air support and forward air control missions. VFA-14''s jets served mostly as tankers, the Super Hornet''s first use in that role. Their combat debut came in November 2002, over Iraq.', sources = 'https://en.wikipedia.org/wiki/Boeing_F/A-18E/F_Super_Hornet
https://www.comw.org/pda/fulltext/oifcentaf.pdf'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'F/A-18E Super Hornet' AND w.name = 'Guerre d''Irak'
