UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Quarante S-3 en 2003. Un S-3B du VS-38 tire à Bassorah le premier Maverick à guidage laser de l''histoire du type ; le 1er mai 2003, un S-3B « Navy One » emmène George W. Bush sur l''Abraham Lincoln. En 2008, quatre S-3B effectuent plus de 350 missions de renseignement depuis Al Asad.', role_en = 'Forty S-3s in 2003. A VS-38 S-3B fired the type''s first laser-guided Maverick in combat at Basra; on 1 May 2003 an S-3B, "Navy One", flew George W. Bush to Abraham Lincoln. In 2008 four S-3Bs flew more than 350 reconnaissance missions from Al Asad.', sources = 'https://en.wikipedia.org/wiki/Lockheed_S-3_Viking
