UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Premier déploiement de combat du MV-22 : annoncé en avril 2007, à Al Asad. Dans la province d''Anbar, les Osprey des Marines assurent transport et reconnaissance ; en juillet 2008, ils totalisent 3 000 sorties et 5 200 heures de vol en Irak, sans perte au combat.', role_en = 'The MV-22''s first combat deployment, announced in April 2007, was at Al Asad. In Anbar province Marine Ospreys flew transport and scouting missions; by July 2008 they had logged 3,000 sorties and 5,200 flight hours in Iraq, with no combat losses.', sources = 'https://en.wikipedia.org/wiki/Bell_Boeing_V-22_Osprey'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'V-22 Osprey' AND w.name = 'Guerre d''Irak'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Premier déploiement de combat du MV-22 : annoncé en avril 2007, à Al Asad. Dans la province d''Anbar, les Osprey des Marines assurent transport et reconnaissance ; en juillet 2008, ils totalisent 3 000 sorties et 5 200 heures de vol en Irak, sans perte au combat.', 'The MV-22''s first combat deployment, announced in April 2007, was at Al Asad. In Anbar province Marine Ospreys flew transport and scouting missions; by July 2008 they had logged 3,000 sorties and 5,200 flight hours in Iraq, with no combat losses.', 'https://en.wikipedia.org/wiki/Bell_Boeing_V-22_Osprey');
