INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2002-12-23', 'day', 'Un MiG-25 abat un Predator', 'A MiG-25 downs a Predator', 'Trois mois avant la guerre, un MiG-25 irakien abat un Predator armé qui patrouillait la zone d''exclusion aérienne : c''est la dernière victoire aérienne de l''aviation irakienne.', 'Three months before the war, an Iraqi MiG-25 shot down an armed Predator patrolling the no-fly zone: the Iraqi Air Force''s last air-to-air kill.', (SELECT id FROM airplanes WHERE name = 'MQ-1 Predator'), 'https://en.wikipedia.org/wiki/General_Atomics_MQ-1_Predator' FROM wars w WHERE w.name = 'Guerre d''Irak'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2003-03-20', 'day', 'Frappe sur Dora Farms', 'Strike on Dora Farms', 'Deux F-117 larguent des bombes antibunker EGBU-27 sur Dora Farms, où Saddam Hussein était censé se trouver : ce sont les premières bombes de la guerre. Le dictateur était parti quelques heures plus tôt.', 'Two F-117s dropped EGBU-27 bunker busters on Dora Farms, where Saddam Hussein was thought to be: the first bombs of the war. He had left a few hours earlier.', (SELECT id FROM airplanes WHERE name = 'F-117 Nighthawk'), 'https://en.wikipedia.org/wiki/Lockheed_F-117_Nighthawk' FROM wars w WHERE w.name = 'Guerre d''Irak'
