INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2003-03-23', 'day', 'Un Tornado abattu par un Patriot', 'Tornado downed by a Patriot', 'Au retour d''une mission, un Tornado GR4A de la RAF est abattu par erreur par une batterie Patriot américaine ; ses deux aviateurs sont tués.', 'Returning from a mission, an RAF Tornado GR4A was shot down in error by a US Patriot battery, killing both crew.', (SELECT id FROM airplanes WHERE name = 'Panavia Tornado'), 'https://en.wikipedia.org/wiki/List_of_aviation_shootdowns_and_accidents_during_the_Iraq_War' FROM wars w WHERE w.name = 'Guerre d''Irak'
