INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2003-03-26', 'day', 'Parachutage sur Bashur', 'Airdrop on Bashur', 'Quinze C-17 larguent de nuit environ un millier de parachutistes de la 173e brigade aéroportée sur Bashur, au Kurdistan irakien : le front nord est ouvert.', 'Fifteen C-17s dropped about a thousand paratroopers of the 173rd Airborne Brigade on Bashur in Iraqi Kurdistan at night, opening the northern front.', (SELECT id FROM airplanes WHERE name = 'C-17 Globemaster III'), 'https://en.wikipedia.org/wiki/Boeing_C-17_Globemaster_III' FROM wars w WHERE w.name = 'Guerre d''Irak'
