SELECT w.id, DATE '2003-04-07', 'day', 'Un B-1 vise Saddam Hussein', 'A B-1 targets Saddam Hussein', 'Un B-1B largue des JDAM sur un bâtiment de Bagdad où Saddam Hussein et ses deux fils étaient censés se trouver ; la tentative échoue.', 'A B-1B dropped JDAMs on a Baghdad building where Saddam Hussein and his two sons were thought to be; the attempt failed.', (SELECT id FROM airplanes WHERE name = 'B-1 Lancer'), 'https://en.wikipedia.org/wiki/Rockwell_B-1_Lancer' FROM wars w WHERE w.name = 'Guerre d''Irak'
