SELECT w.id, DATE '2004-11-08', 'day', 'Seconde bataille de Falloujah', 'Second Battle of Fallujah', 'L''assaut contre Falloujah, tenue par les insurgés, s''ouvre par des frappes aériennes ; AC-130, F-15E, F-16, A-10 et B-52 appuient ensuite les combats de rue.', 'The assault on insurgent-held Fallujah opened with air strikes; AC-130s, F-15Es, F-16s, A-10s and B-52s then supported the street fighting.', NULL::int, 'https://en.wikipedia.org/wiki/Second_Battle_of_Fallujah' FROM wars w WHERE w.name = 'Guerre d''Irak'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2005-01-30', 'day', 'Un Hercules de la RAF abattu', 'RAF Hercules shot down', 'Entre Bagdad et Balad, un C-130K de la RAF est abattu par des tirs venus du sol : les dix occupants sont tués.', 'Between Baghdad and Balad an RAF C-130K was brought down by ground fire, killing all ten aboard.', (SELECT id FROM airplanes WHERE name = 'C-130 Hercules'), 'https://en.wikipedia.org/wiki/2005_Royal_Air_Force_Hercules_shootdown' FROM wars w WHERE w.name = 'Guerre d''Irak'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2006-06-07', 'day', 'Mort de Zarqaoui', 'Death of Zarqawi', 'Deux F-16 de l''USAF bombardent une maison où se cache Abou Moussab al-Zarqaoui, chef d''al-Qaïda en Irak, qui est tué.', 'Two USAF F-16s bombed a safe house where Abu Musab al-Zarqawi, leader of al-Qaeda in Iraq, was hiding, killing him.', (SELECT id FROM airplanes WHERE name = 'F-16 Fighting Falcon'), 'https://en.wikipedia.org/wiki/General_Dynamics_F-16_Fighting_Falcon_operational_history' FROM wars w WHERE w.name = 'Guerre d''Irak'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2007-01-10', 'day', 'Annonce du surge', 'Surge announced', 'George W. Bush annonce l''envoi de plus de 20 000 soldats supplémentaires. Dans les airs aussi, l''effort s''intensifie : 1 447 bombes larguées en 2007, contre 229 en 2006.', 'George W. Bush announced more than 20,000 extra troops. The effort grew in the air too: 1,447 bombs were dropped in 2007, against 229 in 2006.', NULL::int, 'https://en.wikipedia.org/wiki/Iraq_War_troop_surge_of_2007' FROM wars w WHERE w.name = 'Guerre d''Irak'
