 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2009-06-10', 'day', 'Première mission du MC-12W', 'First MC-12W mission', 'Arrivé à Balad deux jours plus tôt, le premier MC-12W Liberty effectue sa première mission de combat, fournissant vidéo en direct et écoute électronique aux troupes au sol.', 'Two days after reaching Balad, the first MC-12W Liberty flew its first combat mission, supplying live video and signals intelligence to ground troops.', (SELECT id FROM airplanes WHERE name = 'Beechcraft MC-12W Liberty'), 'https://www.airandspaceforces.com/libertyentersthefight' FROM wars w WHERE w.name = 'Guerre d''Irak'
