INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1967-07-08', 'day', 'Premier combat aérien d''après-guerre', 'First post-war air kill', 'Des Mirage de l''escadron Atalef abattent un MiG-21 égyptien venu gêner une frappe israélienne contre l''artillerie, premier succès aérien depuis la guerre des Six Jours.', 'Mirages of the Atalef squadron shoot down an Egyptian MiG-21 trying to disrupt an Israeli strike on artillery, the first air kill since the Six-Day War.', (SELECT id FROM airplanes WHERE name = 'Mirage IIICJ Shahak'), 'https://www.jewishvirtuallibrary.org/dassault-mirage-iiicj-shahak' FROM wars w WHERE w.name = 'Guerre d''usure'
