INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1970-04-08', 'day', 'Bombardement de Bahr el-Baqar', 'Bahr el-Baqar bombing', 'Des F-4 israéliens frappent une école primaire prise pour une installation militaire et tuent 46 ou 47 enfants selon les sources ; les raids en profondeur prennent fin peu après.', 'Israeli F-4s hit a primary school mistaken for a military site, killing 46 or 47 children depending on the source; the deep raids end shortly afterwards.', (SELECT id FROM airplanes WHERE name = 'F-4E Kurnass'), 'https://en.wikipedia.org/wiki/Operation_Priha' FROM wars w WHERE w.name = 'Guerre d''usure'
