INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1970-07-30', 'day', 'Embuscade Rimon 20', 'The Rimon 20 ambush', 'Douze Mirage et quatre F-4E attirent une vingtaine de MiG-21 pilotés par des Soviétiques dans une embuscade : cinq MiG sont détruits, sans perte israélienne.', 'Twelve Mirages and four F-4Es lure some two dozen Soviet-flown MiG-21s into an ambush: five MiGs are destroyed with no Israeli loss.', (SELECT id FROM airplanes WHERE name = 'MiG-21'), 'https://en.wikipedia.org/wiki/Operation_Rimon_20' FROM wars w WHERE w.name = 'Guerre d''usure'
