INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'onu', 1, 'Forces de l''ONU', 'UN forces', 'Corée du Sud, États-Unis, Royaume-Uni, Australie, Canada, Afrique du Sud, Nouvelle-Zélande, France, Turquie, Grèce, Belgique, Luxembourg, Pays-Bas, Colombie, Éthiopie, Philippines, Thaïlande', 'South Korea, United States, United Kingdom, Australia, Canada, South Africa, New Zealand, France, Turkey, Greece, Belgium, Luxembourg, Netherlands, Colombia, Ethiopia, Philippines, Thailand' FROM wars w WHERE w.name = 'Guerre de Corée'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'nord', 2, 'Corée du Nord et alliés', 'North Korea and allies', 'Corée du Nord, Chine, URSS (engagement aérien non reconnu à l''époque)', 'North Korea, China, USSR (air involvement not acknowledged at the time)' FROM wars w WHERE w.name = 'Guerre de Corée'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
