INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1950-06-25', 'day', 'Invasion du Sud, Kimpo mitraillé', 'Invasion of the South, Kimpo strafed', 'La Corée du Nord franchit le 38e parallèle. Ses chasseurs attaquent Kimpo et Séoul et détruisent au sol un C-54, premier avion de l''US Air Force perdu dans la guerre.', 'North Korea crosses the 38th parallel. Its fighters attack Kimpo and Seoul and destroy a C-54 on the ground, the first USAF aircraft lost in the war.', (SELECT id FROM airplanes WHERE name = 'Douglas C-54 Skymaster'), 'https://en.wikipedia.org/wiki/USAF_units_and_aircraft_of_the_Korean_War' FROM wars w WHERE w.name = 'Guerre de Corée'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1950-06-27', 'day', 'Premières victoires américaines au-dessus de Kimpo', 'First American victories over Kimpo', 'Des F-82G couvrent les C-54 qui évacuent les derniers civils de Kimpo et abattent trois des cinq chasseurs nord-coréens venus les attaquer.', 'F-82Gs covering the C-54s evacuating the last civilians from Kimpo shoot down three of the five North Korean fighters that attack them.', (SELECT id FROM airplanes WHERE name = 'F-82 Twin Mustang'), 'https://en.wikipedia.org/wiki/North_American_F-82_Twin_Mustang' FROM wars w WHERE w.name = 'Guerre de Corée'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1950-06-29', 'day', 'Premier bombardement de la Corée du Nord', 'First bombing raid on North Korea', 'Des B-26 du 3rd Bombardment Group mènent la première mission de bombardement de l''US Air Force sur le Nord, contre un aérodrome proche de Pyongyang.', 'B-26s of the 3rd Bombardment Group fly the USAF''s first bombing mission against the North, hitting an airfield near Pyongyang.', (SELECT id FROM airplanes WHERE name = 'A-26 Invader'), 'https://en.wikipedia.org/wiki/Douglas_A-26_Invader' FROM wars w WHERE w.name = 'Guerre de Corée'
