INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1950-07-03', 'day', 'Entrée en guerre des porte-avions', 'Carriers go into action', 'L''USS *Valley Forge* et le HMS *Triumph* lancent leurs premiers raids sur le Nord. Deux F9F-3 Panther abattent deux Yak-9 : premières victoires de jets de l''US Navy.', 'USS *Valley Forge* and HMS *Triumph* launch their first strikes on the North. Two F9F-3 Panthers shoot down two Yak-9s, the US Navy''s first jet victories.', (SELECT id FROM airplanes WHERE name = 'F9F Panther'), 'https://www.history.navy.mil/browse-by-topic/communities/naval-aviation/1950-1953.html' FROM wars w WHERE w.name = 'Guerre de Corée'
