INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1950-11-01', 'day', 'Apparition du MiG-15', 'The MiG-15 appears', 'Des MiG-15 soviétiques interceptent des avions américains près du Yalu. Le même jour a lieu le premier combat entre avions à réaction, contre des F-80.', 'Soviet MiG-15s intercept American aircraft near the Yalu. The same day sees the first jet-versus-jet combat, against F-80s.', (SELECT id FROM airplanes WHERE name = 'MiG-15'), 'https://en.wikipedia.org/wiki/MiG_Alley' FROM wars w WHERE w.name = 'Guerre de Corée'
