INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1950-11-09', 'day', 'Premier MiG-15 détruit', 'First MiG-15 destroyed', 'Le capitaine de corvette William Amen, sur F9F-2B Panther, abat un MiG-15 lors d''une attaque des ponts de Sinuiju. Une revendication d''un pilote de F-80, la veille, n''est pas confirmée par les archives soviétiques.', 'Lieutenant Commander William Amen, flying an F9F-2B Panther, downs a MiG-15 during a strike on the Sinuiju bridges. An F-80 pilot''s claim from the previous day is not borne out by Soviet records.', (SELECT id FROM airplanes WHERE name = 'F9F Panther'), 'https://en.wikipedia.org/wiki/Grumman_F9F_Panther' FROM wars w WHERE w.name = 'Guerre de Corée'
