       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1950-12-01', 'month', 'Un pont parachuté à Koto-ri', 'A bridge dropped at Koto-ri', 'Pendant la retraite du réservoir de Chosin, huit C-119 parachutent des travées de pont métalliques qui permettent aux troupes encerclées de rejoindre Hungnam.', 'During the retreat from the Chosin Reservoir, eight C-119s parachute steel bridge sections that let the encircled troops reach Hungnam.', (SELECT id FROM airplanes WHERE name = 'C-119 Flying Boxcar'), 'https://en.wikipedia.org/wiki/Fairchild_C-119_Flying_Boxcar' FROM wars w WHERE w.name = 'Guerre de Corée'
