INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1950-12-17', 'day', 'Un Sabre abat un MiG près du Yalu', 'A Sabre downs a MiG near the Yalu', 'Trois escadrons de F-86 viennent d''arriver. Le lieutenant-colonel Bruce Hinton mène une patrouille de quatre Sabre le long du Yalu et abat le MiG-15 du major Iakov Efromeïenko, qui s''éjecte.', 'Three F-86 squadrons have just arrived. Lieutenant Colonel Bruce Hinton leads four Sabres along the Yalu and shoots down Major Yakov Efromeenko''s MiG-15; the Soviet pilot ejects.', (SELECT id FROM airplanes WHERE name = 'F-86 Sabre'), 'https://en.wikipedia.org/wiki/MiG_Alley' FROM wars w WHERE w.name = 'Guerre de Corée'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
