INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1951-04-12', 'day', 'Le « jeudi noir » des B-29', 'The B-29s'' “Black Thursday”', 'Une trentaine de MiG-15 fondent sur 48 B-29 escortés : trois bombardiers abattus, sept endommagés. Les sorties de jour des bombardiers sont suspendues près de trois mois.', 'About thirty MiG-15s fall on 48 escorted B-29s: three bombers are shot down and seven damaged. Daylight bomber sorties are halted for about three months.', (SELECT id FROM airplanes WHERE name = 'B-29 Superfortress'), 'https://en.wikipedia.org/wiki/MiG_Alley' FROM wars w WHERE w.name = 'Guerre de Corée'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
