INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1951-10-23', 'day', 'Namsi, la fin des raids de jour', 'Namsi ends the daylight raids', 'Sur neuf B-29 envoyés contre l''aérodrome de Namsi, six ne rentrent pas à leur base. Les Superfortress ne bombarderont plus que de nuit.', 'Of nine B-29s sent against Namsi airfield, six fail to return to base. From now on the Superfortresses bomb only at night.', (SELECT id FROM airplanes WHERE name = 'B-29 Superfortress'), 'https://migflug.com/afterburner/black-tuesday-namsi-1951-b-29-mig-15/' FROM wars w WHERE w.name = 'Guerre de Corée'
