INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1951-12-01', 'day', 'Bataille de Sunchon', 'Battle of Sunchon', 'Quatorze Meteor australiens affrontent au moins vingt MiG-15 pilotés par des Soviétiques ; trois Meteor sont perdus. La RAAF repasse ensuite le Meteor à l''attaque au sol.', 'Fourteen Australian Meteors fight at least twenty Soviet-flown MiG-15s and lose three aircraft. The RAAF then switches the Meteor back to ground attack.', (SELECT id FROM airplanes WHERE name = 'Gloster Meteor'), 'https://en.wikipedia.org/wiki/Gloster_Meteor' FROM wars w WHERE w.name = 'Guerre de Corée'
