INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1952-06-23', 'day', 'Les centrales du Nord frappées', 'The North''s power plants struck', 'Avions embarqués et chasseurs-bombardiers de l''US Air Force attaquent le barrage de Sui-ho et huit autres centrales : environ 90 % de la production électrique du Nord est détruite.', 'Carrier aircraft and USAF fighter-bombers attack the Sui-ho dam and eight other plants, destroying about 90% of the North''s power production.', (SELECT id FROM airplanes WHERE name = 'A-1 Skyraider'), 'https://en.wikipedia.org/wiki/Attack_on_the_Sui-ho_Dam' FROM wars w WHERE w.name = 'Guerre de Corée'
