SELECT w.id, DATE '1952-11-02', 'day', 'Première victoire de nuit au radar entre jets', 'First radar night kill between jets', 'Un F3D-2 Skyknight du VMF(N)-513 abat de nuit un avion à réaction ennemi, repéré et poursuivi au radar.', 'A VMF(N)-513 F3D-2 Skyknight shoots down an enemy jet at night after a radar interception.', (SELECT id FROM airplanes WHERE name = 'F3D Skyknight'), 'https://en.wikipedia.org/wiki/Douglas_F3D_Skyknight' FROM wars w WHERE w.name = 'Guerre de Corée'
