INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'inde', 1, 'Inde', 'India', 'Inde (armée de terre, Indian Air Force)', 'India (Army, Indian Air Force)' FROM wars w WHERE w.name = 'Guerre de Kargil'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'pakistan', 2, 'Pakistan', 'Pakistan', 'Pakistan : Northern Light Infantry, Special Services Group, avec des combattants irréguliers selon certaines sources', 'Pakistan: Northern Light Infantry, Special Services Group, with irregular fighters according to some sources' FROM wars w WHERE w.name = 'Guerre de Kargil'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre de Kargil' AND s.side_key NOT IN ('inde', 'pakistan');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'inde'), role = 'Le 21 mai, un Canberra PR.57 du 106e escadron en reconnaissance photo est touché à un moteur par un missile portable et rentre sur l''autre à Srinagar ; les Canberra photographient ensuite les positions avec les MiG-25R.', role_en = 'On 21 May a No. 106 Squadron Canberra PR.57 on photo reconnaissance was hit in one engine by a shoulder-fired missile and returned to Srinagar on the other; Canberras then photographed enemy positions alongside MiG-25Rs.', sources = 'https://en.wikipedia.org/wiki/English_Electric_Canberra
https://en.wikipedia.org/wiki/Operation_Safed_Sagar
https://www.airandspaceforces.com/article/0912kargil/'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'English Electric Canberra' AND w.name = 'Guerre de Kargil'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'inde'), 'Le 21 mai, un Canberra PR.57 du 106e escadron en reconnaissance photo est touché à un moteur par un missile portable et rentre sur l''autre à Srinagar ; les Canberra photographient ensuite les positions avec les MiG-25R.', 'On 21 May a No. 106 Squadron Canberra PR.57 on photo reconnaissance was hit in one engine by a shoulder-fired missile and returned to Srinagar on the other; Canberras then photographed enemy positions alongside MiG-25Rs.', 'https://en.wikipedia.org/wiki/English_Electric_Canberra
