INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1999-05-03', 'day', 'Début du conflit', 'The conflict begins', 'Date retenue pour le début du conflit : les premières infiltrations sont repérées au début de mai, et l''armée indienne découvre peu à peu que plus d''une centaine de postes sont occupés de son côté de la ligne de contrôle.', 'The date usually given for the start of the conflict: the first infiltrations are spotted in early May, and the Indian Army gradually discovers that more than a hundred posts on its side of the Line of Control have been occupied.', NULL::int, 'https://fr.wikipedia.org/wiki/Conflit_de_Kargil' FROM wars w WHERE w.name = 'Guerre de Kargil'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
