INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1999-05-21', 'day', 'Un Canberra touché par un missile', 'A Canberra hit by a missile', 'Un Canberra PR.57 en mission photographique près de la ligne de contrôle est touché à un moteur par un missile sol-air portable ; il rentre à Srinagar sur l''autre moteur.', 'A Canberra PR.57 on a photographic sortie near the Line of Control is hit in one engine by a shoulder-fired missile; it returns to Srinagar on its other engine.', (SELECT id FROM airplanes WHERE name = 'English Electric Canberra'), 'https://en.wikipedia.org/wiki/English_Electric_Canberra' FROM wars w WHERE w.name = 'Guerre de Kargil'
