INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'ethiopie', 1, 'Éthiopie et ses alliés', 'Ethiopia and its allies', 'Éthiopie du Derg (Mengistu Haïlé Mariam) ; Union soviétique (pont aérien, armes, conseillers du général Petrov) ; Cuba (12 000 à 18 000 soldats et des pilotes) ; Yémen du Sud', 'Derg-ruled Ethiopia (Mengistu Haile Mariam); Soviet Union (airlift, arms, advisers under General Petrov); Cuba (12,000 to 18,000 troops and pilots); South Yemen' FROM wars w WHERE w.name = 'Guerre de l''Ogaden'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'somalie', 2, 'Somalie', 'Somalia', 'République démocratique somalie de Siad Barre et Front de libération de la Somalie occidentale (FLSO)', 'Siad Barre’s Somali Democratic Republic and the Western Somali Liberation Front (WSLF)' FROM wars w WHERE w.name = 'Guerre de l''Ogaden'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre de l''Ogaden' AND s.side_key NOT IN ('ethiopie', 'somalie');
