INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1977-07-13', 'day', 'L’invasion somalienne', 'The Somali invasion', 'L’armée somalienne et le FLSO entrent en force dans l’Ogaden ; selon les sources, l’invasion commence le 12, le 13 ou le 23 juillet 1977.', 'The Somali army and the WSLF pour into the Ogaden; sources date the start of the invasion to 12, 13 or 23 July 1977.', NULL::int, 'https://en.wikipedia.org/wiki/Ogaden_War' FROM wars w WHERE w.name = 'Guerre de l''Ogaden'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
