INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'afrique-du-sud', 1, 'Afrique du Sud et UNITA', 'South Africa and UNITA', 'Afrique du Sud (SADF, SAAF), forces territoriales et police du Sud-Ouest africain (SWATF, SWAPOL), UNITA', 'South Africa (SADF, SAAF), South West African territorial forces and police (SWATF, SWAPOL), UNITA' FROM wars w WHERE w.name = 'Guerre de la frontière sud-africaine'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'angola-cuba-swapo', 2, 'Angola, Cuba et SWAPO, soutenus par l’URSS', 'Angola, Cuba and SWAPO, backed by the Soviet Union', 'Angola (FAPLA et force aérienne FAPA-DAA), Cuba (FAR et DAAFAR), SWAPO (PLAN), conseillers soviétiques', 'Angola (FAPLA and the FAPA-DAA air force), Cuba (FAR and DAAFAR), SWAPO (PLAN), Soviet advisers' FROM wars w WHERE w.name = 'Guerre de la frontière sud-africaine'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre de la frontière sud-africaine' AND s.side_key NOT IN ('afrique-du-sud', 'angola-cuba-swapo');
