SELECT w.id, DATE '1966-08-26', 'day', 'Attaque d’Omugulugwombashe', 'Attack on Omugulugwombashe', 'Parachutistes et policiers sud-africains attaquent le camp de la SWALA à Omugulugwombashe, dans le nord du Sud-Ouest africain : la guerre commence.', 'South African paratroopers and police attack the SWALA camp at Omugulugwombashe in northern South West Africa: the war begins.', NULL::int, 'https://en.wikipedia.org/wiki/South_African_Border_War' FROM wars w WHERE w.name = 'Guerre de la frontière sud-africaine'
