INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1991-06-27', 'day', 'Début de la guerre des Dix Jours', 'Ten-Day War begins', 'L''armée fédérale entre en Slovénie ; les Slovènes abattent deux hélicoptères de la JNA avec des missiles SA-7. Le lendemain, l''aviation frappe l''aéroport de Brnik.', 'The federal army moves into Slovenia; Slovene forces shoot down two JNA helicopters with SA-7 missiles. The next day the air force strikes Brnik airport.', NULL::int, 'https://en.wikipedia.org/wiki/Ten-Day_War' FROM wars w WHERE w.name = 'Guerre de Yougoslavie'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1991-10-07', 'day', 'Raid sur Banski dvori', 'Banski dvori raid', 'Deux MiG-21 et deux G-4 frappent le siège de la présidence croate à Zagreb, juste après que Tuđman, Mesić et Marković ont quitté la salle à manger : aucun n''est blessé.', 'Two MiG-21s and two G-4s strike the seat of the Croatian presidency in Zagreb just after Tuđman, Mesić and Marković have left the dining room; none is hurt.', (SELECT id FROM airplanes WHERE name = 'Soko G-4 Super Galeb'), 'https://en.wikipedia.org/wiki/Bombing_of_Banski_dvori' FROM wars w WHERE w.name = 'Guerre de Yougoslavie'
