SELECT w.id, DATE '1992-07-02', 'day', 'Ouverture du pont aérien de Sarajevo', 'Sarajevo airlift opens', 'Début de *Provide Promise* : jusqu''en janvier 1996, des avions de 21 pays effectuent 12 886 sorties vers Sarajevo assiégée.', '*Provide Promise* begins: until January 1996, aircraft from 21 countries fly 12,886 sorties into besieged Sarajevo.', NULL::int, 'https://en.wikipedia.org/wiki/Operation_Provide_Promise' FROM wars w WHERE w.name = 'Guerre de Yougoslavie'
