SELECT w.id, DATE '1994-02-28', 'day', 'Combat de Banja Luka', 'Banja Luka incident', 'Guidés par un AWACS, des F-16 américains abattent quatre J-21 Jastreb serbes qui violaient la zone d''exclusion ; les Serbes reconnaissent cinq pertes.', 'Directed by an AWACS, US F-16s shoot down four Serb J-21 Jastrebs violating the no-fly zone; the Serbs acknowledge five losses.', (SELECT id FROM airplanes WHERE name = 'Soko J-21 Jastreb'), 'https://en.wikipedia.org/wiki/Banja_Luka_incident' FROM wars w WHERE w.name = 'Guerre de Yougoslavie'
