INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1995-06-02', 'day', 'F-16 de Scott O''Grady abattu', 'Scott O''Grady''s F-16 shot down', 'Un SA-6 bosno-serbe abat un F-16 de l''USAF près de Mrkonjić Grad ; le capitaine O''Grady est récupéré le 8 juin.', 'A Bosnian Serb SA-6 shoots down a USAF F-16 near Mrkonjić Grad; Captain O''Grady is rescued on 8 June.', (SELECT id FROM airplanes WHERE name = 'F-16 Fighting Falcon'), 'https://en.wikipedia.org/wiki/Operation_Deny_Flight' FROM wars w WHERE w.name = 'Guerre de Yougoslavie'
