SELECT w.id, DATE '1999-03-27', 'day', 'Un F-117 abattu', 'An F-117 is shot down', 'Un S-125 du 3e bataillon de la 250e brigade abat le F-117 « Vega 31 » près de Buđanovci ; son pilote est récupéré dans la nuit.', 'An S-125 of the 3rd Battalion, 250th Brigade, shoots down F-117 "Vega 31" near Buđanovci; its pilot is rescued that night.', (SELECT id FROM airplanes WHERE name = 'F-117 Nighthawk'), 'https://en.wikipedia.org/wiki/1999_F-117A_shootdown' FROM wars w WHERE w.name = 'Guerre de Yougoslavie'
