SELECT w.id, DATE '1999-05-07', 'day', 'Frappe sur l''ambassade de Chine', 'Chinese embassy strike', 'Un B-2 largue cinq JDAM sur l''ambassade de Chine à Belgrade, à la suite d''une erreur de ciblage : trois morts.', 'A B-2 drops five JDAMs on the Chinese embassy in Belgrade after a targeting error, killing three.', (SELECT id FROM airplanes WHERE name = 'B-2 Spirit'), 'https://en.wikipedia.org/wiki/Northrop_B-2_Spirit' FROM wars w WHERE w.name = 'Guerre de Yougoslavie'
