INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'royaume-uni', 1, 'Royaume-Uni', 'United Kingdom', 'Royaume-Uni', 'United Kingdom' FROM wars w WHERE w.name = 'Guerre des Malouines'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'argentine', 2, 'Argentine', 'Argentina', 'Argentine', 'Argentina' FROM wars w WHERE w.name = 'Guerre des Malouines'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre des Malouines' AND s.side_key NOT IN ('royaume-uni', 'argentine');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'argentine'), role = 'Pilier de l’attaque argentine : les A-4B et A-4C de la Fuerza Aérea et les A-4Q de l’aéronavale frappent la flotte à basse altitude. Ils coulent le *Coventry* le 25 mai, contribuent à couler l’*Ardent* et frappent le *Sir Galahad* le 8 juin ; 22 sont perdus.', role_en = 'The backbone of the Argentine strike force: Air Force A-4Bs and A-4Cs and Navy A-4Qs attacked the fleet at low level. They sank *Coventry* on 25 May, helped sink *Ardent* and hit *Sir Galahad* on 8 June; 22 were lost.', sources = 'https://en.wikipedia.org/wiki/Douglas_A-4_Skyhawk
https://en.wikipedia.org/wiki/Argentine_air_forces_in_the_Falklands_War
https://en.wikipedia.org/wiki/Battle_of_San_Carlos_(1982)
https://en.wikipedia.org/wiki/Bluff_Cove_air_attacks'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'A-4 Skyhawk' AND w.name = 'Guerre des Malouines'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'argentine'), 'Pilier de l’attaque argentine : les A-4B et A-4C de la Fuerza Aérea et les A-4Q de l’aéronavale frappent la flotte à basse altitude. Ils coulent le *Coventry* le 25 mai, contribuent à couler l’*Ardent* et frappent le *Sir Galahad* le 8 juin ; 22 sont perdus.', 'The backbone of the Argentine strike force: Air Force A-4Bs and A-4Cs and Navy A-4Qs attacked the fleet at low level. They sank *Coventry* on 25 May, helped sink *Ardent* and hit *Sir Galahad* on 8 June; 22 were lost.', 'https://en.wikipedia.org/wiki/Douglas_A-4_Skyhawk
https://en.wikipedia.org/wiki/Argentine_air_forces_in_the_Falklands_War
https://en.wikipedia.org/wiki/Battle_of_San_Carlos_(1982)
https://en.wikipedia.org/wiki/Bluff_Cove_air_attacks');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'argentine'), role = 'Six MB-339A de l’aéronavale, basés à Port Stanley, sont les seuls jets d’attaque opérant depuis les îles. Le 21 mai, le lieutenant Owen Crippa attaque la flotte à San Carlos et touche la frégate *Argonaut* ; un autre est abattu par un missile Blowpipe le 27 mai à Goose Green.', role_en = 'Six Navy MB-339As based at Port Stanley were the only attack jets flying from the islands. On 21 May Lt Owen Crippa attacked the fleet at San Carlos and hit the frigate *Argonaut*; another was shot down by a Blowpipe missile at Goose Green on 27 May.', sources = 'https://en.wikipedia.org/wiki/Aermacchi_MB-339
https://en.wikipedia.org/wiki/Battle_of_San_Carlos_(1982)
https://en.wikipedia.org/wiki/Argentine_air_forces_in_the_Falklands_War'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Aermacchi MB-339' AND w.name = 'Guerre des Malouines'
