UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'pays-arabes'), role = 'L''Égypte perd la quasi-totalité de ses Tu-16 au sol le 5 juin, à Cairo-Ouest, Beni Souef et Louxor. Le 6 juin, des Tu-16 irakiens bombardent Israël ; l''un, abattu, s''écrase sur la base de Ramat David, tuant son équipage et des soldats israéliens.', role_en = 'Egypt lost almost all its Tu-16s on the ground on 5 June, at Cairo West, Beni Suef and Luxor. On 6 June, Iraqi Tu-16s bombed Israel; one was shot down and crashed onto Ramat David air base, killing its crew and Israeli soldiers.', sources = 'https://en.wikipedia.org/wiki/Tupolev_Tu-16
https://en.wikipedia.org/wiki/Six-Day_War
https://fr.wikipedia.org/wiki/Guerre_des_Six_Jours
https://warfarehistorynetwork.com/article/the-sinai-air-strike-june-5-1967/'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Tu-16' AND w.name = 'Guerre des Six Jours'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'pays-arabes'), 'L''Égypte perd la quasi-totalité de ses Tu-16 au sol le 5 juin, à Cairo-Ouest, Beni Souef et Louxor. Le 6 juin, des Tu-16 irakiens bombardent Israël ; l''un, abattu, s''écrase sur la base de Ramat David, tuant son équipage et des soldats israéliens.', 'Egypt lost almost all its Tu-16s on the ground on 5 June, at Cairo West, Beni Suef and Luxor. On 6 June, Iraqi Tu-16s bombed Israel; one was shot down and crashed onto Ramat David air base, killing its crew and Israeli soldiers.', 'https://en.wikipedia.org/wiki/Tupolev_Tu-16
https://en.wikipedia.org/wiki/Six-Day_War
https://fr.wikipedia.org/wiki/Guerre_des_Six_Jours
https://warfarehistorynetwork.com/article/the-sinai-air-strike-june-5-1967/');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'israel'), role = 'Le Vautour frappe les bases égyptiennes les plus lointaines, de Ras Banas à Louxor, et achève la force de bombardement égyptienne ; il attaque trois fois la base irakienne H-3, puis appuie les troupes en Cisjordanie, au Sinaï et sur le Golan. Huit sont perdus.', role_en = 'The Vautour struck the most distant Egyptian bases, from Ras Banas to Luxor, finishing off Egypt''s bomber force; it attacked Iraq''s H-3 base three times, then supported the troops on the West Bank, in the Sinai and on the Golan. Eight were lost.', sources = 'https://jewishvirtuallibrary.org/jsource/History/vautour.html
https://en.wikipedia.org/wiki/Sud_Aviation_Vautour
https://en.wikipedia.org/wiki/Six-Day_War'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Vautour II' AND w.name = 'Guerre des Six Jours'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'israel'), 'Le Vautour frappe les bases égyptiennes les plus lointaines, de Ras Banas à Louxor, et achève la force de bombardement égyptienne ; il attaque trois fois la base irakienne H-3, puis appuie les troupes en Cisjordanie, au Sinaï et sur le Golan. Huit sont perdus.', 'The Vautour struck the most distant Egyptian bases, from Ras Banas to Luxor, finishing off Egypt''s bomber force; it attacked Iraq''s H-3 base three times, then supported the troops on the West Bank, in the Sinai and on the Golan. Eight were lost.', 'https://jewishvirtuallibrary.org/jsource/History/vautour.html
https://en.wikipedia.org/wiki/Sud_Aviation_Vautour
https://en.wikipedia.org/wiki/Six-Day_War');
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1967-05-22', 'day', 'Le blocus du détroit de Tiran', 'The Straits of Tiran blockade', 'Dans la nuit du 22 au 23 mai, Nasser ferme le détroit de Tiran aux navires israéliens, trois jours après le départ des Casques bleus du Sinaï. Israël avait averti qu''il y verrait un acte de guerre.', 'On the night of 22-23 May, Nasser closed the Straits of Tiran to Israeli shipping, three days after the UN peacekeepers left the Sinai. Israel had warned it would see this as an act of war.', NULL::int, 'https://en.wikipedia.org/wiki/Six-Day_War' FROM wars w WHERE w.name = 'Guerre des Six Jours'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1967-06-05', 'day', 'L''opération *Moked*', 'Operation *Moked*', 'À 7 h 45, presque toute l''aviation israélienne frappe au ras de l''eau les aérodromes égyptiens ; la première vague en atteint onze et détruit près de 200 appareils au sol, selon le décompte israélien.', 'At 7:45 am, almost the entire Israeli Air Force struck Egypt''s airfields at wave-top height; the first wave hit eleven of them and destroyed nearly 200 aircraft on the ground, by the Israeli count.', NULL::int, 'https://en.wikipedia.org/wiki/Operation_Focus' FROM wars w WHERE w.name = 'Guerre des Six Jours'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1967-06-05', 'day', 'Les chasseurs de Hurghada surpris', 'The Hurghada fighters caught out', 'Vingt MiG-19 et MiG-21 rappelés de Hurghada vers le nord sont surpris par des Mirage près d''Abou Souweir vers 8 h 30 : quatre sont abattus, la plupart des autres s''écrasent ou sont endommagés à court de carburant.', 'Twenty MiG-19s and MiG-21s ordered north from Hurghada were bounced by Mirages near Abu Sueir around 8:30 am: four were shot down, and most of the rest crashed or were damaged when they ran out of fuel.', (SELECT id FROM airplanes WHERE name = 'MiG-19'), 'https://warfarehistorynetwork.com/article/the-sinai-air-strike-june-5-1967/' FROM wars w WHERE w.name = 'Guerre des Six Jours'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
