INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1967-06-05', 'day', 'Les bombardiers égyptiens anéantis', 'Egypt''s bombers wiped out', 'Les Vautour frappent les bases les plus lointaines, de Beni Souef à Louxor et Ras Banas, où s''étaient repliés Tu-16 et Il-28 ; à midi, la force de bombardement égyptienne n''existe plus.', 'Vautours struck the most distant bases, from Beni Suef to Luxor and Ras Banas, where Tu-16s and Il-28s had withdrawn; by noon, Egypt''s bomber force had ceased to exist.', (SELECT id FROM airplanes WHERE name = 'Vautour II'), 'https://jewishvirtuallibrary.org/jsource/History/vautour.html' FROM wars w WHERE w.name = 'Guerre des Six Jours'
