INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1967-06-05', 'day', 'L''aviation jordanienne détruite', 'The Jordanian air force destroyed', 'Après un raid de Hunter jordaniens sur Netanya, l''aviation israélienne attaque peu avant 12 h 30 les deux bases jordaniennes et y détruit les 21 Hunter du royaume.', 'After Jordanian Hunters raided Netanya, the Israeli Air Force attacked Jordan''s two air bases shortly before 12:30 pm and destroyed all 21 of the kingdom''s Hunters.', (SELECT id FROM airplanes WHERE name = 'Hawker Hunter'), 'https://en.wikipedia.org/wiki/Six-Day_War' FROM wars w WHERE w.name = 'Guerre des Six Jours'
