INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1967-06-05', 'day', 'La Syrie frappe, puis est frappée', 'Syria strikes, then is struck', 'Une douzaine de MiG-17 et MiG-21 syriens attaquent Haïfa, Degania et Megiddo. Le soir, les raids israéliens sur les aérodromes syriens détruisent environ les deux tiers de l''aviation syrienne.', 'A dozen Syrian MiG-17s and MiG-21s attacked Haifa, Degania and Megiddo. That evening, Israeli raids on Syrian airfields destroyed some two-thirds of the Syrian air force.', (SELECT id FROM airplanes WHERE name = 'MiG-17'), 'https://acig.org/artman/publish/article_260.shtml' FROM wars w WHERE w.name = 'Guerre des Six Jours'
