INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1967-06-08', 'day', 'L''attaque de l''USS *Liberty*', 'The attack on USS *Liberty*', 'Deux Mirage puis deux Super Mystère, suivis de vedettes lance-torpilles, attaquent le navire espion américain au large du Sinaï : 34 morts et 171 blessés. Israël plaide une méprise, ce que contestent des survivants.', 'Two Mirages and then two Super Mystères, followed by torpedo boats, attacked the American spy ship off the Sinai: 34 killed and 171 wounded. Israel pleaded a mistake, which survivors dispute.', (SELECT id FROM airplanes WHERE name = 'Super Mystère B2'), 'https://en.wikipedia.org/wiki/USS_Liberty_incident' FROM wars w WHERE w.name = 'Guerre des Six Jours'
