SELECT w.id, 'nigeria', 1, 'Gouvernement fédéral du Nigeria', 'Federal Government of Nigeria', 'Armée et aviation fédérales nigérianes, pilotes égyptiens puis mercenaires européens ; armes et avions achetés à l’URSS, à la Tchécoslovaquie et à la Pologne ; appui politique et armes du Royaume-Uni', 'Nigerian federal army and air force, Egyptian pilots and later European mercenaries; arms and aircraft bought from the USSR, Czechoslovakia and Poland; political backing and arms from Britain' FROM wars w WHERE w.name = 'Guerre du Biafra'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
