INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'rhodesie', 1, 'Rhodésie', 'Rhodesia', 'Forces de sécurité rhodésiennes, avec le soutien matériel et militaire de l’Afrique du Sud (et du Portugal jusqu’en 1974)', 'Rhodesian Security Forces, with material and military support from South Africa (and Portugal until 1974)' FROM wars w WHERE w.name = 'Guerre du Bush rhodésien'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'nationalistes', 2, 'Mouvements nationalistes', 'Nationalist movements', 'ZANU-ZANLA (soutenue par la Chine et le FRELIMO mozambicain) et ZAPU-ZIPRA (soutenue par l’Union soviétique et basée en Zambie), sans aviation', 'ZANU-ZANLA (backed by China and Mozambique''s FRELIMO) and ZAPU-ZIPRA (backed by the Soviet Union and based in Zambia), with no air arm' FROM wars w WHERE w.name = 'Guerre du Bush rhodésien'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
