SELECT w.id, DATE '1995-02-09', 'day', 'Les Su-22 entrent en scène', 'The Su-22s join in', 'L’aviation péruvienne mène au moins seize sorties d’attaque au sol, dont des Su-22 ; les Canberra bombardent de nouveau de nuit.', 'The Peruvian Air Force flies at least sixteen ground-attack sorties, Su-22s among them; Canberras bomb again at night.', (SELECT id FROM airplanes WHERE name = 'Su-17'), 'https://en.wikipedia.org/wiki/Cenepa_War' FROM wars w WHERE w.name = 'Guerre du Cenepa'
