INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1995-02-10', 'day', 'Deux Su-22 revendiqués par les Mirage', 'Two Su-22s claimed by Mirages', 'Deux Mirage F1JA équatoriens revendiquent deux Su-22 péruviens au missile Magic. Le Pérou attribue ces pertes à la défense antiaérienne et à un incendie moteur.', 'Two Ecuadorian Mirage F1JAs claim two Peruvian Su-22s with Magic missiles. Peru blames the losses on anti-aircraft fire and an engine fire.', (SELECT id FROM airplanes WHERE name = 'Mirage F1'), 'https://en.wikipedia.org/wiki/Dassault_Mirage_F1' FROM wars w WHERE w.name = 'Guerre du Cenepa'
