INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1995-02-10', 'day', 'Un A-37B abattu par un Kfir', 'An A-37B downed by a Kfir', 'Dans le même engagement, un Kfir C.2 abat un A-37B péruvien d’un missile Shafrir ; l’équipage s’éjecte et est récupéré.', 'In the same engagement, a Kfir C.2 shoots down a Peruvian A-37B with a Shafrir missile; the crew eject and are rescued.', (SELECT id FROM airplanes WHERE name = 'IAI Kfir'), 'https://en.wikipedia.org/wiki/IAI_Kfir' FROM wars w WHERE w.name = 'Guerre du Cenepa'
