INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'coalition', 1, 'Coalition', 'Coalition', 'États-Unis, Royaume-Uni, France, Arabie saoudite, Koweït, Italie, Canada, Qatar, Bahreïn, Émirats arabes unis, Égypte… (42 pays)', 'United States, United Kingdom, France, Saudi Arabia, Kuwait, Italy, Canada, Qatar, Bahrain, United Arab Emirates, Egypt… (42 countries)' FROM wars w WHERE w.name = 'Guerre du Golfe'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'irak', 2, 'Irak', 'Iraq', 'Irak', 'Iraq' FROM wars w WHERE w.name = 'Guerre du Golfe'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre du Golfe' AND s.side_key NOT IN ('coalition', 'irak');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Pour son baptême du feu, l''A-10 est déployé à 132 exemplaires : 8 100 sorties, 90 % des missiles Maverick tirés pendant le conflit, chasse aux Scud et deux hélicoptères irakiens abattus au canon. Quatre sont abattus par des missiles sol-air.', role_en = 'In its combat debut, 132 A-10s were deployed: 8,100 sorties, 90 per cent of the Maverick missiles fired in the conflict, Scud hunting and two Iraqi helicopters shot down with the cannon. Four were downed by surface-to-air missiles.', sources = 'https://en.wikipedia.org/wiki/Fairchild_Republic_A-10_Thunderbolt_II
https://en.wikipedia.org/wiki/Air_engagements_of_the_Gulf_War'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'A-10 Thunderbolt II' AND w.name = 'Guerre du Golfe'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Pour son baptême du feu, l''A-10 est déployé à 132 exemplaires : 8 100 sorties, 90 % des missiles Maverick tirés pendant le conflit, chasse aux Scud et deux hélicoptères irakiens abattus au canon. Quatre sont abattus par des missiles sol-air.', 'In its combat debut, 132 A-10s were deployed: 8,100 sorties, 90 per cent of the Maverick missiles fired in the conflict, Scud hunting and two Iraqi helicopters shot down with the cannon. Four were downed by surface-to-air missiles.', 'https://en.wikipedia.org/wiki/Fairchild_Republic_A-10_Thunderbolt_II
