UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Bête de somme du pont aérien vers le Golfe, qualifié de plus grand de l''histoire : pendant *Desert Shield* et *Desert Storm*, les C-141 effectuent 8 536 missions et transportent environ 144 700 tonnes de fret et 93 126 passagers.', role_en = 'The workhorse of an airlift to the Gulf described as the largest in history: during *Desert Shield* and *Desert Storm*, C-141s flew 8,536 missions carrying some 159,000 short tons of cargo and 93,126 passengers.', sources = 'https://en.wikipedia.org/wiki/Lockheed_C-141_Starlifter'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'C-141 Starlifter' AND w.name = 'Guerre du Golfe'
