UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Pièce maîtresse du pont aérien de 1990-1991, il achemine vers le Golfe le matériel le plus lourd. Pendant *Desert Shield*, un C-5A d''un équipage de réserve s''écrase au décollage de Ramstein après le déploiement intempestif d''un inverseur de poussée : 13 des 17 personnes à bord sont tuées.', role_en = 'A mainstay of the 1990-1991 airlift, it carried the heaviest equipment to the Gulf. During *Desert Shield*, a C-5A flown by a reserve crew crashed on take-off from Ramstein after a thrust reverser deployed: 13 of the 17 people aboard were killed.', sources = 'https://en.wikipedia.org/wiki/Lockheed_C-5_Galaxy'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'C-5 Galaxy' AND w.name = 'Guerre du Golfe'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Pièce maîtresse du pont aérien de 1990-1991, il achemine vers le Golfe le matériel le plus lourd. Pendant *Desert Shield*, un C-5A d''un équipage de réserve s''écrase au décollage de Ramstein après le déploiement intempestif d''un inverseur de poussée : 13 des 17 personnes à bord sont tuées.', 'A mainstay of the 1990-1991 airlift, it carried the heaviest equipment to the Gulf. During *Desert Shield*, a C-5A flown by a reserve crew crashed on take-off from Ramstein after a thrust reverser deployed: 13 of the 17 people aboard were killed.', 'https://en.wikipedia.org/wiki/Lockheed_C-5_Galaxy');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Sous le nom de Midge, le drone de l''armée britannique est engagé au Koweït en 1991 pour confirmer la position des forces irakiennes, en particulier de leur artillerie, avec un certain effet lorsqu''il est combiné aux raids d''artillerie.', role_en = 'As the Midge, the British Army''s drone was used in Kuwait in 1991 to confirm the positions of Iraqi forces, especially their artillery, with some effect when combined with artillery raids.', sources = 'https://en.wikipedia.org/wiki/Canadair_CL-89'
