UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = '39 Prowler, 27 répartis sur six porte-avions et 12 des Marines basés à terre, brouillent la défense antiaérienne irakienne : 1 648 sorties (1 132 pour la Navy, 516 pour les Marines) et plus de 150 missiles antiradar HARM tirés sur radars et nœuds de communication, sans aucune perte.', role_en = 'Thirty-nine Prowlers, 27 spread over six carriers and 12 Marine aircraft ashore, jammed Iraq''s air defences: 1,648 sorties (1,132 Navy, 516 Marine) and more than 150 HARM anti-radar missiles fired at radars and communications nodes, without a single loss.', sources = 'https://en.wikipedia.org/wiki/Northrop_Grumman_EA-6B_Prowler'
