   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), '39 Prowler, 27 répartis sur six porte-avions et 12 des Marines basés à terre, brouillent la défense antiaérienne irakienne : 1 648 sorties (1 132 pour la Navy, 516 pour les Marines) et plus de 150 missiles antiradar HARM tirés sur radars et nœuds de communication, sans aucune perte.', 'Thirty-nine Prowlers, 27 spread over six carriers and 12 Marine aircraft ashore, jammed Iraq''s air defences: 1,648 sorties (1,132 Navy, 516 Marine) and more than 150 HARM anti-radar missiles fired at radars and communications nodes, without a single loss.', 'https://en.wikipedia.org/wiki/Northrop_Grumman_EA-6B_Prowler');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Dix-huit EF-111A brouillent les radars irakiens devant les raids en profondeur, dès les premières frappes sur Bagdad. Le 17 janvier, un équipage se voit attribuer officieusement un Mirage F1 écrasé au sol pendant la poursuite ; un EF-111A est perdu le 13 février avec ses deux hommes.', role_en = 'Eighteen EF-111As jammed Iraqi radars ahead of deep strikes, starting with the first raids on Baghdad. On 17 January one crew was unofficially credited with a Mirage F1 that flew into the ground during the chase; one EF-111A was lost on 13 February with both crew.', sources = 'https://en.wikipedia.org/wiki/General_Dynamics%E2%80%93Grumman_EF-111A_Raven
https://en.wikipedia.org/wiki/Gulf_War_air_campaign
https://en.wikipedia.org/wiki/Air_engagements_of_the_Gulf_War'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'EF-111 Raven' AND w.name = 'Guerre du Golfe'
