UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'irak'), role = 'La première nuit, un MiG-25 abat très probablement le F/A-18 de Scott Speicher, seule perte de la coalition en combat aérien. Deux MiG-25 sont abattus par des F-15C le 19 janvier ; la plupart des autres sont détruits au sol.', role_en = 'On the first night a MiG-25 most likely shot down Scott Speicher''s F/A-18, the coalition''s only loss in air combat. Two MiG-25s were downed by F-15Cs on 19 January; most of the rest were destroyed on the ground.', sources = 'https://en.wikipedia.org/wiki/Mikoyan-Gurevich_MiG-25
