UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Lors des premières attaques, 37 des 38 BQM-74C prévus sont lancés depuis le sol, en vagues minutées, comme leurres pour la deuxième vague de frappes ; ils tournent jusqu''à vingt minutes au-dessus de Bagdad. Un seul groupe de trois est intercepté.', role_en = 'During the opening attacks, 37 of the 38 BQM-74Cs assigned were ground-launched in precisely timed waves as decoys for the second wave of strikes; they circled Baghdad for up to twenty minutes. Only one group of three was intercepted.', sources = 'https://en.wikipedia.org/wiki/Northrop_BQM-74_Chukar'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Northrop BQM-74 Chukar' AND w.name = 'Guerre du Golfe'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Lors des premières attaques, 37 des 38 BQM-74C prévus sont lancés depuis le sol, en vagues minutées, comme leurres pour la deuxième vague de frappes ; ils tournent jusqu''à vingt minutes au-dessus de Bagdad. Un seul groupe de trois est intercepté.', 'During the opening attacks, 37 of the 38 BQM-74Cs assigned were ground-launched in precisely timed waves as decoys for the second wave of strikes; they circled Baghdad for up to twenty minutes. Only one group of three was intercepted.', 'https://en.wikipedia.org/wiki/Northrop_BQM-74_Chukar');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Les OV-1D de l''US Army surveillent le champ de bataille avec leur radar latéral, qui détecte les véhicules en mouvement et permet d''appeler des frappes par mauvais temps. *Desert Storm* est le chant du cygne du type ; la dernière éjection d''un Mohawk en zone de combat a lieu la nuit du 28 février.', role_en = 'US Army OV-1Ds watched the battlefield with their side-looking radar, which picked up moving vehicles and allowed strikes to be called in bad weather. *Desert Storm* was the type''s swan song; the last Mohawk ejection in a combat zone took place on the night of 28 February.', sources = 'https://en.wikipedia.org/wiki/Grumman_OV-1_Mohawk
https://www.historynet.com/silent-warrior-grummans-ov-1-mohawk/'
