UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Les OV-10 des Marines coordonnent l''appui aérien des forces terrestres et repèrent les forces irakiennes pendant l''avance : c''est leur dernier grand engagement. Deux sont abattus, victimes de leur lenteur, du vol à basse altitude et de l''absence de contre-mesures infrarouges.', role_en = 'Marine OV-10s coordinated air support for ground forces and tracked Iraqi units during the advance: their last major combat deployment. Two were shot down, victims of their slow speed, low-altitude flying and lack of infrared countermeasures.', sources = 'https://en.wikipedia.org/wiki/North_American_Rockwell_OV-10_Bronco
https://en.wikipedia.org/wiki/Gulf_War_air_campaign'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'OV-10 Bronco' AND w.name = 'Guerre du Golfe'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Les OV-10 des Marines coordonnent l''appui aérien des forces terrestres et repèrent les forces irakiennes pendant l''avance : c''est leur dernier grand engagement. Deux sont abattus, victimes de leur lenteur, du vol à basse altitude et de l''absence de contre-mesures infrarouges.', 'Marine OV-10s coordinated air support for ground forces and tracked Iraqi units during the advance: their last major combat deployment. Two were shot down, victims of their slow speed, low-altitude flying and lack of infrared countermeasures.', 'https://en.wikipedia.org/wiki/North_American_Rockwell_OV-10_Bronco
