UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Parmi les premières forces américaines sur place, 48 heures après l''invasion, les P-3C surveillent les côtes irakiennes et koweïtiennes ; ils repèrent la flottille attaquée près de l''île de Boubiyan et ciblent 55 des 108 navires irakiens détruits pendant le conflit.', role_en = 'Among the first US forces on the scene, 48 hours after the invasion, P-3Cs watched the Iraqi and Kuwaiti coasts; they spotted the flotilla attacked near Bubiyan Island and targeted 55 of the 108 Iraqi vessels destroyed in the conflict.', sources = 'https://en.wikipedia.org/wiki/Lockheed_P-3_Orion'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'P-3 Orion' AND w.name = 'Guerre du Golfe'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), 'Parmi les premières forces américaines sur place, 48 heures après l''invasion, les P-3C surveillent les côtes irakiennes et koweïtiennes ; ils repèrent la flottille attaquée près de l''île de Boubiyan et ciblent 55 des 108 navires irakiens détruits pendant le conflit.', 'Among the first US forces on the scene, 48 hours after the invasion, P-3Cs watched the Iraqi and Kuwaiti coasts; they spotted the flotilla attacked near Bubiyan Island and targeted 55 of the 108 Iraqi vessels destroyed in the conflict.', 'https://en.wikipedia.org/wiki/Lockheed_P-3_Orion');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'coalition'), role = 'Les Tornado GR1 de la RAF ouvrent la guerre par des attaques au ras du sol contre les aérodromes irakiens, à la JP233, puis passent à la moyenne altitude avec des bombes guidées désignées par des Buccaneer. Tornado F3 de défense aérienne et Tornado saoudiens IDS et ADV sont aussi engagés.', role_en = 'RAF Tornado GR1s opened the war with very low-level JP233 attacks on Iraqi airfields, then switched to medium altitude with guided bombs designated by Buccaneers. Tornado F3 air defence fighters and Saudi IDS and ADV Tornados also took part.', sources = 'https://en.wikipedia.org/wiki/Panavia_Tornado
