INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1990-08-02', 'day', 'Invasion du Koweït', 'Invasion of Kuwait', 'L''armée irakienne envahit le Koweït en quelques heures. Le Conseil de sécurité exige son retrait le jour même par la résolution 660.', 'The Iraqi army overruns Kuwait in a matter of hours. The UN Security Council demands its withdrawal the same day in Resolution 660.', NULL::int, 'https://en.wikipedia.org/wiki/Gulf_War' FROM wars w WHERE w.name = 'Guerre du Golfe'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1990-08-08', 'day', 'Premiers F-15 en Arabie saoudite', 'First F-15s in Saudi Arabia', 'Les F-15 du 1st Tactical Fighter Wing, partis de Langley, se posent en Arabie saoudite au terme d''un vol sans escale : *Desert Shield* commence à prendre forme dans le ciel.', 'F-15s of the 1st Tactical Fighter Wing, flying nonstop from Langley, touch down in Saudi Arabia: *Desert Shield* takes shape in the air.', (SELECT id FROM airplanes WHERE name = 'F-15 Eagle'), 'https://www.airandspaceforces.com/this-day-in-airpower/august-08-1990/' FROM wars w WHERE w.name = 'Guerre du Golfe'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
