INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1991-01-16', 'day', 'Décollage de l''opération Senior Surprise', 'Operation Senior Surprise takes off', 'Sept B-52G décollent de Barksdale, en Louisiane, pour tirer 35 missiles de croisière CALCM sur l''Irak et revenir sans escale : la plus longue mission de combat jamais menée à l''époque.', 'Seven B-52Gs take off from Barksdale, Louisiana, to fire 35 CALCM cruise missiles at Iraq and fly home nonstop, the longest combat mission ever flown at the time.', (SELECT id FROM airplanes WHERE name = 'B-52 Stratofortress'), 'https://www.barksdale.af.mil/News/Display/Article/1054069/celebrating-the-26th-anniversary-of-secret-squirrel/' FROM wars w WHERE w.name = 'Guerre du Golfe'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
