INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1991-01-17', 'day', 'Première nuit de Desert Storm', 'First night of Desert Storm', 'À 2 h 38, des hélicoptères détruisent des radars frontaliers ; à 3 heures, dix F-117 bombardent Bagdad sous la protection des EF-111. La coalition effectue 2 775 sorties dans la journée.', 'At 2:38 a.m. helicopters destroy border radars; at 3:00 a.m. ten F-117s bomb Baghdad under EF-111 cover. The coalition flies 2,775 sorties that day.', (SELECT id FROM airplanes WHERE name = 'F-117 Nighthawk'), 'https://en.wikipedia.org/wiki/Gulf_War_air_campaign' FROM wars w WHERE w.name = 'Guerre du Golfe'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
