INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1991-01-17', 'day', 'Deux MiG-21 abattus, Speicher perdu', 'Two MiG-21s downed, Speicher lost', 'Deux F/A-18 du porte-avions Saratoga, chargés de bombarder l''aérodrome H-3, abattent deux MiG-21 puis reprennent leur attaque. La même nuit, le F/A-18 de Scott Speicher est abattu, probablement par un MiG-25 : seule perte de la coalition en combat aérien.', 'Two F/A-18s from the carrier Saratoga, sent to bomb the H-3 airfield, shoot down two MiG-21s and then resume their attack. The same night Scott Speicher''s F/A-18 is downed, probably by a MiG-25: the coalition''s only air-to-air loss.', (SELECT id FROM airplanes WHERE name = 'F/A-18 Hornet'), 'https://en.wikipedia.org/wiki/Air_engagements_of_the_Gulf_War' FROM wars w WHERE w.name = 'Guerre du Golfe'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
