 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1991-01-18', 'day', 'Un Tornado italien abattu', 'An Italian Tornado shot down', 'Dès la première mission italienne, dans la nuit du 17 au 18 janvier, le Tornado de Gianmarco Bellini et Maurizio Cocciolone est abattu par la DCA ; les deux hommes restent 47 jours prisonniers.', 'On Italy''s very first mission, on the night of 17-18 January, the Tornado of Gianmarco Bellini and Maurizio Cocciolone is shot down by anti-aircraft fire; both men spend 47 days as prisoners.', (SELECT id FROM airplanes WHERE name = 'Panavia Tornado Italien'), 'https://it.wikipedia.org/wiki/Operazione_Locusta' FROM wars w WHERE w.name = 'Guerre du Golfe'
