INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1991-01-24', 'day', 'Doublé d''un pilote saoudien', 'A Saudi pilot''s double', 'Au-dessus des eaux saoudiennes du Golfe, le capitaine Ayedh al-Shamrani, sur F-15C, abat à la Sidewinder deux Mirage F1 irakiens qui filaient vers le sud, armés selon Riyad de missiles Exocet.', 'Over Saudi waters in the Gulf, Captain Ayedh al-Shamrani, flying an F-15C, downs with Sidewinders two Iraqi Mirage F1s heading south, armed with Exocet missiles according to Riyadh.', (SELECT id FROM airplanes WHERE name = 'Mirage F1'), 'https://www.upi.com/Archives/1991/01/25/Saudi-plane-shoots-down-two-Iraqi-jets/3365664779600/' FROM wars w WHERE w.name = 'Guerre du Golfe'
