INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1991-01-25', 'day', 'Début de la fuite vers l''Iran', 'The flight to Iran begins', 'Sept Su-25 irakiens quittent l''Irak et se posent en Iran. Ils ouvrent un exode qui emmènera, selon les décomptes, entre 115 et 140 appareils irakiens, jamais rendus.', 'Seven Iraqi Su-25s leave Iraq and land in Iran. They open an exodus that will take between 115 and 140 Iraqi aircraft there, depending on the count, never to return.', (SELECT id FROM airplanes WHERE name = 'Su-25'), 'https://en.wikipedia.org/wiki/Sukhoi_Su-25' FROM wars w WHERE w.name = 'Guerre du Golfe'
