INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1991-02-13', 'day', 'Bombardement de l''abri d''Amiriyah', 'Amiriyah shelter bombing', 'À 4 h 30, deux F-117 larguent chacun une bombe guidée GBU-27 sur un abri de Bagdad inscrit deux jours plus tôt parmi les cibles militaires : au moins 408 civils sont tués.', 'At 4:30 a.m. two F-117s each drop a GBU-27 guided bomb on a Baghdad shelter added to the military target list two days earlier: at least 408 civilians are killed.', (SELECT id FROM airplanes WHERE name = 'F-117 Nighthawk'), 'https://en.wikipedia.org/wiki/Amiriyah_shelter_bombing' FROM wars w WHERE w.name = 'Guerre du Golfe'
