INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'azerbaidjan', 1, 'Azerbaïdjan', 'Azerbaijan', 'Forces armées azerbaïdjanaises, avec le soutien militaire de la Turquie', 'Azerbaijani Armed Forces, with Turkish military support' FROM wars w WHERE w.name = 'Guerre du Haut-Karabagh (2020)'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'armenie', 2, 'Arménie et Artsakh', 'Armenia and Artsakh', 'Armée de défense de la république autoproclamée d’Artsakh (Haut-Karabagh) et forces armées arméniennes', 'Defence Army of the self-proclaimed Republic of Artsakh (Nagorno-Karabakh) and Armenian Armed Forces' FROM wars w WHERE w.name = 'Guerre du Haut-Karabagh (2020)'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
