INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1973-10-06', 'day', 'La frappe d''ouverture égyptienne', 'Egypt''s opening air strike', 'À 14 heures, plus de 200 avions égyptiens frappent bases aériennes, batteries Hawk, centres de commandement et radars israéliens du Sinaï, tandis que des Tu-16 tirent des missiles Kelt.', 'At 2 pm, more than 200 Egyptian aircraft strike Israeli air bases, Hawk batteries, command centres and radars in the Sinai, while Tu-16s launch Kelt missiles.', (SELECT id FROM airplanes WHERE name = 'Tu-16'), 'https://en.wikipedia.org/wiki/Yom_Kippur_War' FROM wars w WHERE w.name = 'Guerre du Kippour'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1973-10-06', 'day', 'La bataille aérienne d''Ofira', 'The Ofira air battle', 'Deux F-4E israéliens interceptent vingt MiG-17 et huit MiG-21 qui attaquent la base d''Ofira et revendiquent sept victoires sans perte ; l''Égypte conteste ce récit.', 'Two Israeli F-4Es intercept twenty MiG-17s and eight MiG-21s attacking Ofira air base and claim seven kills without loss; Egypt disputes this account.', (SELECT id FROM airplanes WHERE name = 'F-4E Kurnass'), 'https://en.wikipedia.org/wiki/Ofira_Air_Battle' FROM wars w WHERE w.name = 'Guerre du Kippour'
