       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1973-10-07', 'day', 'L''opération *Tagar* interrompue', 'Operation *Tagar* called off', 'L''armée de l''air israélienne attaque les défenses et les bases égyptiennes, puis arrête l''opération après la première vague pour secourir le Golan ; deux Skyhawk sont perdus.', 'The Israeli Air Force strikes Egyptian defences and air bases, then halts the operation after the first wave to rescue the Golan front; two Skyhawks are lost.', (SELECT id FROM airplanes WHERE name = 'A-4 Skyhawk'), 'https://en.wikipedia.org/wiki/Operation_Tagar' FROM wars w WHERE w.name = 'Guerre du Kippour'
