SELECT w.id, DATE '1973-10-12', 'day', 'Nixon ordonne le pont aérien', 'Nixon orders the airlift', 'Le président américain ordonne d''envoyer « tout ce qui peut voler » ; quelques heures plus tard, C-141 et C-5 font route vers Israël.', 'The US president orders the military to send everything that can fly; within hours, C-141s and C-5s are on their way to Israel.', NULL::int, 'https://www.jewishvirtuallibrary.org/operation-nickel-grass' FROM wars w WHERE w.name = 'Guerre du Kippour'
