INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'israel', 1, 'Israël', 'Israel', 'Israël (Tsahal et son armée de l''air)', 'Israel (the IDF and the Israeli Air Force)' FROM wars w WHERE w.name = 'Guerre du Liban de 2006'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'hezbollah', 2, 'Hezbollah', 'Hezbollah', 'Hezbollah libanais, armé par l''Iran et la Syrie', 'Lebanon''s Hezbollah, armed by Iran and Syria' FROM wars w WHERE w.name = 'Guerre du Liban de 2006'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre du Liban de 2006' AND s.side_key NOT IN ('israel', 'hezbollah');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'israel'), role = 'Le Hermes 450 (Zik) fait partie, avec le Searcher II et le Heron, des drones qui assurent l''essentiel de la surveillance du Sud-Liban. Trois sont perdus pendant la guerre, deux sur panne et un sur erreur d''opérateur, aucun sous le feu ennemi.', role_en = 'The Hermes 450 (Zik) was one of the drones, alongside the Searcher II and the Heron, that did most of the surveillance work over southern Lebanon. Three were lost during the war, two to technical faults and one to operator error, none to enemy fire.', sources = 'https://www.military.com/defensetech/2006/10/06/how-israels-drones-fought-the-war-part-ii
https://en.wikipedia.org/wiki/Elbit_Hermes_450
https://en.wikipedia.org/wiki/2006_Lebanon_War'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Elbit Hermes 450' AND w.name = 'Guerre du Liban de 2006'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'israel'), 'Le Hermes 450 (Zik) fait partie, avec le Searcher II et le Heron, des drones qui assurent l''essentiel de la surveillance du Sud-Liban. Trois sont perdus pendant la guerre, deux sur panne et un sur erreur d''opérateur, aucun sous le feu ennemi.', 'The Hermes 450 (Zik) was one of the drones, alongside the Searcher II and the Heron, that did most of the surveillance work over southern Lebanon. Three were lost during the war, two to technical faults and one to operator error, none to enemy fire.', 'https://www.military.com/defensetech/2006/10/06/how-israels-drones-fought-the-war-part-ii
https://en.wikipedia.org/wiki/Elbit_Hermes_450
https://en.wikipedia.org/wiki/2006_Lebanon_War');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'israel'), role = 'Livré depuis 2004, le Sufa frappe le Liban dès les premiers jours : un navigateur raconte une mission menée juste après l''enlèvement, avec des bombes guidées GBU-31 et GBU-38. Un F-16I est perdu au décollage d''une base du sud sur une panne, son équipage s''éjectant indemne.', role_en = 'In service since 2004, the Sufa struck Lebanon from the first days: a navigator recalls a mission flown just after the abduction with GBU-31 and GBU-38 guided bombs. One F-16I was lost on take-off from a southern base after a technical fault; both crew ejected unhurt.', sources = 'https://www.twz.com/air/flying-and-fighting-in-the-israeli-air-forces-f-16i-sufa
https://www.ynet.co.il/articles/0,7340,L-3982867,00.html
https://en.wikipedia.org/wiki/2006_Lebanon_War
https://en.wikipedia.org/wiki/General_Dynamics_F-16_Fighting_Falcon_variants'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'F-16I Sufa' AND w.name = 'Guerre du Liban de 2006'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'israel'), 'Livré depuis 2004, le Sufa frappe le Liban dès les premiers jours : un navigateur raconte une mission menée juste après l''enlèvement, avec des bombes guidées GBU-31 et GBU-38. Un F-16I est perdu au décollage d''une base du sud sur une panne, son équipage s''éjectant indemne.', 'In service since 2004, the Sufa struck Lebanon from the first days: a navigator recalls a mission flown just after the abduction with GBU-31 and GBU-38 guided bombs. One F-16I was lost on take-off from a southern base after a technical fault; both crew ejected unhurt.', 'https://www.twz.com/air/flying-and-fighting-in-the-israeli-air-forces-f-16i-sufa
https://www.ynet.co.il/articles/0,7340,L-3982867,00.html
https://en.wikipedia.org/wiki/2006_Lebanon_War
https://en.wikipedia.org/wiki/General_Dynamics_F-16_Fighting_Falcon_variants');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'israel'), role = 'Tout juste acquis par l''aviation israélienne, le Heron (Shoval) vole au-dessus du Liban, mis en œuvre par des équipes mixtes de l''armée de l''air et d''IAI pour des missions de renseignement variées ; *Flight International* évoque des Heron armés de missiles Spike.', role_en = 'Newly acquired by the Israeli Air Force, the Heron (Shoval) flew over Lebanon, operated by joint air force and IAI teams on a wide range of intelligence missions; *Flight International* reported Herons armed with Spike missiles.', sources = 'https://en.globes.co.il/en/article-1000190348
https://www.military.com/defensetech/2006/10/06/how-israels-drones-fought-the-war-part-ii
https://www.flightglobal.com/israel-fields-armed-uavs-in-lebanon/68914.article
https://en.wikipedia.org/wiki/IAI_Heron'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'IAI Heron' AND w.name = 'Guerre du Liban de 2006'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'israel'), 'Tout juste acquis par l''aviation israélienne, le Heron (Shoval) vole au-dessus du Liban, mis en œuvre par des équipes mixtes de l''armée de l''air et d''IAI pour des missions de renseignement variées ; *Flight International* évoque des Heron armés de missiles Spike.', 'Newly acquired by the Israeli Air Force, the Heron (Shoval) flew over Lebanon, operated by joint air force and IAI teams on a wide range of intelligence missions; *Flight International* reported Herons armed with Spike missiles.', 'https://en.globes.co.il/en/article-1000190348
https://www.military.com/defensetech/2006/10/06/how-israels-drones-fought-the-war-part-ii
https://www.flightglobal.com/israel-fields-armed-uavs-in-lebanon/68914.article
https://en.wikipedia.org/wiki/IAI_Heron');
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2006-07-12', 'day', 'Le raid du Hezbollah et les premières frappes', 'Hezbollah''s raid and the first strikes', 'Un commando du Hezbollah tue trois soldats et en enlève deux près de Zar''it. Le jour même, l''aviation israélienne frappe routes et ponts du Sud-Liban, dont cinq ponts sur le Litani et le Zahrani.', 'A Hezbollah team killed three soldiers and captured two near Zar''it. The same day, Israeli aircraft hit roads and bridges in southern Lebanon, including five bridges over the Litani and Zahrani.', NULL::int, 'https://en.wikipedia.org/wiki/2006_Lebanon_War' FROM wars w WHERE w.name = 'Guerre du Liban de 2006'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2006-07-13', 'day', 'Opération *Densité* et aéroport de Beyrouth', 'Operation *Density* and Beirut airport', 'Peu après minuit, l''aviation détruit en 34 minutes 59 lanceurs de roquettes Fajr selon Tsahal ; les pistes et les dépôts de carburant de l''aéroport de Beyrouth sont bombardés.', 'Shortly after midnight, the air force destroyed 59 Fajr rocket launchers in 34 minutes, according to the IDF; the runways and fuel depots of Beirut airport were bombed.', NULL::int, 'https://en.wikipedia.org/wiki/2006_Lebanon_War' FROM wars w WHERE w.name = 'Guerre du Liban de 2006'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2006-07-14', 'day', 'Frappes sur la banlieue sud de Beyrouth', 'Strikes on Beirut''s southern suburbs', 'Israël frappe Dahiyé, fief du Hezbollah où se trouvent son quartier général et les logements de ses dirigeants ; le même jour, un missile antinavire du Hezbollah touche la corvette *Hanit*.', 'Israel struck Dahiyeh, the Hezbollah stronghold housing its headquarters and its leaders'' homes; the same day a Hezbollah anti-ship missile hit the corvette *Hanit*.', NULL::int, 'https://fr.wikipedia.org/wiki/Conflit_isra%C3%A9lo-libanais_de_2006' FROM wars w WHERE w.name = 'Guerre du Liban de 2006'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
