INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2006-07-19', 'day', '23 tonnes de bombes sur un bunker', '23 tonnes of bombs on a bunker', 'Un bunker supposé de la direction du Hezbollah, dans le sud de Beyrouth, reçoit 23 tonnes de bombes ; aucun dirigeant n''est atteint. L''article français de Wikipédia date cette frappe du 20 juillet.', 'A suspected Hezbollah leadership bunker in southern Beirut was hit with 23 tonnes of bombs; no leader was killed. The French Wikipedia article dates the strike to 20 July.', NULL::int, 'https://en.wikipedia.org/wiki/2006_Lebanon_War' FROM wars w WHERE w.name = 'Guerre du Liban de 2006'
