INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2006-07-30', 'day', 'La frappe de Cana', 'The Qana strike', 'Deux bombes touchent un immeuble de Cana que Tsahal présente comme une cache du Hezbollah : 28 morts, dont 16 enfants, selon Human Rights Watch et la Croix-Rouge libanaise.', 'Two bombs hit a building in Qana that the IDF described as a Hezbollah hideout: 28 dead, 16 of them children, according to Human Rights Watch and the Lebanese Red Cross.', NULL::int, 'https://en.wikipedia.org/wiki/2006_Qana_airstrike' FROM wars w WHERE w.name = 'Guerre du Liban de 2006'
