INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2006-07-31', 'day', 'Pause de 48 heures', 'A 48-hour pause', 'Sous la pression internationale, Israël suspend jusqu''à 48 heures ses frappes sur le Sud-Liban ; le Hezbollah cesse ses tirs pendant cette pause.', 'Under international pressure, Israel suspended air strikes over southern Lebanon for up to 48 hours; Hezbollah halted its rocket fire during the pause.', NULL::int, 'https://en.wikipedia.org/wiki/2006_Qana_airstrike' FROM wars w WHERE w.name = 'Guerre du Liban de 2006'
