SELECT w.id, DATE '2006-08-07', 'day', 'Un drone du Hezbollah abattu', 'A Hezbollah drone shot down', 'Un F-16 israélien abat au large du nord d''Israël le premier des trois drones Ababil, de conception iranienne, lancés par le Hezbollah pendant la guerre.', 'An Israeli F-16 shot down off northern Israel the first of the three Iranian-designed Ababil drones launched by Hezbollah during the war.', NULL::int, 'https://en.wikipedia.org/wiki/HESA_Ababil' FROM wars w WHERE w.name = 'Guerre du Liban de 2006'
