INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2006-08-11', 'day', 'Résolution 1701', 'Resolution 1701', 'Le Conseil de sécurité de l''ONU adopte à l''unanimité la résolution 1701, qui prévoit le désarmement du Hezbollah, le retrait israélien et le déploiement de l''armée libanaise et d''une FINUL renforcée.', 'The UN Security Council unanimously adopted Resolution 1701, calling for Hezbollah''s disarmament, Israel''s withdrawal and the deployment of the Lebanese army and an enlarged UNIFIL.', NULL::int, 'https://en.wikipedia.org/wiki/2006_Lebanon_War' FROM wars w WHERE w.name = 'Guerre du Liban de 2006'
