INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2006-08-12', 'day', 'Un CH-53 abattu', 'A CH-53 shot down', 'Un hélicoptère de transport CH-53 est abattu près de Yater, au Sud-Liban, avec ses cinq membres d''équipage. Le Hezbollah dit avoir employé un nouveau missile.', 'A CH-53 transport helicopter was shot down near Yater in southern Lebanon with its five crew. Hezbollah said it had used a new missile.', NULL::int, 'https://www.aljazeera.com/news/2006/8/13/hezbollah-downs-israeli-helicopter' FROM wars w WHERE w.name = 'Guerre du Liban de 2006'
