INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'israel', 1, 'Israël', 'Israel', 'Israël, avec ses alliés libanais (Forces libanaises chrétiennes, Armée du Liban-Sud)', 'Israel, with its Lebanese allies (the Christian Lebanese Forces and the South Lebanon Army)' FROM wars w WHERE w.name = 'Guerre du Liban'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'syrie-olp', 2, 'Syrie et OLP', 'Syria and the PLO', 'Syrie, Organisation de libération de la Palestine et factions palestiniennes et libanaises alliées', 'Syria, the Palestine Liberation Organization and allied Palestinian and Lebanese factions' FROM wars w WHERE w.name = 'Guerre du Liban'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre du Liban' AND s.side_key NOT IN ('israel', 'syrie-olp');
