INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1982-06-04', 'day', 'Premières frappes contre l''OLP', 'First strikes on the PLO', 'Au lendemain de l''attentat contre l''ambassadeur Argov, les avions israéliens bombardent les dépôts de munitions et les camps d''entraînement de l''OLP au Liban.', 'The day after the attack on Ambassador Argov, Israeli jets bomb PLO ammunition depots and training camps in Lebanon.', NULL::int, 'https://jewishvirtuallibrary.org/israel-air-force-in-operation-peace-for-the-galilee' FROM wars w WHERE w.name = 'Guerre du Liban'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1982-06-06', 'day', '*Paix en Galilée* et la perte d''un Skyhawk', '*Peace for Galilee* and a Skyhawk lost', 'Tsahal envahit le Sud-Liban avec l''appui de l''aviation. Le jour même, l''A-4 d''Aharon Achiaz est abattu par un missile portable SA-7.', 'The IDF invades southern Lebanon with air support. That same day, Aharon Achiaz''s A-4 is shot down by a shoulder-launched SA-7.', (SELECT id FROM airplanes WHERE name = 'A-4 Skyhawk'), 'https://en.wikipedia.org/wiki/Douglas_A-4_Skyhawk' FROM wars w WHERE w.name = 'Guerre du Liban'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1982-06-09', 'day', 'Les drones ouvrent la voie', 'Drones lead the way', 'Les drones Scout et Mastiff, qui ont repéré les sites de missiles de la Bekaa, survolent la vallée pour pousser les Syriens à allumer leurs radars.', 'Scout and Mastiff drones, which had located the Bekaa missile sites, fly over the valley to bait the Syrians into switching on their radars.', (SELECT id FROM airplanes WHERE name = 'IAI Scout'), 'https://en.wikipedia.org/wiki/IAI_Scout' FROM wars w WHERE w.name = 'Guerre du Liban'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
