       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1982-06-09', 'day', '*Mole Cricket 19*', '*Mole Cricket 19*', 'À partir de 14 heures, les Phantom armés de missiles antiradar détruisent les batteries SAM syriennes de la Bekaa ; leur nombre varie de 17 à 29 selon les sources.', 'From 2 pm, Phantoms armed with anti-radiation missiles destroy the Syrian SAM batteries in the Bekaa; sources put the number at between 17 and 29.', (SELECT id FROM airplanes WHERE name = 'F-4E Kurnass'), 'https://en.wikipedia.org/wiki/Operation_Mole_Cricket_19' FROM wars w WHERE w.name = 'Guerre du Liban'
