INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1982-06-09', 'day', 'La grande bataille aérienne de la Bekaa', 'The great Bekaa air battle', 'Une centaine de chasseurs syriens tentent d''arrêter l''attaque ; les F-15 et F-16 israéliens abattent environ 26 MiG dans la première demi-heure.', 'Some hundred Syrian fighters try to stop the attack; Israeli F-15s and F-16s shoot down about 26 MiGs in the first half-hour.', (SELECT id FROM airplanes WHERE name = 'F-16 Fighting Falcon'), 'https://www.airandspaceforces.com/article/0602bekaa/' FROM wars w WHERE w.name = 'Guerre du Liban'
