SELECT w.id, DATE '1982-07-01', 'month', 'Un Phantom abattu dans la Bekaa', 'A Phantom downed in the Bekaa', 'Les avions israéliens détruisent trois batteries SA-8 installées près de la frontière syrienne ; un Phantom est abattu par un missile et son équipage s''éjecte.', 'Israeli aircraft destroy three SA-8 batteries set up near the Syrian border; a Phantom is shot down by a missile and its crew eject.', (SELECT id FROM airplanes WHERE name = 'F-4E Kurnass'), 'https://www.jta.org/archive/heavy-fighting-around-beirut-3-israeli-soldiers-wounded-israeli-aircraft-destroy-syrian-anti-aircr' FROM wars w WHERE w.name = 'Guerre du Liban'
