SELECT w.id, DATE '1982-08-30', 'day', 'Arafat quitte Beyrouth', 'Arafat leaves Beirut', 'Yasser Arafat quitte Beyrouth ; l''OLP installe son nouveau siège à Tunis.', 'Yasser Arafat leaves Beirut; the PLO sets up its new headquarters in Tunis.', NULL::int, 'https://fr.wikipedia.org/wiki/Opération_Paix_en_Galilée' FROM wars w WHERE w.name = 'Guerre du Liban'
