INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1982-09-14', 'day', 'Assassinat de Bachir Gemayel', 'Bashir Gemayel assassinated', 'Le président élu Bachir Gemayel est assassiné ; Tsahal occupe Beyrouth-Ouest le lendemain, avant le massacre de Sabra et Chatila (16-18 septembre).', 'President-elect Bashir Gemayel is assassinated; the IDF occupies West Beirut the next day, ahead of the Sabra and Shatila massacre (16-18 September).', NULL::int, 'https://en.wikipedia.org/wiki/1982_Lebanon_War' FROM wars w WHERE w.name = 'Guerre du Liban'
