INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1982-09-29', 'day', 'Fin de *Paix en Galilée*', 'End of *Peace for Galilee*', 'Israël se retire de Beyrouth-Ouest, ce qui met officiellement fin à l''opération ; ses troupes restent au Liban jusqu''en 1985.', 'Israel withdraws from West Beirut, officially ending the operation; its troops remain in Lebanon until 1985.', NULL::int, 'https://en.wikipedia.org/wiki/1982_Lebanon_War' FROM wars w WHERE w.name = 'Guerre du Liban'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
