INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'maroc', 1, 'Maroc et Mauritanie', 'Morocco and Mauritania', 'Maroc (Forces armées royales) ; Mauritanie jusqu''à la paix du 5 août 1979 ; appui aérien français en Mauritanie (opération Lamantin, 1977-1978) ; aide de l''Arabie saoudite, de la France et des États-Unis', 'Morocco (Royal Armed Forces); Mauritania until the peace of 5 August 1979; French air support in Mauritania (Operation Lamantin, 1977-1978); aid from Saudi Arabia, France and the United States' FROM wars w WHERE w.name = 'Guerre du Sahara occidental'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'polisario', 2, 'Front Polisario', 'Polisario Front', 'Front Polisario et République arabe sahraouie démocratique ; soutien de l''Algérie (bases de Tindouf, armes) et de la Libye', 'Polisario Front and the Sahrawi Arab Democratic Republic; support from Algeria (Tindouf bases, arms) and Libya' FROM wars w WHERE w.name = 'Guerre du Sahara occidental'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
