INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'france-allies', 1, 'France, alliés et États du G5 Sahel', 'France, allies and the G5 Sahel states', 'France ; Mali, Niger, Burkina Faso, Tchad et Mauritanie jusqu’aux coups d’État ; Royaume-Uni, Allemagne, États-Unis, Canada, Belgique, Danemark, Pays-Bas, Espagne, Émirats arabes unis et autres soutiens ; casques bleus de la MINUSMA (2013-2023)', 'France; Mali, Niger, Burkina Faso, Chad and Mauritania until the coups; United Kingdom, Germany, United States, Canada, Belgium, Denmark, Netherlands, Spain, United Arab Emirates and other supporters; MINUSMA peacekeepers (2013-2023)' FROM wars w WHERE w.name = 'Guerre du Sahel'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'juntes-russie', 2, 'Juntes sahéliennes et Russie', 'Sahel juntas and Russia', 'Juntes du Mali (depuis 2021), du Burkina Faso et du Niger (depuis 2023), réunies dans l’Alliance des États du Sahel ; groupe Wagner puis Africa Corps russe', 'Juntas of Mali (since 2021), Burkina Faso and Niger (since 2023), grouped in the Alliance of Sahel States; Wagner Group, then Russia’s Africa Corps' FROM wars w WHERE w.name = 'Guerre du Sahel'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre du Sahel' AND s.side_key NOT IN ('france-allies', 'juntes-russie');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france-allies'), role = 'Sous *Barkhane*, les A330 MRTT Phénix français assurent avec les A400M une partie du transport stratégique entre la métropole et le Sahel, sans suffire à éviter l’affrètement d’avions privés, selon le Sénat.', role_en = 'Under *Barkhane*, France’s A330 MRTT Phénix tankers handled, alongside the A400M, part of the strategic airlift between France and the Sahel, though chartered civilian aircraft were still needed, according to the French Senate.', sources = 'https://www.senat.fr/rap/r22-708/r22-7081.pdf'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Airbus A330 MRTT' AND w.name = 'Guerre du Sahel'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france-allies'), 'Sous *Barkhane*, les A330 MRTT Phénix français assurent avec les A400M une partie du transport stratégique entre la métropole et le Sahel, sans suffire à éviter l’affrètement d’avions privés, selon le Sénat.', 'Under *Barkhane*, France’s A330 MRTT Phénix tankers handled, alongside the A400M, part of the strategic airlift between France and the Sahel, though chartered civilian aircraft were still needed, according to the French Senate.', 'https://www.senat.fr/rap/r22-708/r22-7081.pdf');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france-allies'), role = 'L’A400M fait sa première mission opérationnelle le 29 décembre 2013 : 22 tonnes de fret d’Orléans à Bamako pour *Serval*. Sous *Barkhane*, il décuple la capacité de transport et largue par exemple près de 40 tonnes de vivres, d’eau, de carburant et de munitions au Niger en mars 2020.', role_en = 'The A400M flew its first operational mission on 29 December 2013: 22 tonnes of cargo from Orléans to Bamako for *Serval*. Under *Barkhane* it greatly increased airlift capacity, for instance airdropping nearly 40 tonnes of food, water, fuel and ammunition in Niger in March 2020.', sources = 'https://armyrecognition.com/archives/archives-aerospace-defense/aerospace-defense-2014/first-operational-deployement-for-an-a400m-atlas-french-air-force-in-mali
https://thedefensepost.com/2020/03/10/france-a400m-airdrop-supplies-troops-niger-sahel/
https://www.senat.fr/rap/r22-708/r22-7081.pdf'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Airbus A400M Atlas' AND w.name = 'Guerre du Sahel'
