UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'france-allies'), role = 'L’Allemagne déploie à partir de 2016 des Heron 1 à Gao au profit de la MINUSMA, la mission de l’ONU : trois drones sur place, dont deux peuvent voler en même temps, en reconnaissance au-dessus des troupes au sol.', role_en = 'From 2016 Germany deployed Heron 1 drones at Gao for MINUSMA, the UN mission: three drones on site, two of which could fly at the same time, flying reconnaissance over troops on the ground.', sources = 'https://www.bundeswehr.de/de/auftrag/einsaetze/missionen/abgeschlossene-einsaetze-der-bundeswehr/minusma/heron-1-einsatz-minusma-gao-5256618'
