INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2012-01-16', 'day', 'Début de la rébellion touarègue', 'Tuareg rebellion begins', 'Le MNLA attaque l’armée malienne dans le nord pour obtenir l’indépendance de l’Azawad ; fin mars, Kidal, Gao et Tombouctou tombent aux mains des rebelles et des jihadistes.', 'The MNLA attacks the Malian army in the north to win independence for Azawad; by late March Kidal, Gao and Timbuktu have fallen to rebels and jihadists.', NULL::int, 'https://en.wikipedia.org/wiki/Mali_War' FROM wars w WHERE w.name = 'Guerre du Sahel'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2013-01-11', 'day', 'Premières frappes de *Serval*', 'First *Serval* strikes', 'Dans la nuit du 11 au 12 janvier, quatre Mirage 2000D partis de N’Djamena bombardent au GBU-12 les colonnes jihadistes qui menacent le centre du Mali.', 'On the night of 11-12 January, four Mirage 2000Ds from N’Djamena strike with GBU-12s the jihadist columns threatening central Mali.', (SELECT id FROM airplanes WHERE name = 'Mirage 2000'), 'https://fr.wikipedia.org/wiki/Op%C3%A9ration_Serval' FROM wars w WHERE w.name = 'Guerre du Sahel'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
