INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'etats-unis-allies', 1, 'États-Unis et alliés', 'United States and allies', 'États-Unis, Sud-Vietnam, Australie, Nouvelle-Zélande, Corée du Sud, Thaïlande, Philippines ; Royaume du Laos et République khmère dans leurs propres guerres', 'United States, South Vietnam, Australia, New Zealand, South Korea, Thailand, Philippines; Kingdom of Laos and Khmer Republic in their own wars' FROM wars w WHERE w.name = 'Guerre du Vietnam'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'nord-vietnam', 2, 'Nord-Vietnam', 'North Vietnam', 'Nord-Vietnam, Front national de libération (Viet Cong), Pathet Lao ; soutien matériel soviétique et chinois', 'North Vietnam, National Liberation Front (Viet Cong), Pathet Lao; Soviet and Chinese material support' FROM wars w WHERE w.name = 'Guerre du Vietnam'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre du Vietnam' AND s.side_key NOT IN ('etats-unis-allies', 'nord-vietnam');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), role = 'Pilier de la VNAF (plus de 350 reçus), de l''US Navy et des escortes « Sandy » de sauvetage de l''US Air Force. Il frappe le Nord dès le 5 août 1964 et abat deux MiG-17 au canon. Le major Fisher reçoit la Medal of Honor sur A-1E à A Shau. 256 A-1 américains perdus.', role_en = 'Mainstay of the VNAF (over 350 received), the US Navy and the USAF''s "Sandy" rescue escorts. It struck the North on 5 August 1964 and downed two MiG-17s with cannon fire. Major Fisher won the Medal of Honor in an A-1E at A Shau. 256 US A-1s were lost.', sources = 'https://en.wikipedia.org/wiki/Douglas_A-1_Skyraider
https://en.wikipedia.org/wiki/Republic_of_Vietnam_Air_Force'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'A-1 Skyraider' AND w.name = 'Guerre du Vietnam'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), 'Pilier de la VNAF (plus de 350 reçus), de l''US Navy et des escortes « Sandy » de sauvetage de l''US Air Force. Il frappe le Nord dès le 5 août 1964 et abat deux MiG-17 au canon. Le major Fisher reçoit la Medal of Honor sur A-1E à A Shau. 256 A-1 américains perdus.', 'Mainstay of the VNAF (over 350 received), the US Navy and the USAF''s "Sandy" rescue escorts. It struck the North on 5 August 1964 and downed two MiG-17s with cannon fire. Major Fisher won the Medal of Honor in an A-1E at A Shau. 256 US A-1s were lost.', 'https://en.wikipedia.org/wiki/Douglas_A-1_Skyraider
https://en.wikipedia.org/wiki/Republic_of_Vietnam_Air_Force');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), role = 'Arrivés en Thaïlande fin 1960 pour la CIA au Laos, des B-26 volent ensuite en marques sud-vietnamiennes avec Farm Gate, jusqu''à leur interdiction en 1964 après des ruptures d''aile. Rebâtis en B-26K/A-26A, ils chassent les camions de la piste Hô Chi Minh depuis la Thaïlande jusqu''en 1969.', role_en = 'CIA B-26s reached Thailand in late 1960 to support Laos, then flew in South Vietnamese markings with Farm Gate until grounded in 1964 after wing failures. Rebuilt as B-26K/A-26As, they hunted trucks on the Ho Chi Minh Trail from Thailand until 1969.', sources = 'https://en.wikipedia.org/wiki/Douglas_A-26_Invader
https://en.wikipedia.org/wiki/Operation_Farm_Gate'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'A-26 Invader' AND w.name = 'Guerre du Vietnam'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), 'Arrivés en Thaïlande fin 1960 pour la CIA au Laos, des B-26 volent ensuite en marques sud-vietnamiennes avec Farm Gate, jusqu''à leur interdiction en 1964 après des ruptures d''aile. Rebâtis en B-26K/A-26A, ils chassent les camions de la piste Hô Chi Minh depuis la Thaïlande jusqu''en 1969.', 'CIA B-26s reached Thailand in late 1960 to support Laos, then flew in South Vietnamese markings with Farm Gate until grounded in 1964 after wing failures. Rebuilt as B-26K/A-26As, they hunted trucks on the Ho Chi Minh Trail from Thailand until 1969.', 'https://en.wikipedia.org/wiki/Douglas_A-26_Invader
https://en.wikipedia.org/wiki/Operation_Farm_Gate');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), role = 'Bombardier et poseur de mines de 1964 à 1967, il devient ensuite le ravitailleur et brouilleur des groupes aériens (KA-3B, EKA-3B). Les EA-3B du VQ-1 écoutent les radars depuis Da Nang et les RA-3B photographient la nuit les pistes du Laos.', role_en = 'A bomber and minelayer from 1964 to 1967, it then became the air wings'' tanker and jammer (KA-3B, EKA-3B). VQ-1''s EA-3Bs gathered electronic intelligence from Da Nang and RA-3Bs photographed Laotian trails at night.', sources = 'https://en.wikipedia.org/wiki/Douglas_A-3_Skywarrior'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'A-3 Skywarrior' AND w.name = 'Guerre du Vietnam'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), 'Bombardier et poseur de mines de 1964 à 1967, il devient ensuite le ravitailleur et brouilleur des groupes aériens (KA-3B, EKA-3B). Les EA-3B du VQ-1 écoutent les radars depuis Da Nang et les RA-3B photographient la nuit les pistes du Laos.', 'A bomber and minelayer from 1964 to 1967, it then became the air wings'' tanker and jammer (KA-3B, EKA-3B). VQ-1''s EA-3Bs gathered electronic intelligence from Da Nang and RA-3Bs photographed Laotian trails at night.', 'https://en.wikipedia.org/wiki/Douglas_A-3_Skywarrior');
