UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), role = 'En version de reconnaissance RA-5C, huit des dix flottilles de Vigilante photographient le Nord-Vietnam à partir d''août 1964, surtout après les frappes. Mission dangereuse : 18 appareils abattus, dont un par un MiG-21 pendant *Linebacker II*, et neuf perdus par accident.', role_en = 'As the RA-5C reconnaissance version, eight of ten Vigilante squadrons photographed North Vietnam from August 1964, mostly after strikes. A deadly job: 18 shot down, one by a MiG-21 during *Linebacker II*, and nine lost in accidents.', sources = 'https://en.wikipedia.org/wiki/North_American_A-5_Vigilante'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'A-5 Vigilante' AND w.name = 'Guerre du Vietnam'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), 'En version de reconnaissance RA-5C, huit des dix flottilles de Vigilante photographient le Nord-Vietnam à partir d''août 1964, surtout après les frappes. Mission dangereuse : 18 appareils abattus, dont un par un MiG-21 pendant *Linebacker II*, et neuf perdus par accident.', 'As the RA-5C reconnaissance version, eight of ten Vigilante squadrons photographed North Vietnam from August 1964, mostly after strikes. A deadly job: 18 shot down, one by a MiG-21 during *Linebacker II*, and nine lost in accidents.', 'https://en.wikipedia.org/wiki/North_American_A-5_Vigilante');
