UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), role = 'Arrivé au Sud-Vietnam le 21 septembre 1967 pour évaluation, il chasse de nuit les camions de la piste Hô Chi Minh avec le 16th SOS d''Ubon (Thaïlande) ; il en aurait détruit plus de 10 000. Six AC-130 et 52 aviateurs sont perdus.', role_en = 'Arriving in South Vietnam for trials on 21 September 1967, it hunted trucks on the Ho Chi Minh Trail at night with the 16th SOS from Ubon, Thailand, reportedly destroying more than 10,000. Six AC-130s and 52 airmen were lost.', sources = 'https://en.wikipedia.org/wiki/Lockheed_AC-130'
