UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), role = 'Déployé dès 1962 contre une éventuelle menace des Il-28, il protège les bases et escorte les B-52 jusqu''en 1968 ; il harcèle aussi la piste Hô Chi Minh de nuit. 14 sont perdus, dont un seul en combat aérien, abattu par un missile de MiG-21.', role_en = 'Deployed from 1962 against a possible Il-28 threat, it defended bases and escorted B-52s until 1968, and also harassed the Ho Chi Minh Trail at night. 14 were lost, only one in air combat, downed by a MiG-21''s missile.', sources = 'https://en.wikipedia.org/wiki/Convair_F-102_Delta_Dagger'
