UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), role = 'Les F-104C de la 479e escadre protègent de 1965 à 1967 les F-105 et les EC-121 ; ils effectuent 5 206 sorties sans victoire aérienne. 14 sont perdus, dont celui de Philip Smith, abattu par un J-6 chinois le 20 septembre 1965 après s''être égaré au-dessus de la Chine.', role_en = 'The 479th TFW''s F-104Cs protected F-105s and EC-121s from 1965 to 1967, flying 5,206 sorties without an aerial victory. 14 were lost, including Philip Smith''s, shot down by a Chinese J-6 on 20 September 1965 after straying over China.', sources = 'https://en.wikipedia.org/wiki/Lockheed_F-104_Starfighter'
