UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), role = 'Ravitailleur des chasseurs-bombardiers (*Young Tiger*) et des B-52 d''*Arc Light* : 194 687 sorties et 813 878 ravitaillements en vol jusqu''en 1973. Plus de 500 « sauvetages » d''avions endommagés ou à court de carburant sont rapportés.', role_en = 'Tanker for fighter-bombers (*Young Tiger*) and *Arc Light* B-52s: 194,687 sorties and 813,878 aerial refuelings through 1973. More than 500 "saves" of damaged or fuel-starved aircraft are reported.', sources = 'https://www.airandspaceforces.com/article/0698tigers/
