UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), role = 'Avion espion de la CIA, il photographie le Nord-Vietnam depuis Kadena (Okinawa) dans l''opération *Black Shield*, du 31 mai 1967 au 8 mars 1968, à Mach 3 et 24 000 m. Le 30 octobre 1967, au moins six missiles sont tirés contre lui ; l''un explose à quelques centaines de mètres sans l''abattre.', role_en = 'A CIA spyplane, it photographed North Vietnam from Kadena, Okinawa, in Operation *Black Shield* between 31 May 1967 and 8 March 1968, at Mach 3 and 80,000 ft. On 30 October 1967 at least six missiles were fired at it; one detonated close by without bringing it down.', sources = 'https://en.wikipedia.org/wiki/Lockheed_A-12'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Lockheed A-12' AND w.name = 'Guerre du Vietnam'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), 'Avion espion de la CIA, il photographie le Nord-Vietnam depuis Kadena (Okinawa) dans l''opération *Black Shield*, du 31 mai 1967 au 8 mars 1968, à Mach 3 et 24 000 m. Le 30 octobre 1967, au moins six missiles sont tirés contre lui ; l''un explose à quelques centaines de mètres sans l''abattre.', 'A CIA spyplane, it photographed North Vietnam from Kadena, Okinawa, in Operation *Black Shield* between 31 May 1967 and 8 March 1968, at Mach 3 and 80,000 ft. On 30 October 1967 at least six missiles were fired at it; one detonated close by without bringing it down.', 'https://en.wikipedia.org/wiki/Lockheed_A-12');
