UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), role = 'Les C-140A de l''Air Force Communications Service sont déployés en Asie du Sud-Est pour contrôler les aides à la navigation ; ils servent aussi de relais de communications entre le Pentagone et le champ de bataille en tournant au large des côtes.', role_en = 'The Air Force Communications Service''s C-140As deployed to Southeast Asia to flight-check navigation aids, and also loitered off the coast as communications relays between the Pentagon and the battlefield.', sources = 'https://en.wikipedia.org/wiki/Lockheed_JetStar'
