UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), role = 'Les deux EP-3B *Bat Rack*, premiers Orion d''écoute électronique, sont confiés en 1969 à la flottille VQ-1 de l''US Navy et déployés à Da Nang pour le renseignement électronique au-dessus du Vietnam.', role_en = 'The two EP-3B *Bat Rack* aircraft, the first electronic-intelligence Orions, went to the Navy''s VQ-1 squadron in 1969 and deployed to Da Nang for signals intelligence over Vietnam.', sources = 'https://en.wikipedia.org/wiki/Lockheed_EP-3'
