UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), role = 'Avion d''observation silencieux de l''US Army : neuf des onze exemplaires volent de nuit au Sud-Vietnam de juin 1970 à septembre 1971 pour repérer les mouvements du Viet Cong et de l''armée nord-vietnamienne. Trois sont détruits par accident, aucun par le feu ennemi.', role_en = 'A quiet US Army night observation aircraft: nine of the eleven built flew at night over South Vietnam from June 1970 to September 1971, spotting Viet Cong and North Vietnamese army movements. Three were lost in crashes, none to enemy fire.', sources = 'https://en.wikipedia.org/wiki/Lockheed_YO-3'
