UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'nord-vietnam'), role = 'Livré au Nord-Vietnam à partir de 1965, le MiG-21 du 921e régiment pratique l''interception éclair guidée du sol contre les raids américains. En décembre 1966, ses pilotes revendiquent 14 F-105 ; le 2 janvier 1967, l''opération *Bolo* lui coûte cinq appareils selon Hanoï, sept selon l''USAF.', role_en = 'Delivered to North Vietnam from 1965, the 921st Regiment''s MiG-21s flew ground-controlled hit-and-run intercepts against US strikes. Its pilots claimed 14 F-105s in December 1966; Operation *Bolo* on 2 January 1967 cost five aircraft by Hanoi''s count, seven by the USAF''s.', sources = 'https://en.wikipedia.org/wiki/Vietnam_People%27s_Air_Force
https://en.wikipedia.org/wiki/Mikoyan-Gurevich_MiG-21_operators
https://en.wikipedia.org/wiki/Operation_Bolo'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'MiG-21' AND w.name = 'Guerre du Vietnam'
