   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM (NULL::int, 'Avion d''attaque de Farm Gate et de la VNAF au début de la guerre, puis des aviations lao et khmère. Un T-28 lao passé au Nord aurait, selon les sources vietnamiennes, abattu un C-123 le 15 février 1964. L''US Air Force perd 23 T-28.', 'A strike aircraft for Farm Gate and the VNAF early in the war, then for the Lao and Khmer air forces. A Lao T-28 that defected to the North reportedly shot down a C-123 on 15 February 1964. The USAF lost 23 T-28s.', 'https://en.wikipedia.org/wiki/North_American_T-28_Trojan
https://en.wikipedia.org/wiki/Operation_Farm_Gate');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), role = 'Les U-2 taïwanais de la CIA survolent le Nord dès 1962 ; à partir de 1964, le détachement du Strategic Air Command à Biên Hòa (349e escadron) photographie le Nord à haute altitude. Une seule perte en opération, le 9 octobre 1966, pilote sauvé.', role_en = 'CIA Taiwanese U-2s overflew the North from 1962; from 1964 the Strategic Air Command detachment at Bien Hoa (349th Squadron) photographed the North from high altitude. Only one operational loss, on 9 October 1966, pilot saved.', sources = 'https://en.wikipedia.org/wiki/Lockheed_U-2'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'U-2 Dragon Lady' AND w.name = 'Guerre du Vietnam'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis-allies'), 'Les U-2 taïwanais de la CIA survolent le Nord dès 1962 ; à partir de 1964, le détachement du Strategic Air Command à Biên Hòa (349e escadron) photographie le Nord à haute altitude. Une seule perte en opération, le 9 octobre 1966, pilote sauvé.', 'CIA Taiwanese U-2s overflew the North from 1962; from 1964 the Strategic Air Command detachment at Bien Hoa (349th Squadron) photographed the North from high altitude. Only one operational loss, on 9 October 1966, pilot saved.', 'https://en.wikipedia.org/wiki/Lockheed_U-2');
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1964-08-02', 'day', 'Incident du golfe du Tonkin', 'Gulf of Tonkin incident', 'Trois vedettes nord-vietnamiennes approchent le destroyer Maddox ; quatre F-8 Crusader du Ticonderoga les attaquent et revendiquent une vedette coulée. L''incident ouvre la voie à la résolution du Congrès.', 'Three North Vietnamese torpedo boats close on the destroyer Maddox; four F-8 Crusaders from Ticonderoga attack them and claim one sunk. The incident paves the way for the congressional resolution.', (SELECT id FROM airplanes WHERE name = 'F-8 Crusader'), 'https://en.wikipedia.org/wiki/Gulf_of_Tonkin_incident' FROM wars w WHERE w.name = 'Guerre du Vietnam'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1964-08-05', 'day', 'Opération Pierce Arrow', 'Operation Pierce Arrow', 'Les avions du Ticonderoga et du Constellation frappent les bases de vedettes et les dépôts de carburant du Nord. Abattu sur son A-4, Everett Alvarez devient le premier prisonnier de guerre de l''US Navy.', 'Aircraft from Ticonderoga and Constellation strike the North''s torpedo-boat bases and fuel depots. Shot down in his A-4, Everett Alvarez becomes the US Navy''s first prisoner of war.', (SELECT id FROM airplanes WHERE name = 'A-4 Skyhawk'), 'https://en.wikipedia.org/wiki/Douglas_A-4_Skyhawk' FROM wars w WHERE w.name = 'Guerre du Vietnam'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-03-02', 'day', 'Début de Rolling Thunder', 'Rolling Thunder begins', '104 avions américains (B-57, F-105, F-100) attaquent un dépôt de munitions à Xom Bang et 19 Skyraider sud-vietnamiens la base navale de Quang Khe. Six appareils américains sont abattus dès ce premier jour.', '104 American aircraft (B-57s, F-105s, F-100s) attack an ammunition depot at Xom Bang while 19 South Vietnamese Skyraiders hit Quang Khe naval base. Six American aircraft are shot down on this first day.', NULL::int, 'https://en.wikipedia.org/wiki/Operation_Rolling_Thunder' FROM wars w WHERE w.name = 'Guerre du Vietnam'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-04-04', 'day', 'Les MiG-17 frappent au pont de Thanh Hóa', 'MiG-17s strike at the Thanh Hoa Bridge', 'Quatre MiG-17 du 921e régiment contournent l''escorte de F-100 et abattent deux F-105 : les premières victoires reconnues par les deux camps. Selon leur chef, trois MiG ne rentrent pas.', 'Four MiG-17s of the 921st Regiment slip past the F-100 escort and shoot down two F-105s, the first victories acknowledged by both sides. According to their leader, three MiGs fail to return.', (SELECT id FROM airplanes WHERE name = 'MiG-17'), 'https://en.wikipedia.org/wiki/Mikoyan-Gurevich_MiG-17' FROM wars w WHERE w.name = 'Guerre du Vietnam'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-06-18', 'day', 'Première mission Arc Light', 'First Arc Light mission', 'Trente B-52F partis de Guam bombardent un bastion communiste près de Bến Cát. Deux bombardiers se heurtent en vol avant l''objectif ; huit aviateurs sont tués.', 'Thirty B-52Fs from Guam bomb a communist stronghold near Ben Cat. Two bombers collide before reaching the target, killing eight airmen.', (SELECT id FROM airplanes WHERE name = 'B-52 Stratofortress'), 'https://en.wikipedia.org/wiki/Boeing_B-52_Stratofortress' FROM wars w WHERE w.name = 'Guerre du Vietnam'
