INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-07-24', 'day', 'Premier avion abattu par un missile SA-2', 'First aircraft downed by an SA-2 missile', 'Quatre F-4C attaquent un dépôt de munitions à l''ouest de Hanoï : un est abattu et trois endommagés par des SA-2. C''est la première fois que des missiles sol-air visent des avions américains.', 'Four F-4Cs attack a munitions depot west of Hanoi: one is shot down and three damaged by SA-2s, the first time American aircraft are attacked by surface-to-air missiles.', (SELECT id FROM airplanes WHERE name = 'F-4 Phantom II'), 'https://en.wikipedia.org/wiki/Operation_Rolling_Thunder' FROM wars w WHERE w.name = 'Guerre du Vietnam'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
