 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1968-01-12', 'day', 'Raid des An-2 sur le site 85', 'An-2 raid on Lima Site 85', 'Des biplans An-2 attaquent à la roquette et au mortier largué à la main la station radar secrète de Phou Pha Thi, au Laos. Deux sont abattus, l''un par un hélicoptère d''Air America.', 'An-2 biplanes attack the secret radar station at Phou Pha Thi, Laos, with rockets and hand-dropped mortar shells. Two are brought down, one of them by an Air America helicopter.', (SELECT id FROM airplanes WHERE name = 'Antonov An-2'), 'https://en.wikipedia.org/wiki/Vietnam_People%27s_Air_Force' FROM wars w WHERE w.name = 'Guerre du Vietnam'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
