INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1968-01-21', 'day', 'Début du siège de Khe Sanh', 'Siege of Khe Sanh begins', 'Les divisions nord-vietnamiennes encerclent la base des Marines. Ravitaillée par les airs, elle reçoit 65 % de ses approvisionnements par parachutages de C-130, sous le parapluie des bombardements de l''opération Niagara.', 'North Vietnamese divisions surround the Marine base. Supplied from the air, it receives 65% of its supplies by C-130 airdrops, under the umbrella of Operation Niagara''s bombing.', (SELECT id FROM airplanes WHERE name = 'C-130 Hercules'), 'https://en.wikipedia.org/wiki/Battle_of_Khe_Sanh' FROM wars w WHERE w.name = 'Guerre du Vietnam'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1968-05-12', 'day', 'Sauvetage de Kham Duc', 'Rescue at Kham Duc', 'Le lieutenant-colonel Joe Jackson pose son C-123 sur le camp de forces spéciales submergé et récupère trois membres de l''US Air Force restés au sol. Il reçoit la Medal of Honor.', 'Lieutenant Colonel Joe Jackson lands his C-123 at the overrun Special Forces camp and rescues three US Air Force men left behind. He receives the Medal of Honor.', (SELECT id FROM airplanes WHERE name = 'C-123 Provider'), 'https://en.wikipedia.org/wiki/Joe_M._Jackson' FROM wars w WHERE w.name = 'Guerre du Vietnam'
