INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1969-03-18', 'day', 'Bombardements secrets du Cambodge', 'Secret bombing of Cambodia', 'Le Strategic Air Command lance l''opération Menu contre les sanctuaires nord-vietnamiens de l''est du Cambodge. L''opération Freedom Deal la prolonge jusqu''au 15 août 1973.', 'Strategic Air Command launches Operation Menu against North Vietnamese sanctuaries in eastern Cambodia. Operation Freedom Deal carries it on until 15 August 1973.', NULL::int, 'https://en.wikipedia.org/wiki/Operation_Menu' FROM wars w WHERE w.name = 'Guerre du Vietnam'
