INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1972-04-02', 'day', 'Bat 21 abattu', 'Bat 21 shot down', 'Au troisième jour de l''offensive de Pâques, un EB-66C qui escorte des B-52 est détruit par un SA-2. Le sauvetage de son seul survivant, Iceal Hambleton, coûte cinq autres appareils.', 'On the third day of the Easter Offensive, an EB-66C escorting B-52s is destroyed by an SA-2. The rescue of its sole survivor, Iceal Hambleton, costs five more aircraft.', (SELECT id FROM airplanes WHERE name = 'B-66 Destroyer'), 'https://en.wikipedia.org/wiki/Rescue_of_Bat_21_Bravo' FROM wars w WHERE w.name = 'Guerre du Vietnam'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1972-05-09', 'day', 'Minage de Haïphong', 'Mining of Haiphong', 'Six A-7 et trois A-6 du Coral Sea mouillent 36 mines dans le port de Haïphong (opération Pocket Money), au premier jour de Linebacker. D''autres avions embarqués minent ensuite les ports secondaires.', 'Six A-7s and three A-6s from Coral Sea lay 36 mines in Haiphong harbor (Operation Pocket Money) on the first day of Linebacker. Other carrier aircraft then mine the secondary ports.', (SELECT id FROM airplanes WHERE name = 'A-7 Corsair II'), 'https://en.wikipedia.org/wiki/Operation_Linebacker' FROM wars w WHERE w.name = 'Guerre du Vietnam'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
