INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1972-12-18', 'day', 'Linebacker II', 'Linebacker II', 'Les B-52 frappent Hanoï et Haïphong pendant onze jours. Dès la première nuit, le mitrailleur de queue Samuel Turner est crédité d''un MiG-21, l''une des deux victoires attribuées aux B-52.', 'B-52s strike Hanoi and Haiphong for eleven days. On the first night, tail gunner Samuel Turner is credited with a MiG-21, one of the two victories credited to B-52 gunners.', (SELECT id FROM airplanes WHERE name = 'B-52 Stratofortress'), 'https://en.wikipedia.org/wiki/Operation_Linebacker_II' FROM wars w WHERE w.name = 'Guerre du Vietnam'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
