INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1975-04-29', 'day', 'Fuite vers le Midway', 'Escape to Midway', 'À la veille de la chute de Saïgon, le major Bung-Ly s''enfuit de Côn Sơn avec sa femme et ses cinq enfants à bord d''un O-1 biplace et se pose sur le porte-avions Midway, qui pousse des hélicoptères à la mer pour lui faire place.', 'On the eve of the fall of Saigon, Major Bung-Ly flees Con Son with his wife and five children in a two-seat O-1 and lands on the carrier Midway, which pushes helicopters overboard to make room.', (SELECT id FROM airplanes WHERE name = 'Cessna O-1 Bird Dog'), 'https://en.wikipedia.org/wiki/Cessna_O-1_Bird_Dog' FROM wars w WHERE w.name = 'Guerre du Vietnam'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
