UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'ethiopie'), role = 'Achetés en urgence à la Russie (huit livrés à partir de décembre 1998), les Su-27 éthiopiens remportent les premiers combats de l''histoire contre des MiG-29 : deux abattus les 25 et 26 février 1999, un endommagé le 21. L''Éthiopie revendique d''autres victoires en mai 2000.', role_en = 'Bought urgently from Russia (eight delivered from December 1998), Ethiopia''s Su-27s won the first ever combats against MiG-29s: two shot down on 25 and 26 February 1999, another damaged on the 21st. Ethiopia claims further kills in May 2000.', sources = 'https://en.wikipedia.org/wiki/Sukhoi_Su-27
https://en.wikipedia.org/wiki/February_1999_Eritrean%E2%80%93Ethiopian_aerial_clashes
https://acig.org/artman/publish/printer_189.shtml'
  FROM airplanes a, wars w
