INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1998-05-06', 'day', 'Les incidents de Badme', 'The Badme incidents', 'Après des accrochages où plusieurs responsables érythréens sont tués, une force mécanisée érythréenne entre dans la région de Badme, revendiquée par les deux pays.', 'After clashes in which several Eritrean officials were killed, an Eritrean mechanised force entered the Badme area, claimed by both countries.', NULL::int, 'https://en.wikipedia.org/wiki/Eritrean%E2%80%93Ethiopian_War' FROM wars w WHERE w.name = 'Guerre Érythrée-Éthiopie'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1998-06-05', 'day', 'Les MiG-23 sur Asmara', 'MiG-23s over Asmara', 'Deux MiG-23BN éthiopiens attaquent l''aéroport d''Asmara, touchant un Boeing 727 et deux hangars ; l''un est abattu par la DCA et son pilote tué.', 'Two Ethiopian MiG-23BNs attacked Asmara airport, hitting a Boeing 727 and two hangars; one was shot down by anti-aircraft fire, killing its pilot.', (SELECT id FROM airplanes WHERE name = 'MiG-23'), 'https://acig.org/artman/publish/printer_189.shtml' FROM wars w WHERE w.name = 'Guerre Érythrée-Éthiopie'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1998-06-05', 'day', 'Les MB-339 sur Mekele', 'MB-339s over Mekelle', 'En représailles, des MB-339 érythréens bombardent Mekele ; des sous-munitions frappent une école primaire et tuent des dizaines d''enfants et de parents.', 'In retaliation, Eritrean MB-339s bombed Mekelle; cluster munitions hit a primary school, killing dozens of children and parents.', (SELECT id FROM airplanes WHERE name = 'Aermacchi MB-339'), 'https://en.wikipedia.org/wiki/Eritrean%E2%80%93Ethiopian_War' FROM wars w WHERE w.name = 'Guerre Érythrée-Éthiopie'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
