INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1998-06-06', 'day', 'Un MiG-21 abattu au-dessus d''Asmara', 'A MiG-21 downed over Asmara', 'Un MiG-21 éthiopien est abattu ; son pilote, le colonel Bezabeh Petros, est capturé, comme il l''avait déjà été pendant la guerre d''indépendance.', 'An Ethiopian MiG-21 was shot down; its pilot, Colonel Bezabeh Petros, was captured, as he had already been during the war of independence.', NULL::int, 'https://acig.org/artman/publish/printer_189.shtml' FROM wars w WHERE w.name = 'Guerre Érythrée-Éthiopie'
