INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1998-06-14', 'day', 'Moratoire sur les frappes aériennes', 'Air strike moratorium', 'Sur proposition des États-Unis, l''Érythrée et l''Éthiopie acceptent de cesser immédiatement les frappes aériennes et la menace d''en faire.', 'Following a US proposal, Eritrea and Ethiopia agreed to halt air strikes and the threat of air strikes immediately.', NULL::int, 'https://clintonwhitehouse6.archives.gov/1998/06/1998-06-14-statement-by-the-press-secretary-on-ethiopia-and-eritrea.html' FROM wars w WHERE w.name = 'Guerre Érythrée-Éthiopie'
