INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1998-12-15', 'day', 'Les Su-27 arrivent', 'The Su-27s arrive', 'Le premier des huit Su-27 achetés par l''Éthiopie quitte Krasnodar ; quelque 80 Russes arrivent en décembre pour les mettre en œuvre.', 'The first of the eight Su-27s bought by Ethiopia left Krasnodar; some 80 Russians arrived in December to bring them into service.', (SELECT id FROM airplanes WHERE name = 'Su-27'), 'https://acig.org/artman/publish/printer_189.shtml' FROM wars w WHERE w.name = 'Guerre Érythrée-Éthiopie'
