INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1999-02-22', 'day', 'L''opération *Sunset*', 'Operation *Sunset*', 'L''offensive éthiopienne pour reprendre Badme commence par l''attaque de l''aéroport d''Assab par quatre chasseurs ; des Mi-24 mitraillent ensuite les troupes érythréennes en retraite.', 'The Ethiopian offensive to retake Badme opened with an attack on Assab airport by four fighters; Mi-24s later rocketed retreating Eritrean troops.', NULL::int, 'https://en.wikipedia.org/wiki/Eritrean%E2%80%93Ethiopian_War' FROM wars w WHERE w.name = 'Guerre Érythrée-Éthiopie'
