INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1999-02-25', 'day', 'Premier MiG-29 abattu par un Su-27', 'First MiG-29 downed by a Su-27', 'Au nord de Mekele, un Su-27 éthiopien abat le MiG-29 érythréen de Yonas Misghinna, tué : c''est la première victoire d''un Su-27 sur un MiG-29.', 'North of Mekelle, an Ethiopian Su-27 shot down the Eritrean MiG-29 of Yonas Misghinna, who was killed: the first victory of a Su-27 over a MiG-29.', (SELECT id FROM airplanes WHERE name = 'Su-27'), 'https://en.wikipedia.org/wiki/February_1999_Eritrean%E2%80%93Ethiopian_aerial_clashes' FROM wars w WHERE w.name = 'Guerre Érythrée-Éthiopie'
