INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1999-02-26', 'day', 'Un second MiG-29 perdu', 'A second MiG-29 lost', 'Envoyé d''Asmara contre un Su-27, le MiG-29 de Samuel Girmay est abattu et son pilote tué ; l''Érythrée ne garde que deux MiG-29 en état de vol.', 'Sent from Asmara against a Su-27, Samuel Girmay''s MiG-29 was shot down and he was killed; Eritrea was left with only two flyable MiG-29s.', (SELECT id FROM airplanes WHERE name = 'MiG-29'), 'https://en.wikipedia.org/wiki/February_1999_Eritrean%E2%80%93Ethiopian_aerial_clashes' FROM wars w WHERE w.name = 'Guerre Érythrée-Éthiopie'
