INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2000-05-29', 'day', 'L''aéroport d''Asmara bombardé', 'Asmara airport bombed', 'Au lendemain d''un raid sur la centrale de Hirgigo, près de Massaoua, quatre MiG-23BN frappent l''aéroport d''Asmara à la roquette et à la bombe ; la tour de contrôle brûle.', 'The day after a raid on the Hirgigo power station near Massawa, four MiG-23BNs struck Asmara airport with rockets and bombs; the control tower was set ablaze.', (SELECT id FROM airplanes WHERE name = 'MiG-23'), 'https://acig.org/artman/publish/printer_189.shtml' FROM wars w WHERE w.name = 'Guerre Érythrée-Éthiopie'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2000-06-18', 'day', 'La cessation des hostilités', 'The cessation of hostilities', 'À Alger, l''Éthiopie et l''Érythrée acceptent la fin des combats et un arbitrage contraignant de leur frontière, sous le contrôle de casques bleus.', 'In Algiers, Ethiopia and Eritrea agreed to end the fighting and to binding arbitration of their border, monitored by UN peacekeepers.', NULL::int, 'https://en.wikipedia.org/wiki/Eritrean%E2%80%93Ethiopian_War' FROM wars w WHERE w.name = 'Guerre Érythrée-Éthiopie'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
