INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'occident', 1, 'Occident', 'Western bloc', 'États-Unis, Royaume-Uni, France, Canada, Allemagne de l''Ouest et autres membres de l''OTAN, Japon et alliés occidentaux', 'United States, United Kingdom, France, Canada, West Germany and other NATO members, Japan and Western allies' FROM wars w WHERE w.name = 'Guerre froide'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'bloc-sovietique', 2, 'Bloc soviétique', 'Soviet bloc', 'Union soviétique, Allemagne de l''Est, Pologne, Tchécoslovaquie, Hongrie, Roumanie, Bulgarie et autres alliés de Moscou', 'Soviet Union, East Germany, Poland, Czechoslovakia, Hungary, Romania, Bulgaria and Moscow''s other allies' FROM wars w WHERE w.name = 'Guerre froide'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'neutres', 3, 'Pays neutres', 'Neutral countries', 'Suède et autres pays non alignés dont l''aviation a fait face aux deux blocs', 'Sweden and other non-aligned countries whose air arms faced both blocs' FROM wars w WHERE w.name = 'Guerre froide'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre froide' AND s.side_key NOT IN ('occident', 'bloc-sovietique', 'neutres');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'En 1958, des B-26 de la CIA appuient en secret les rebelles indonésiens de Permesta (opération *Haik*) ; le 18 mai, le pilote contractuel Allen Pope est abattu. Des RB-26 assurent aussi la reconnaissance du SAC en 1949-1950, puis en Europe jusqu''en 1957.', role_en = 'In 1958 CIA B-26s covertly supported Indonesia''s Permesta rebels (Operation *Haik*); on 18 May contract pilot Allen Pope was shot down. RB-26s also flew reconnaissance for SAC in 1949-1950 and in Europe until 1957.', sources = 'https://en.wikipedia.org/wiki/Douglas_A-26_Invader
https://en.wikipedia.org/wiki/Permesta'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'A-26 Invader' AND w.name = 'Guerre froide'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), 'En 1958, des B-26 de la CIA appuient en secret les rebelles indonésiens de Permesta (opération *Haik*) ; le 18 mai, le pilote contractuel Allen Pope est abattu. Des RB-26 assurent aussi la reconnaissance du SAC en 1949-1950, puis en Europe jusqu''en 1957.', 'In 1958 CIA B-26s covertly supported Indonesia''s Permesta rebels (Operation *Haik*); on 18 May contract pilot Allen Pope was shot down. RB-26s also flew reconnaissance for SAC in 1949-1950 and in Europe until 1957.', 'https://en.wikipedia.org/wiki/Douglas_A-26_Invader
https://en.wikipedia.org/wiki/Permesta');
