UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Les A-7D de l''Air National Guard se déploient en Allemagne de l''Ouest et au Danemark lors des exercices REFORGER ; dès 1981, ceux de Tonopah, laissés exprès à découvert, trompent les satellites espions soviétiques pour cacher le programme F-117.', role_en = 'Air National Guard A-7Ds deployed to West Germany and Denmark during REFORGER exercises; from 1981 those at Tonopah were deliberately left in the open to mislead Soviet spy satellites and hide the F-117 programme.', sources = 'https://en.wikipedia.org/wiki/LTV_A-7_Corsair_II'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'A-7 Corsair II' AND w.name = 'Guerre froide'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), 'Les A-7D de l''Air National Guard se déploient en Allemagne de l''Ouest et au Danemark lors des exercices REFORGER ; dès 1981, ceux de Tonopah, laissés exprès à découvert, trompent les satellites espions soviétiques pour cacher le programme F-117.', 'Air National Guard A-7Ds deployed to West Germany and Denmark during REFORGER exercises; from 1981 those at Tonopah were deliberately left in the open to mislead Soviet spy satellites and hide the F-117 programme.', 'https://en.wikipedia.org/wiki/LTV_A-7_Corsair_II');
