UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Pilier du NORAD contre les bombardiers soviétiques (neuf escadrons de l’ARC au milieu des années 1950), il équipe de 1956 à 1962 quatre escadrons de la 1re Division aérienne en Europe, dont le 423e à Grostenquin, seul chasseur tous temps de l’OTAN.', role_en = 'A NORAD mainstay against Soviet bombers (nine RCAF squadrons in the mid-1950s), it equipped four No. 1 Air Division squadrons in Europe from 1956 to 1962, including No. 423 at Grostenquin, NATO’s only all-weather fighter at the time.', sources = 'https://en.wikipedia.org/wiki/Avro_Canada_CF-100_Canuck'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Avro Canada CF-100 Canuck' AND w.name = 'Guerre froide'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), 'Pilier du NORAD contre les bombardiers soviétiques (neuf escadrons de l’ARC au milieu des années 1950), il équipe de 1956 à 1962 quatre escadrons de la 1re Division aérienne en Europe, dont le 423e à Grostenquin, seul chasseur tous temps de l’OTAN.', 'A NORAD mainstay against Soviet bombers (nine RCAF squadrons in the mid-1950s), it equipped four No. 1 Air Division squadrons in Europe from 1956 to 1962, including No. 423 at Grostenquin, NATO’s only all-weather fighter at the time.', 'https://en.wikipedia.org/wiki/Avro_Canada_CF-100_Canuck');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Bombardier lourd de la RAF jusqu''à l''arrivée des bombardiers V. Le 12 mars 1953, le Lincoln RF531 de la Central Gunnery School est abattu par des MiG-15 soviétiques à 32 km au nord-est de Lunebourg, lors d''un vol vers Berlin : ses sept hommes d''équipage sont tués.', role_en = 'RAF heavy bomber until the V-bombers arrived. On 12 March 1953 Lincoln RF531 of the Central Gunnery School was shot down by Soviet MiG-15s 20 miles north-east of Lüneburg during a flight to Berlin, killing all seven crew.', sources = 'https://en.wikipedia.org/wiki/Avro_Lincoln'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Avro Lincoln' AND w.name = 'Guerre froide'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), 'Bombardier lourd de la RAF jusqu''à l''arrivée des bombardiers V. Le 12 mars 1953, le Lincoln RF531 de la Central Gunnery School est abattu par des MiG-15 soviétiques à 32 km au nord-est de Lunebourg, lors d''un vol vers Berlin : ses sept hommes d''équipage sont tués.', 'RAF heavy bomber until the V-bombers arrived. On 12 March 1953 Lincoln RF531 of the Central Gunnery School was shot down by Soviet MiG-15s 20 miles north-east of Lüneburg during a flight to Berlin, killing all seven crew.', 'https://en.wikipedia.org/wiki/Avro_Lincoln');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Conçu contre la flotte sous-marine soviétique, il équipe le Coastal Command dans l''Atlantique Nord dès 1951, avec des grenades anti-sous-marines nucléaires à partir de 1966 ; de 1972 au 1er juillet 1991, la version AEW.2 du 8e escadron (Lossiemouth) assure le guet aérien lointain britannique.', role_en = 'Designed to counter the Soviet submarine fleet, it equipped Coastal Command over the North Atlantic from 1951, carrying nuclear depth charges from 1966; from 1972 to 1 July 1991 No. 8 Squadron''s AEW.2s (Lossiemouth) provided Britain''s airborne early warning.', sources = 'https://en.wikipedia.org/wiki/Avro_Shackleton'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Avro Shackleton' AND w.name = 'Guerre froide'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), 'Conçu contre la flotte sous-marine soviétique, il équipe le Coastal Command dans l''Atlantique Nord dès 1951, avec des grenades anti-sous-marines nucléaires à partir de 1966 ; de 1972 au 1er juillet 1991, la version AEW.2 du 8e escadron (Lossiemouth) assure le guet aérien lointain britannique.', 'Designed to counter the Soviet submarine fleet, it equipped Coastal Command over the North Atlantic from 1951, carrying nuclear depth charges from 1966; from 1972 to 1 July 1991 No. 8 Squadron''s AEW.2s (Lossiemouth) provided Britain''s airborne early warning.', 'https://en.wikipedia.org/wiki/Avro_Shackleton');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Pilier de la force V de la RAF à partir de 1957, le Vulcan tient l''alerte nucléaire (QRA) dès 1962, prêt à décoller en quinze minutes, et emporte le missile Blue Steel de 1963 à 1970. En octobre 1962, la crise de Cuba place le Bomber Command en alerte 3.', role_en = 'A mainstay of the RAF''s V-force from 1957, the Vulcan stood nuclear Quick Reaction Alert from 1962, ready to launch within fifteen minutes, and carried the Blue Steel missile from 1963 to 1970. In October 1962 the Cuban crisis put Bomber Command on Alert Condition 3.', sources = 'https://en.wikipedia.org/wiki/Avro_Vulcan'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Avro Vulcan' AND w.name = 'Guerre froide'
