UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'De 1983 à 1986, des Hawk T1 de la RAF sont modifiés en Hawk T1A pour emporter deux Sidewinder et un canon : en guerre, guidés par le radar des Tornado F3, ils devaient défendre en dernier recours le ciel britannique.', role_en = 'From 1983 to 1986, RAF Hawk T1s were converted to T1A standard to carry two Sidewinders and a gun pod: in wartime, cued by Tornado F3 radar, they were to act as a last-ditch defence of British airspace.', sources = 'https://en.wikipedia.org/wiki/BAE_Systems_Hawk
