UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'À partir de 1984, les RC-12 Guardrail de l''US Army remplacent en Allemagne de l''Ouest les RU-21 qui surveillent depuis 1971 les mouvements des troupes du bloc soviétique en RDA et en Tchécoslovaquie, par l''écoute de leurs émissions.', role_en = 'From 1984 the US Army''s RC-12 Guardrail aircraft replaced, in West Germany, the RU-21s that had been monitoring Soviet bloc troop movements in East Germany and Czechoslovakia since 1971 by intercepting their emissions.', sources = 'https://www.army.mil/article/61251/guardrail_turns_40_modernization_keeps_it_going'
