UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Le 5 octobre 1986, un C-123 qui livre des armes aux Contras pour un réseau lié à la CIA est abattu au-dessus du Nicaragua par un missile soviétique SA-7 des sandinistes ; le survivant, Eugene Hasenfus, prouve l''implication américaine.', role_en = 'On 5 October 1986 a C-123 flying weapons to the Contras for a CIA-linked network was shot down over Nicaragua by a Sandinista Soviet-made SA-7 missile; the survivor, Eugene Hasenfus, exposed US involvement.', sources = 'https://en.wikipedia.org/wiki/Eugene_Hasenfus'
  FROM airplanes a, wars w
