   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), 'Le 5 octobre 1986, un C-123 qui livre des armes aux Contras pour un réseau lié à la CIA est abattu au-dessus du Nicaragua par un missile soviétique SA-7 des sandinistes ; le survivant, Eugene Hasenfus, prouve l''implication américaine.', 'On 5 October 1986 a C-123 flying weapons to the Contras for a CIA-linked network was shot down over Nicaragua by a Sandinista Soviet-made SA-7 missile; the survivor, Eugene Hasenfus, exposed US involvement.', 'https://en.wikipedia.org/wiki/Eugene_Hasenfus');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Le 2 septembre 1958, un C-130A-II d''écoute électronique du 7406th Support Squadron, parti d''Incirlik pour longer la frontière turco-soviétique, est abattu par quatre MiG-17 près d''Erevan ; ses 17 occupants sont présumés morts.', role_en = 'On 2 September 1958 a C-130A-II electronic intelligence aircraft of the 7406th Support Squadron, flying from Incirlik along the Turkish-Soviet border, was shot down by four MiG-17s near Yerevan; all 17 aboard are presumed dead.', sources = 'https://en.wikipedia.org/wiki/1958_C-130_shootdown_incident'
