   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), 'Le 2 septembre 1958, un C-130A-II d''écoute électronique du 7406th Support Squadron, parti d''Incirlik pour longer la frontière turco-soviétique, est abattu par quatre MiG-17 près d''Erevan ; ses 17 occupants sont présumés morts.', 'On 2 September 1958 a C-130A-II electronic intelligence aircraft of the 7406th Support Squadron, flying from Incirlik along the Turkish-Soviet border, was shot down by four MiG-17s near Yerevan; all 17 aboard are presumed dead.', 'https://en.wikipedia.org/wiki/1958_C-130_shootdown_incident');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'En janvier 1969, 63 C-141 du Military Airlift Command amènent en deux jours quelque 5 000 soldats à Nuremberg pour *Reforger I*, premier exercice de renforcement rapide des forces américaines en Allemagne de l''Ouest.', role_en = 'In January 1969, 63 Military Airlift Command C-141s flew some 5,000 soldiers into Nuremberg in two days for *Reforger I*, the first exercise in rapidly reinforcing US forces in West Germany.', sources = 'https://www.stripes.com/history/2023-03-08/reforger-debut-germany-1969-9402523.html'
