 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'C-141 Starlifter' AND w.name = 'Guerre froide'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), 'En janvier 1969, 63 C-141 du Military Airlift Command amènent en deux jours quelque 5 000 soldats à Nuremberg pour *Reforger I*, premier exercice de renforcement rapide des forces américaines en Allemagne de l''Ouest.', 'In January 1969, 63 Military Airlift Command C-141s flew some 5,000 soldiers into Nuremberg in two days for *Reforger I*, the first exercise in rapidly reinforcing US forces in West Germany.', 'https://www.stripes.com/history/2023-03-08/reforger-debut-germany-1969-9402523.html');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Le 24 octobre 1974, un C-5A largue sous parachute un missile Minuteman I tiré en plein vol : l''essai prouve qu''un missile intercontinental peut partir d''un avion, capacité jamais déployée mais avancée comme monnaie d''échange dans les négociations SALT.', role_en = 'On 24 October 1974 a C-5A dropped a Minuteman I missile by parachute and it was fired in mid-air: the test proved an ICBM could be air-launched, a capability never deployed but used as a bargaining chip in the SALT talks.', sources = 'https://en.wikipedia.org/wiki/Lockheed_C-5_Galaxy'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'C-5 Galaxy' AND w.name = 'Guerre froide'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), 'Le 24 octobre 1974, un C-5A largue sous parachute un missile Minuteman I tiré en plein vol : l''essai prouve qu''un missile intercontinental peut partir d''un avion, capacité jamais déployée mais avancée comme monnaie d''échange dans les négociations SALT.', 'On 24 October 1974 a C-5A dropped a Minuteman I missile by parachute and it was fired in mid-air: the test proved an ICBM could be air-launched, a capability never deployed but used as a bargaining chip in the SALT talks.', 'https://en.wikipedia.org/wiki/Lockheed_C-5_Galaxy');
