UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'De 1956 à 1990, les Chipmunk du Station Flight de RAF Gatow, à Berlin-Ouest, mènent pour la mission militaire britannique BRIXMIS des vols de reconnaissance discrète au-dessus de la région de Berlin.', role_en = 'From 1956 to 1990, the Chipmunks of the RAF Gatow Station Flight in West Berlin flew covert reconnaissance sorties over the Berlin area for the British military mission BRIXMIS.', sources = 'https://en.wikipedia.org/wiki/De_Havilland_Canada_DHC-1_Chipmunk'
