UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Le Strategic Air Command aligne une cinquantaine de C-124 de 1950 à 1962, d''abord pour déplacer ses armes nucléaires entre bases ; de 1959 à 1961, les C-124 transportent aussi à travers l''Atlantique les missiles Thor déployés en Angleterre.', role_en = 'Strategic Air Command flew some fifty C-124s from 1950 to 1962, chiefly to move its nuclear weapons between bases; from 1959 to 1961 C-124s also carried the Thor missiles deployed in England across the Atlantic.', sources = 'https://en.wikipedia.org/wiki/Douglas_C-124_Globemaster_II'
