 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Douglas C-124 Globemaster II' AND w.name = 'Guerre froide'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), 'Le Strategic Air Command aligne une cinquantaine de C-124 de 1950 à 1962, d''abord pour déplacer ses armes nucléaires entre bases ; de 1959 à 1961, les C-124 transportent aussi à travers l''Atlantique les missiles Thor déployés en Angleterre.', 'Strategic Air Command flew some fifty C-124s from 1950 to 1962, chiefly to move its nuclear weapons between bases; from 1959 to 1961 C-124s also carried the Thor missiles deployed in England across the Atlantic.', 'https://en.wikipedia.org/wiki/Douglas_C-124_Globemaster_II');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Les C-133 de l''US Air Force transportent vers et depuis leurs bases plusieurs centaines de missiles intercontinentaux Atlas, Titan et Minuteman, pièces maîtresses de la dissuasion nucléaire américaine.', role_en = 'US Air Force C-133s airlifted several hundred Atlas, Titan and Minuteman intercontinental missiles to and from their operational bases, the core of America''s nuclear deterrent.', sources = 'https://en.wikipedia.org/wiki/Douglas_C-133_Cargomaster'
