UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Radar volant des groupes aéronavals américains, conçu contre les bombardiers soviétiques porteurs de missiles ; début 1991, des Hawkeye du VAW-116 pistent des Tu-95 au départ de Subic Bay (Philippines), interceptés ensuite par les F-14.', role_en = 'Airborne radar of US carrier groups, designed against Soviet missile-carrying bombers; in early 1991 VAW-116 Hawkeyes tracked Tu-95 Bears while leaving Subic Bay in the Philippines, which F-14s then intercepted.', sources = 'https://www.twz.com/25572/confessions-of-an-e-2c-hawkeye-radar-operator'
