UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Le 15 juillet 1958, 29 F-100 du 354th TFW gagnent Incirlik pour la crise du Liban ; en 1961, pendant la crise de Berlin, le 614th TFS est envoyé à Ramstein, et en octobre 1962, 181 F-100 se massent à Homestead face à Cuba.', role_en = 'On 15 July 1958, 29 F-100s of the 354th TFW deployed to Incirlik for the Lebanon crisis; in 1961, during the Berlin crisis, the 614th TFS was sent to Ramstein, and in October 1962, 181 F-100s massed at Homestead facing Cuba.', sources = 'https://en.wikipedia.org/wiki/North_American_F-100_Super_Sabre'
  FROM airplanes a, wars w
