UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'En octobre 1962, les RF-101A du 363rd TRW photographient Cuba à basse altitude ; les F-101A/C du 81st TFW (Bentwaters) tiennent une force de frappe nucléaire en Angleterre, et les F-101B de l’ADC (dès 1959) puis CF-101 canadiens servent le NORAD jusqu’en 1984.', role_en = 'In October 1962, RF-101As of the 363rd TRW photographed Cuba at low level; the F-101A/Cs of the 81st TFW (Bentwaters) formed a nuclear strike force in England, and ADC F-101Bs (from 1959) then Canadian CF-101s served NORAD until 1984.', sources = 'https://en.wikipedia.org/wiki/McDonnell_F-101_Voodoo'
