UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'De 1960 à 1991, 916 F-104G servent la Bundeswehr : chasse (JG 71, JG 74), reconnaissance (AG 51, AG 52), attaque antinavire (MFG 1, MFG 2) et frappe, y compris nucléaire, dans le cadre de l’OTAN (JaboG 31, opérationnelle dès 1962, à JaboG 36) ; 269 sont perdus par accident.', role_en = 'From 1960 to 1991, 916 F-104Gs served the Bundeswehr: fighters (JG 71, JG 74), reconnaissance (AG 51, AG 52), anti-ship strike (MFG 1, MFG 2) and strike, including nuclear, within NATO (JaboG 31, operational from 1962, to JaboG 36); 269 were lost in crashes.', sources = 'https://de.wikipedia.org/wiki/Lockheed_F-104'
