UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Principal intercepteur tous temps de l’Air Defense Command de 1959 aux années 1980, armé de la roquette nucléaire Genie et guidé par le réseau SAGE ; il tient l’alerte aux États-Unis, en Alaska et en Islande, et intercepte un Tu-95 au large du cap Cod en 1982.', role_en = 'Air Defense Command’s main all-weather interceptor from 1959 into the 1980s, armed with the Genie nuclear rocket and guided by SAGE; it stood alert in the US, Alaska and Iceland, and intercepted a Tu-95 off Cape Cod in 1982.', sources = 'https://en.wikipedia.org/wiki/Convair_F-106_Delta_Dart'
