UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Les F-4EJ japonais tiennent l’alerte face à l’aviation soviétique : le 6 septembre 1976, ceux de Chitose ne repèrent pas le MiG-25 de Belenko avant Hakodate ; le 9 décembre 1987, ceux du 302e escadron tirent les tout premiers coups de semonce japonais sur un Tu-16 au-dessus d’Okinawa.', role_en = 'Japan’s F-4EJs stood alert against Soviet aircraft: on 6 September 1976 those from Chitose failed to find Belenko’s MiG-25 before Hakodate; on 9 December 1987 those of the 302nd Squadron fired the JASDF’s first-ever warning shots at a Tu-16 over Okinawa.', sources = 'https://en.wikipedia.org/wiki/1987_Okinawan_Tu-16_airspace_violation
