UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'En 1955, les F2H-2P du Corps des Marines survolent 27 fois les zones de rassemblement chinoises face à Taïwan ; de 1955 à 1962, les 39 F2H-3 de la Marine royale canadienne servent d’intercepteurs du NORAD depuis la terre ou le *Bonaventure*.', role_en = 'In 1955 Marine Corps F2H-2Ps flew 27 overflights of Chinese staging areas facing Taiwan; from 1955 to 1962 the Royal Canadian Navy’s 39 F2H-3s served as NORAD interceptors from shore bases or HMCS *Bonaventure*.', sources = 'https://en.wikipedia.org/wiki/McDonnell_F2H_Banshee'
