UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Intercepteur tous temps de première ligne de l’US Navy de 1956 à 1962, il survole le Liban et Quemoy pendant les crises de 1958, et ses canons sont remis en œuvre lors de la crise des missiles de Cuba.', role_en = 'The US Navy’s front-line all-weather interceptor from 1956 to 1962, it flew over Lebanon and Quemoy during the 1958 crises, and its cannon were reinstalled and armed for the Cuban Missile Crisis.', sources = 'https://en.wikipedia.org/wiki/McDonnell_F3H_Demon'
