UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Seul escadron de chasse de l’US Navy rattaché au NORAD, le VFAW-3, basé à North Island (San Diego), tient avec ses Skyray l’alerte de défense aérienne continentale contre les bombardiers soviétiques, une mission d’ordinaire réservée à l’Air Force.', role_en = 'The only US Navy fighter squadron assigned to NORAD, VFAW-3, based at North Island (San Diego), stood continental air defence alert with its Skyrays against Soviet bombers, a mission normally left to the Air Force.', sources = 'https://en.wikipedia.org/wiki/Douglas_F4D_Skyray'
