UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Le 18 novembre 1952, au large de Vladivostok, deux Panther de l’*Oriskany* livrent un long combat contre des MiG-15 de l’aviation navale soviétique, un affrontement direct américano-soviétique tenu secret pendant des décennies.', role_en = 'On 18 November 1952, off Vladivostok, two Panthers from USS *Oriskany* fought a long engagement with Soviet Naval Aviation MiG-15s, a direct US–Soviet clash kept secret for decades.', sources = 'https://en.wikipedia.org/wiki/Grumman_F9F_Panther'
