UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'La RAF Germany aligne ses Harrier à Wildenrath dès 1970, puis à Gütersloh en 1977, au plus près du front : dispersés loin des bases vulnérables sur des terrains camouflés, ils doivent frapper les colonnes blindées du pacte de Varsovie.', role_en = 'RAF Germany based its Harriers at Wildenrath from 1970 and moved them to Gütersloh in 1977, closer to the front: dispersed to camouflaged sites away from vulnerable airfields, they were to strike Warsaw Pact armoured columns.', sources = 'https://en.wikipedia.org/wiki/Hawker_Siddeley_Harrier'
