UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Après la capture du *Pueblo*, les A-12 de la CIA basés à Kadena survolent la Corée du Nord : le 26 janvier 1968, Jack Weeks localise le navire dans la baie de Changjahwan ; le dernier vol opérationnel du type a lieu au-dessus du Nord le 8 mai 1968.', role_en = 'After the Pueblo seizure, Kadena-based CIA A-12s overflew North Korea: on 26 January 1968 Jack Weeks located the ship in Changjahwan Bay, and the type''s last operational sortie was flown over the North on 8 May 1968.', sources = 'https://en.wikipedia.org/wiki/Lockheed_A-12'
