UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Lancés depuis des B-52 (programme *Senior Bowl*), quatre D-21B visent le site d''essais nucléaires chinois de Lop Nor de 1969 à 1971 : le premier, le 9 novembre 1969, file tout droit et s''écrase en URSS ; aucune photo n''est récupérée.', role_en = 'Launched from B-52s (Senior Bowl), four D-21Bs targeted China''s Lop Nur nuclear test site between 1969 and 1971: the first, on 9 November 1969, failed to turn and crashed in the Soviet Union; no photographs were ever recovered.', sources = 'https://en.wikipedia.org/wiki/Lockheed_D-21'
