UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Converti en avion d''écoute (P4M-1Q), il longe de nuit les côtes chinoises, nord-coréennes et soviétiques avec les escadrons VQ-1 et VQ-2 ; le 22 août 1956, l''un d''eux est abattu près de Shanghai par la chasse chinoise (16 morts), un autre est criblé par des MiG-17 nord-coréens le 16 juin 1959.', role_en = 'Converted for signals intelligence (P4M-1Q), it flew night missions along the Chinese, North Korean and Soviet coasts with VQ-1 and VQ-2; on 22 August 1956 one was shot down near Shanghai by Chinese fighters (16 killed), and another was badly damaged by North Korean MiG-17s on 16 June 1959.', sources = 'https://en.wikipedia.org/wiki/Martin_P4M_Mercator'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Martin P4M Mercator' AND w.name = 'Guerre froide'
