UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'En service depuis décembre 1981, le F-15J remplace en mars 1984 le F-104J au 203e escadron de Chitose, base qui fait face, par-delà le détroit de La Pérouse, à la base de chasse soviétique de Sakhaline.', role_en = 'In service from December 1981, the F-15J replaced the F-104J in March 1984 with the 203rd Squadron at Chitose, which faces the Soviet fighter base on Sakhalin across the La Pérouse Strait.', sources = 'https://en.wikipedia.org/wiki/Mitsubishi_F-15J'
