UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Chasseur de sous-marins des porte-avions américains à partir de 1974 ; en janvier 1987, un S-3A du VS-24 (USS *Nimitz*) relaie un P-3 en mer Tyrrhénienne et reprend brièvement le contact avec un sous-marin soviétique Charlie II venu de la flotte du Nord.', role_en = 'Submarine hunter aboard US carriers from 1974; in January 1987 a VS-24 S-3A from USS Nimitz relieved a P-3 in the Tyrrhenian Sea and briefly regained contact with a Soviet Charlie II submarine from the Northern Fleet.', sources = 'https://www.twz.com/30525/confessions-of-a-submarine-hunting-s-3-viking-crewman-during-the-twilight-of-the-cold-war
