UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'bloc-sovietique'), role = 'Le plus gros intercepteur de la PVO, mis en service vers 1964, garde l’immense Nord soviétique contre les bombardiers de l’OTAN comme le B-52 ; son seul fait d’armes connu est la destruction de ballons de reconnaissance de l’OTAN.', role_en = 'The PVO’s largest interceptor, in service from about 1964, guarded the vast Soviet north against NATO bombers such as the B-52; its only publicly known combat action was shooting down NATO reconnaissance balloons.', sources = 'https://en.wikipedia.org/wiki/Tupolev_Tu-128'
