UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'bloc-sovietique'), role = 'Dernier bombardier stratégique soviétique, nucléaire ou conventionnel, armé de missiles de croisière Kh-55 : il entre en service en avril 1987 au 184e régiment de bombardiers lourds de la Garde, à Priluki (Ukraine) ; l''Ukraine en hérite 19 à la dislocation de l''URSS.', role_en = 'The last Soviet strategic bomber, nuclear or conventional, armed with Kh-55 cruise missiles: it entered service in April 1987 with the 184th Guards Heavy Bomber Regiment at Pryluky, Ukraine; Ukraine inherited 19 of them when the USSR broke up.', sources = 'https://en.wikipedia.org/wiki/Tupolev_Tu-160'
