UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'occident'), role = 'Les chasseurs-bombardiers Venom forment en 1953 une escadre à Fassberg (14, 98 et 118 Squadrons), puis en 1954 une seconde à Celle (16, 94 et 145 Squadrons), en Allemagne de l’Ouest, au sein de la 2nd Tactical Air Force ; le Hunter les relève de 1955 à 1957.', role_en = 'Venom fighter-bombers formed a wing at Fassberg in 1953 (Nos 14, 98 and 118 Squadrons) and a second at Celle in 1954 (Nos 16, 94 and 145 Squadrons), in West Germany, within the 2nd Tactical Air Force; the Hunter replaced them from 1955 to 1957.', sources = 'https://en.wikipedia.org/wiki/De_Havilland_Venom'
  FROM airplanes a, wars w
