INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1948-06-26', 'day', 'Début du pont aérien de Berlin', 'The Berlin Airlift begins', 'Deux jours après le blocus soviétique de Berlin-Ouest, Américains et Britanniques ravitaillent la ville par avion. Jusqu''au 30 septembre 1949, 278 228 vols y apportent plus de 2,3 millions de tonnes de fret.', 'Two days after the Soviet blockade of West Berlin, the Americans and British began supplying the city by air. By 30 September 1949, 278,228 flights had brought in more than 2.3 million tons of cargo.', (SELECT id FROM airplanes WHERE name = 'Douglas C-54 Skymaster'), 'https://en.wikipedia.org/wiki/Berlin_Blockade' FROM wars w WHERE w.name = 'Guerre froide'
