       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1951-10-18', 'day', 'Première bombe atomique soviétique larguée d''avion', 'First Soviet atomic bomb dropped from an aircraft', 'Un Tu-4A, copie soviétique du B-29, largue la bombe RDS-3 : l''URSS dispose désormais d''un vecteur aérien pour son arme atomique.', 'A Tu-4A, the Soviet copy of the B-29, dropped the RDS-3 bomb: the USSR now had an aircraft able to deliver its atomic weapon.', (SELECT id FROM airplanes WHERE name = 'Tupolev Tu-4'), 'https://en.wikipedia.org/wiki/RDS-3' FROM wars w WHERE w.name = 'Guerre froide'
