INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1953-03-12', 'day', 'Un Lincoln de la RAF abattu au-dessus de l''Allemagne', 'RAF Lincoln shot down over Germany', 'Le Lincoln RF531 de la Central Gunnery School, en route vers Berlin, est abattu par des MiG-15 soviétiques au nord-est de Lunebourg. Ses sept hommes d''équipage sont tués.', 'Lincoln RF531 of the Central Gunnery School, flying towards Berlin, was shot down by Soviet MiG-15s north-east of Lüneburg. All seven crew were killed.', (SELECT id FROM airplanes WHERE name = 'Avro Lincoln'), 'https://en.wikipedia.org/wiki/Avro_Lincoln' FROM wars w WHERE w.name = 'Guerre froide'
