INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1955-07-01', 'month', 'Touchino et le « bomber gap »', 'Tushino and the "bomber gap"', 'Au défilé aérien de Touchino, les mêmes bombardiers M-4 repassent devant la tribune et donnent l''illusion d''une flotte bien plus nombreuse. Washington croit à un retard sur l''URSS et accélère la production du B-52.', 'At the Tushino air display, the same M-4 bombers flew past the stand again, creating the illusion of a much larger fleet. Washington believed it was falling behind the USSR and speeded up B-52 production.', (SELECT id FROM airplanes WHERE name = 'Myasishchev M-4'), 'https://en.wikipedia.org/wiki/Bomber_gap' FROM wars w WHERE w.name = 'Guerre froide'
