INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1960-05-01', 'day', 'L''U-2 de Powers abattu au-dessus de l''Oural', 'Powers''s U-2 shot down over the Urals', 'Parti de Peshawar pour rejoindre Bodø, l''U-2 de la CIA piloté par Francis Gary Powers est abattu par un missile S-75 près de Sverdlovsk. L''affaire fait échouer le sommet de Paris.', 'Flying from Peshawar towards Bodø, the CIA U-2 piloted by Francis Gary Powers was shot down by an S-75 missile near Sverdlovsk. The affair wrecked the Paris summit.', (SELECT id FROM airplanes WHERE name = 'U-2 Dragon Lady'), 'https://en.wikipedia.org/wiki/1960_U-2_incident' FROM wars w WHERE w.name = 'Guerre froide'
