INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1962-11-20', 'day', 'Fin de la crise de Cuba : les Il-28 repartent', 'End of the Cuban crisis: the Il-28s go home', 'Après le retrait des missiles, Washington exige aussi celui des bombardiers Il-28 livrés à Cuba. Moscou s''y engage et le blocus naval est levé le 20 novembre ; les avions sont rembarqués début décembre.', 'After the missiles were withdrawn, Washington also demanded the removal of the Il-28 bombers delivered to Cuba. Moscow agreed and the naval quarantine was lifted on 20 November; the aircraft were shipped out in early December.', (SELECT id FROM airplanes WHERE name = 'Il-28'), 'https://en.wikipedia.org/wiki/Cuban_Missile_Crisis' FROM wars w WHERE w.name = 'Guerre froide'
