INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1966-01-17', 'day', 'Accident de Palomares', 'The Palomares accident', 'Au-dessus de l''Espagne, un B-52G de *Chrome Dome* heurte le KC-135 qui le ravitaille. Sept aviateurs meurent ; deux des quatre bombes H dispersent du plutonium au sol, une autre n''est repêchée en mer que le 7 avril.', 'Over Spain, a *Chrome Dome* B-52G collided with the KC-135 refuelling it. Seven airmen died; two of the four H-bombs scattered plutonium on the ground, and another was only recovered from the sea on 7 April.', (SELECT id FROM airplanes WHERE name = 'KC-135 Stratotanker'), 'https://en.wikipedia.org/wiki/1966_Palomares_B-52_crash' FROM wars w WHERE w.name = 'Guerre froide'
