INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1966-04-06', 'day', 'Un Yak-28 tombe dans Berlin-Ouest', 'A Yak-28 falls into West Berlin', 'En perdition, un Yak-28 soviétique s''abîme dans le lac Stößensee, à Berlin-Ouest ; ses deux pilotes périssent en évitant les habitations. Des plongeurs britanniques récupèrent l''épave, examinée par l''OTAN avant d''être rendue.', 'A stricken Soviet Yak-28 crashed into Lake Stößensee in West Berlin; its two pilots died steering clear of housing. British divers recovered the wreck, which NATO examined before handing it back.', (SELECT id FROM airplanes WHERE name = 'Yak-28'), 'https://en.wikipedia.org/wiki/Yakovlev_Yak-28' FROM wars w WHERE w.name = 'Guerre froide'
