INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1976-09-06', 'day', 'Belenko passe à l''Ouest en MiG-25', 'Belenko defects in a MiG-25', 'Le lieutenant Viktor Belenko quitte Tchougouïevka et pose son MiG-25 à Hakodate, au Japon. L''appareil est démonté et examiné, puis rendu à l''URSS en trente caisses.', 'Lieutenant Viktor Belenko left Chuguyevka and landed his MiG-25 at Hakodate, Japan. The aircraft was dismantled and examined, then returned to the USSR in thirty crates.', (SELECT id FROM airplanes WHERE name = 'MiG-25'), 'https://en.wikipedia.org/wiki/Viktor_Belenko' FROM wars w WHERE w.name = 'Guerre froide'
