INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1983-11-07', 'day', 'Able Archer 83', 'Able Archer 83', 'Pendant cinq jours, l''exercice nucléaire de l''OTAN fait craindre à Moscou une attaque surprise : des avions à capacité nucléaire sont mis en alerte en RDA et en Pologne. La gravité de l''épisode reste débattue.', 'For five days NATO''s nuclear exercise led Moscow to fear a surprise attack: nuclear-capable aircraft were put on alert in East Germany and Poland. How dangerous the episode was is still debated.', NULL::int, 'https://en.wikipedia.org/wiki/Able_Archer_83' FROM wars w WHERE w.name = 'Guerre froide'
