INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1991-09-27', 'day', 'Fin de l''alerte nucléaire des bombardiers', 'Bombers stand down from nuclear alert', 'Le président George H. W. Bush retire les B-52 et les ravitailleurs du Strategic Air Command de l''alerte nucléaire permanente qu''ils tenaient depuis 1957. L''URSS disparaît trois mois plus tard.', 'President George H. W. Bush took Strategic Air Command''s B-52s and tankers off the continuous nuclear alert they had stood since 1957. The USSR ceased to exist three months later.', (SELECT id FROM airplanes WHERE name = 'B-52 Stratofortress'), 'https://en.wikipedia.org/wiki/Strategic_Air_Command' FROM wars w WHERE w.name = 'Guerre froide'
