INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'inde', 1, 'Inde', 'India', 'Inde (Indian Air Force, aéronavale indienne)', 'India (Indian Air Force, Indian Naval Air Arm)' FROM wars w WHERE w.name = 'Guerre indo-pakistanaise de 1965'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'pakistan', 2, 'Pakistan', 'Pakistan', 'Pakistan (Pakistan Air Force)', 'Pakistan (Pakistan Air Force)' FROM wars w WHERE w.name = 'Guerre indo-pakistanaise de 1965'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre indo-pakistanaise de 1965' AND s.side_key NOT IN ('inde', 'pakistan');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'inde'), role = 'Les Alizé de l''aéronavale indienne patrouillent les côtes ouest et sud, recueillent du renseignement électronique et survolent le Pendjab pour aider l''IAF à repérer les radars ; un détachement suit la flotte pakistanaise lors de l''opération *Dwarka*.', role_en = 'Indian Navy Alizés patrolled the western and southern coasts, gathered electronic intelligence and flew over Punjab to help the IAF locate radar sites; a detachment shadowed the Pakistani task force during Operation *Dwarka*.', sources = 'https://en.wikipedia.org/wiki/Breguet_Alizé'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Breguet Alizé' AND w.name = 'Guerre indo-pakistanaise de 1965'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'inde'), 'Les Alizé de l''aéronavale indienne patrouillent les côtes ouest et sud, recueillent du renseignement électronique et survolent le Pendjab pour aider l''IAF à repérer les radars ; un détachement suit la flotte pakistanaise lors de l''opération *Dwarka*.', 'Indian Navy Alizés patrolled the western and southern coasts, gathered electronic intelligence and flew over Punjab to help the IAF locate radar sites; a detachment shadowed the Pakistani task force during Operation *Dwarka*.', 'https://en.wikipedia.org/wiki/Breguet_Alizé');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'inde'), role = 'Seul avion indien employé pour les frappes de nuit en profondeur, le Canberra bombarde de nuit Sargodha, Chaklala et Peshawar (13-14 septembre), frappe Chittagong le 7 et détruit en plein jour le radar de Badin le 21 ; quatre sont détruits au sol à Kalaikunda et un est abattu par un F-104.', role_en = 'India''s only aircraft used for deep night strikes, the Canberra bombed Sargodha, Chaklala and Peshawar by night (13-14 September), hit Chittagong on the 7th and knocked out the Badin radar in daylight on the 21st; four were destroyed on the ground at Kalaikunda and one was shot down by an F-104.', sources = 'https://en.wikipedia.org/wiki/English_Electric_Canberra
