UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'pakistan'), role = 'L''unique escadron de F-104 de la PAF intercepte de jour comme de nuit et reconnaît (204 sorties de jour, 42 de nuit) ; il abat le Mystère de Devaiah au-dessus de Sargodha, un Canberra le 21 septembre, et se voit crédité du Gnat posé à Pasrur.', role_en = 'The PAF''s sole F-104 squadron flew day and night interception and reconnaissance (204 day sorties, 42 night); it shot down Devaiah''s Mystère over Sargodha and a Canberra on 21 September, and was credited with the Gnat that landed at Pasrur.', sources = 'https://en.wikipedia.org/wiki/Lockheed_F-104_Starfighter
