UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'inde'), role = 'Retirés du front de l''ouest après le 1er septembre, les Ouragan (« Toofani ») restent en ligne à l''est : quatre appareils du 4e escadron mitraillent un convoi près de Lalmonirhat, au Pakistan oriental, et cinq du 47e escadron assurent la défense de Tezpur.', role_en = 'Pulled from the western front after 1 September, the Ouragans ("Toofani") stayed in service in the east: four No. 4 Squadron aircraft strafed a convoy near Lalmonirhat in East Pakistan, and five No. 47 Squadron jets flew air defence at Tezpur.', sources = 'https://www.bharat-rakshak.com/IAF/history/1965war/book/chapter05-2/
