UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'inde'), role = 'Le 1er septembre, douze Vampire du 45e escadron attaquent les chars de *Grand Slam* à Chhamb ; quatre sont perdus et le type quitte le front. À l''est, ceux du 24e escadron mitraillent Jessore le 7, puis quatre sont détruits au sol à Kalaikunda.', role_en = 'On 1 September twelve No. 45 Squadron Vampires attacked the *Grand Slam* armour at Chhamb; four were lost and the type left the front line. In the east, No. 24 Squadron''s Vampires strafed Jessore on the 7th, and four were then destroyed on the ground at Kalaikunda.', sources = 'https://en.wikipedia.org/wiki/Indo-Pakistani_air_war_of_1965
