INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-08-05', 'day', 'Opération *Gibraltar*', 'Operation *Gibraltar*', 'Des soldats pakistanais déguisés en civils s''infiltrent au Cachemire indien pour y provoquer un soulèvement, qui n''aura pas lieu.', 'Pakistani soldiers disguised as civilians slip into Indian-held Kashmir to spark an uprising that never comes.', NULL::int, 'https://en.wikipedia.org/wiki/Indo-Pakistani_war_of_1965' FROM wars w WHERE w.name = 'Guerre indo-pakistanaise de 1965'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-09-01', 'day', '*Grand Slam* et les Vampire de Chhamb', '*Grand Slam* and the Chhamb Vampires', 'Contre l''offensive blindée pakistanaise, l''IAF lance douze Vampire et quatorze Mystère ; deux Sabre interceptent et quatre Vampire sont perdus, ce qui conduit à retirer le type du front.', 'Against the Pakistani armoured offensive, the IAF sends twelve Vampires and fourteen Mystères; two Sabres intercept and four Vampires are lost, and the type is pulled from the front.', (SELECT id FROM airplanes WHERE name = 'de Havilland Vampire'), 'https://en.wikipedia.org/wiki/Indo-Pakistani_air_war_of_1965' FROM wars w WHERE w.name = 'Guerre indo-pakistanaise de 1965'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-09-03', 'day', 'Premier duel Gnat contre Sabre', 'First Gnat versus Sabre duel', 'Trevor Keelor revendique la première victoire aérienne indienne de la guerre, contestée par le Pakistan ; un autre Gnat, posé par erreur à Pasrur, est capturé.', 'Trevor Keelor claims India''s first air victory of the war, disputed by Pakistan; another Gnat, landed by mistake at Pasrur, is captured.', (SELECT id FROM airplanes WHERE name = 'Folland Gnat'), 'https://en.wikipedia.org/wiki/Indo-Pakistani_air_war_of_1965' FROM wars w WHERE w.name = 'Guerre indo-pakistanaise de 1965'
