INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-09-06', 'day', 'Frappes pakistanaises sur Pathankot, Adampur et Halwara', 'Pakistani strikes on Pathankot, Adampur and Halwara', 'Au soir de l''offensive indienne vers Lahore, les Sabre détruisent une dizaine d''avions au sol à Pathankot ; les raids sur Adampur et Halwara échouent, et Rafiqui est tué au-dessus de Halwara.', 'On the evening of the Indian push towards Lahore, Sabres destroy about ten aircraft on the ground at Pathankot; the Adampur and Halwara raids fail, and Rafiqui is killed over Halwara.', (SELECT id FROM airplanes WHERE name = 'F-86 Sabre'), 'https://en.wikipedia.org/wiki/Indo-Pakistani_air_war_of_1965' FROM wars w WHERE w.name = 'Guerre indo-pakistanaise de 1965'
