   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-09-07', 'day', 'Raids indiens sur Sargodha', 'Indian raids on Sargodha', 'L''IAF lance 33 sorties de Mystère et de Hunter contre la principale base de la PAF ; elle y perd deux Mystère, dont celui de Devaiah abattu par un F-104, et trois Hunter, puis renonce aux raids de jour.', 'The IAF flies 33 Mystère and Hunter sorties against the PAF''s main base; it loses two Mystères, including Devaiah''s, downed by an F-104, and three Hunters, and gives up daylight raids.', (SELECT id FROM airplanes WHERE name = 'Mystère IV'), 'https://en.wikipedia.org/wiki/Indo-Pakistani_air_war_of_1965' FROM wars w WHERE w.name = 'Guerre indo-pakistanaise de 1965'
