       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-09-07', 'day', 'Les revendications de M. M. Alam', 'M. M. Alam''s claims', 'Aux commandes de son Sabre, Alam revendique cinq Hunter en moins d''une minute au-dessus de Sargodha ; plusieurs historiens n''en retiennent que deux.', 'Flying his Sabre, Alam claims five Hunters in under a minute over Sargodha; several historians accept only two.', (SELECT id FROM airplanes WHERE name = 'F-86 Sabre'), 'https://en.wikipedia.org/wiki/Muhammad_Mahmood_Alam' FROM wars w WHERE w.name = 'Guerre indo-pakistanaise de 1965'
