INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-09-07', 'day', 'Kalaikunda, à l''est', 'Kalaikunda, in the east', 'Des Sabre venus du Pakistan oriental détruisent au sol quatre Canberra et quatre Vampire ; au second raid, le Hunter d''Alfred Cooke touche trois Sabre.', 'Sabres from East Pakistan destroy four Canberras and four Vampires on the ground; during the second raid, Alfred Cooke''s Hunter hits three Sabres.', (SELECT id FROM airplanes WHERE name = 'Hawker Hunter'), 'https://www.bharat-rakshak.com/IAF/history/1965war/book/chapter05-2/' FROM wars w WHERE w.name = 'Guerre indo-pakistanaise de 1965'
