INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-09-20', 'day', 'Résolution 211 de l''ONU', 'UN Resolution 211', 'Le Conseil de sécurité exige un cessez-le-feu sans condition dans les 48 heures ; l''Inde l''accepte aussitôt.', 'The Security Council demands an unconditional ceasefire within 48 hours; India accepts at once.', NULL::int, 'https://en.wikipedia.org/wiki/Indo-Pakistani_war_of_1965' FROM wars w WHERE w.name = 'Guerre indo-pakistanaise de 1965'
