INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-09-21', 'day', 'Raid de jour sur le radar de Badin', 'Daylight raid on the Badin radar', 'Six Canberra du 16e escadron partis d''Agra mettent hors service le radar de Badin ; le même jour, un F-104 abat un Canberra qui rentre de Sargodha.', 'Six No. 16 Squadron Canberras from Agra knock out the Badin radar; the same day, an F-104 shoots down a Canberra returning from Sargodha.', (SELECT id FROM airplanes WHERE name = 'English Electric Canberra'), 'https://en.wikipedia.org/wiki/Indo-Pakistani_air_war_of_1965' FROM wars w WHERE w.name = 'Guerre indo-pakistanaise de 1965'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
