INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1965-09-22', 'day', 'Bombardement d''Amritsar', 'Bombing of Amritsar', 'Selon l''IDSA, un B-57 escorté de Sabre frappe un faubourg d''Amritsar : 55 civils sont tués.', 'According to the IDSA, a Sabre-escorted B-57 hits a suburb of Amritsar, killing 55 civilians.', (SELECT id FROM airplanes WHERE name = 'Martin B-57 Canberra'), 'https://www.idsa.in/system/files/jds/jds_9_3_2015_AirPowerinthe1965IndoPakistanWar.pdf' FROM wars w WHERE w.name = 'Guerre indo-pakistanaise de 1965'
