UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'inde'), role = 'À l''est, les MiG-21FL des 28e et 4e escadrons détruisent la piste de Tejgaon le 6 décembre puis frappent la résidence du gouverneur à Dacca le 14 ; à l''ouest, ils abattent le chef du 9e escadron de F-104 le 12 et un F-104 jordanien le 17.', role_en = 'In the east, MiG-21FLs of Nos. 28 and 4 Squadrons wrecked the Tejgaon runway on 6 December and struck Government House in Dacca on the 14th; in the west they shot down the commander of the F-104 squadron on the 12th and a Jordanian F-104 on the 17th.', sources = 'https://en.wikipedia.org/wiki/Mikoyan-Gurevich_MiG-21
