INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1971-03-25', 'day', 'Opération *Searchlight*', 'Operation *Searchlight*', 'L''armée pakistanaise écrase le mouvement bengali à Dacca et arrête Sheikh Mujibur Rahman ; l''indépendance du Bangladesh est proclamée et l''exode vers l''Inde commence.', 'The Pakistani army crushes the Bengali movement in Dacca and arrests Sheikh Mujibur Rahman; Bangladesh''s independence is declared and the exodus to India begins.', NULL::int, 'https://en.wikipedia.org/wiki/Indo-Pakistani_war_of_1971' FROM wars w WHERE w.name = 'Guerre Indo-Pakistanaise de 1971'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1971-09-28', 'day', 'Création de la Kilo Flight', 'Kilo Flight is formed', 'À Dimapur, des pilotes bengalis passés à la dissidence forment la première unité combattante de l''armée de l''air du Bangladesh, avec un Otter, une Alouette III et un DC-3.', 'At Dimapur, defecting Bengali pilots form the first fighting unit of the Bangladesh Air Force, with an Otter, an Alouette III and a DC-3.', NULL::int, 'https://en.wikipedia.org/wiki/Kilo_Flight' FROM wars w WHERE w.name = 'Guerre Indo-Pakistanaise de 1971'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1971-11-22', 'day', 'Bataille de Boyra', 'Battle of Boyra', 'Avant toute déclaration de guerre, quatre Gnat du 22e escadron abattent deux Sabre pakistanais et en endommagent un troisième ; les deux pilotes éjectés sont capturés.', 'Before any declaration of war, four No. 22 Squadron Gnats shoot down two Pakistani Sabres and damage a third; both pilots eject and are captured.', (SELECT id FROM airplanes WHERE name = 'Folland Gnat'), 'https://en.wikipedia.org/wiki/Battle_of_Boyra' FROM wars w WHERE w.name = 'Guerre Indo-Pakistanaise de 1971'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1971-12-03', 'day', 'Opération *Chengiz Khan*', 'Operation *Chengiz Khan*', 'En fin d''après-midi, la PAF frappe par surprise les aérodromes du nord-ouest de l''Inde, puis les bombarde de nuit ; les dégâts sont vite réparés et l''Inde entre en guerre.', 'In the late afternoon the PAF launches surprise strikes on airfields in north-western India, then bombs them through the night; the damage is quickly repaired and India goes to war.', NULL::int, 'https://en.wikipedia.org/wiki/Operation_Chengiz_Khan' FROM wars w WHERE w.name = 'Guerre Indo-Pakistanaise de 1971'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
