INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1971-12-04', 'day', 'Premières frappes du *Vikrant*', '*Vikrant*''s first strikes', 'Deux vagues de huit Sea Hawk attaquent le port de Chittagong et celui de Cox''s Bazar ; deux canonnières sont touchées et six navires marchands immobilisés.', 'Two waves of eight Sea Hawks attack the harbours of Chittagong and Cox''s Bazar; two gunboats are hit and six merchant ships disabled.', (SELECT id FROM airplanes WHERE name = 'Hawker Sea Hawk'), 'https://en.wikipedia.org/wiki/INS_Vikrant_(1961)' FROM wars w WHERE w.name = 'Guerre Indo-Pakistanaise de 1971'
