INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1971-12-04', 'day', 'Premier raid de la Kilo Flight', 'Kilo Flight''s first raid', 'L''Otter frappe les réservoirs de l''aéroport de Chittagong et l''Alouette III le dépôt de Godnail, à Narayanganj : premières attaques aériennes bangladaises (le 3 décembre selon d''autres récits).', 'The Otter hits fuel tanks at Chittagong airport and the Alouette III the Godnail depot at Narayanganj: the first Bangladeshi air attacks (dated 3 December in other accounts).', NULL::int, 'https://en.wikipedia.org/wiki/Kilo_Flight' FROM wars w WHERE w.name = 'Guerre Indo-Pakistanaise de 1971'
