INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1971-12-05', 'day', 'Longewala', 'Longewala', 'Au matin, des Hunter et des Marut de Jaisalmer, guidés par un observateur en Krishak, attaquent la colonne blindée pakistanaise qui assiège le poste indien et la mettent en déroute.', 'In the morning, Hunters and Maruts from Jaisalmer, guided by a spotter in a Krishak, attack the Pakistani armoured column besieging the Indian post and rout it.', (SELECT id FROM airplanes WHERE name = 'Hawker Hunter'), 'https://en.wikipedia.org/wiki/Battle_of_Longewala' FROM wars w WHERE w.name = 'Guerre Indo-Pakistanaise de 1971'
