INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1971-12-06', 'day', 'La piste de Tejgaon détruite', 'Tejgaon runway knocked out', 'Les MiG-21 des 28e et 4e escadrons cratèrent la piste de Dacca-Tejgaon : les Sabre pakistanais ne peuvent plus décoller et l''IAF tient le ciel du Pakistan oriental.', 'MiG-21s of Nos. 28 and 4 Squadrons crater the runway at Dacca-Tejgaon: the Pakistani Sabres can no longer take off and the IAF controls the skies over East Pakistan.', (SELECT id FROM airplanes WHERE name = 'MiG-21'), 'https://en.wikipedia.org/wiki/Indo-Pakistani_air_war_of_1971' FROM wars w WHERE w.name = 'Guerre Indo-Pakistanaise de 1971'
