INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1971-12-10', 'day', 'Un Alizé abattu', 'An Alizé shot down', 'Le F-104 du Wing Commander Arif Iqbal abat un Breguet Alizé de la marine indienne ; ses trois membres d''équipage sont tués.', 'Wing Commander Arif Iqbal''s F-104 shoots down an Indian Navy Breguet Alizé, killing its three crew.', (SELECT id FROM airplanes WHERE name = 'Breguet Alizé'), 'https://en.wikipedia.org/wiki/List_of_aerial_victories_during_the_Indo-Pakistani_war_of_1971' FROM wars w WHERE w.name = 'Guerre Indo-Pakistanaise de 1971'
