INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1971-12-11', 'day', 'Parachutage de Tangail', 'Tangail airdrop', 'Des An-12, des C-119 et des Dakota larguent environ 750 hommes du 2e bataillon parachutiste, qui s''emparent du pont de Poongli et coupent la route de Dacca à la 93e brigade pakistanaise.', 'An-12s, C-119s and Dakotas drop some 750 men of the 2nd Parachute Battalion, who seize the Poongli bridge and block the Pakistani 93rd Brigade''s road to Dacca.', (SELECT id FROM airplanes WHERE name = 'Antonov An-12'), 'https://en.wikipedia.org/wiki/Tangail_Airdrop' FROM wars w WHERE w.name = 'Guerre Indo-Pakistanaise de 1971'
