INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1971-12-14', 'day', 'Frappe sur la résidence du gouverneur', 'Strike on Government House', 'Quatre MiG-21 du 28e escadron tirent leurs roquettes de 57 mm sur la résidence du gouverneur à Dacca pendant une réunion ; le gouverneur démissionne peu après.', 'Four No. 28 Squadron MiG-21s fire 57 mm rockets into Government House in Dacca during a meeting; the governor resigns shortly afterwards.', (SELECT id FROM airplanes WHERE name = 'MiG-21'), 'https://en.wikipedia.org/wiki/Indo-Pakistani_air_war_of_1971' FROM wars w WHERE w.name = 'Guerre Indo-Pakistanaise de 1971'
