INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1971-12-14', 'day', 'Sekhon tombe au-dessus de Srinagar', 'Sekhon falls over Srinagar', 'Seul face aux Sabre du 26e escadron venus attaquer Srinagar, le pilote de Gnat Nirmal Jit Singh Sekhon est abattu ; il reçoit à titre posthume le Param Vir Chakra, seul aviateur indien ainsi décoré.', 'Alone against No. 26 Squadron Sabres attacking Srinagar, Gnat pilot Nirmal Jit Singh Sekhon is shot down; he is posthumously awarded the Param Vir Chakra, the only Indian airman so honoured.', (SELECT id FROM airplanes WHERE name = 'Folland Gnat'), 'https://en.wikipedia.org/wiki/Nirmal_Jit_Singh_Sekhon' FROM wars w WHERE w.name = 'Guerre Indo-Pakistanaise de 1971'
