SELECT w.id, DATE '1971-12-16', 'day', 'Reddition de Dacca', 'Surrender at Dacca', 'Le général Niazi signe la capitulation des forces pakistanaises de l''Est devant le général Aurora ; environ 93 000 hommes sont faits prisonniers et le Bangladesh devient indépendant.', 'General Niazi signs the surrender of Pakistan''s Eastern forces before General Aurora; some 93,000 men are taken prisoner and Bangladesh becomes independent.', NULL::int, 'https://en.wikipedia.org/wiki/Indo-Pakistani_war_of_1971' FROM wars w WHERE w.name = 'Guerre Indo-Pakistanaise de 1971'
