INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1980-09-22', 'day', 'Frappes irakiennes d’ouverture', 'Iraqi opening air strikes', 'Selon Cooper et Bishop, 192 avions irakiens attaquent une dizaine de bases iraniennes ; cinq Tu-22 bombardent Téhéran. Les hangars durcis protègent l’essentiel de l’aviation iranienne.', 'According to Cooper and Bishop, 192 Iraqi aircraft attack some ten Iranian air bases; five Tu-22s bomb Tehran. Hardened shelters protect most of the Iranian air force.', (SELECT id FROM airplanes WHERE name = 'Tu-22'), 'https://en.wikipedia.org/wiki/22_September_1980_Iraqi_airstrike_on_Iran' FROM wars w WHERE w.name = 'Guerre Iran-Irak'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1980-09-23', 'day', 'Opération *Kaman 99*', 'Operation *Kaman 99*', 'Riposte iranienne : des F-4 et des F-5 frappent les bases aériennes et les installations pétrolières irakiennes, de Mossoul à Bassora, pendant que les F-14 couvrent l’Iran.', 'Iran strikes back: F-4s and F-5s hit Iraqi air bases and oil installations from Mosul to Basra, while F-14s cover Iranian airspace.', (SELECT id FROM airplanes WHERE name = 'F-4 Phantom II'), 'https://en.wikipedia.org/wiki/Operation_Kaman_99' FROM wars w WHERE w.name = 'Guerre Iran-Irak'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1980-09-30', 'day', 'Raid iranien sur Osirak', 'Iranian raid on Osirak', 'Quatre F-4 iraniens visent le réacteur nucléaire irakien d’Osirak (opération *Scorch Sword*) : première attaque contre un réacteur, sans dégâts durables.', 'Four Iranian F-4s attack Iraq’s Osirak nuclear reactor (Operation *Scorch Sword*): the first attack on a reactor, with no lasting damage.', (SELECT id FROM airplanes WHERE name = 'F-4 Phantom II'), 'https://en.wikipedia.org/wiki/Operation_Scorch_Sword' FROM wars w WHERE w.name = 'Guerre Iran-Irak'
