INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1981-04-04', 'day', 'Raid sur H-3', 'Raid on H-3', 'Huit F-4 ravitaillés en vol frappent la base de H-3, à l’ouest de l’Irak. L’Iran revendique au moins 48 avions détruits ; l’Irak n’admet qu’un MiG-21 endommagé.', 'Eight air-refuelled F-4s strike H-3 air base in western Iraq. Iran claims at least 48 aircraft destroyed; Iraq admits only one MiG-21 damaged.', (SELECT id FROM airplanes WHERE name = 'F-4 Phantom II'), 'https://en.wikipedia.org/wiki/H-3_airstrike' FROM wars w WHERE w.name = 'Guerre Iran-Irak'
