INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'israel', 1, 'Israël', 'Israel', 'Israël (armée de l''air, Mossad)', 'Israel (Air Force, Mossad)' FROM wars w WHERE w.name = 'Guerre Iran-Israël'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'etats-unis', 2, 'États-Unis', 'United States', 'États-Unis (US Air Force, US Navy), entrés en guerre le 22 juin ; aide à la défense antimissile d''Israël, avec le concours de la Jordanie', 'United States (US Air Force, US Navy), in the war from 22 June; help with Israel''s missile defence, with assistance from Jordan' FROM wars w WHERE w.name = 'Guerre Iran-Israël'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'iran', 3, 'Iran', 'Iran', 'Iran (armée régulière, Gardiens de la révolution) ; tirs ponctuels des Houthis du Yémen sur Israël', 'Iran (regular armed forces, Revolutionary Guards); occasional launches at Israel by Yemen''s Houthis' FROM wars w WHERE w.name = 'Guerre Iran-Israël'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre Iran-Israël' AND s.side_key NOT IN ('israel', 'etats-unis', 'iran');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis'), role = 'Opération *Midnight Hammer*, 22 juin : sept B-2 partis de Whiteman (Missouri) volent environ 37 heures aller-retour ; six larguent douze GBU-57 sur Fordo, le septième deux sur Natanz, premier emploi au combat de cette bombe.', role_en = 'Operation *Midnight Hammer*, 22 June: seven B-2s from Whiteman, Missouri, flew a round trip of about 37 hours; six dropped twelve GBU-57s on Fordow and the seventh two on Natanz, the bomb''s first combat use.', sources = 'https://en.wikipedia.org/wiki/2025_United_States_strikes_on_Iranian_nuclear_sites
https://www.airandspaceforces.com/us-strikes-iranian-nuclear-facilities-b-2-bombers-cruise-missiles
https://en.wikipedia.org/wiki/Northrop_B-2_Spirit'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'B-2 Spirit' AND w.name = 'Guerre Iran-Israël'
