INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'israel', 1, 'Israël', 'Israel', 'Israël (Tsahal et son armée de l''air)', 'Israel (the IDF and the Israeli Air Force)' FROM wars w WHERE w.name = 'Guerre Israël-Hamas'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'hamas-allies', 2, 'Hamas et ses alliés', 'Hamas and its allies', 'Hamas et factions armées de Gaza ; sur les fronts voisins, Hezbollah libanais et Houthis du Yémen', 'Hamas and the armed factions of Gaza; on the neighbouring fronts, Lebanon''s Hezbollah and Yemen''s Houthis' FROM wars w WHERE w.name = 'Guerre Israël-Hamas'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
