INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'russie', 1, 'Russie et séparatistes', 'Russia and separatists', 'Russie (forces armées, aviation, flotte de la mer Noire) ; forces séparatistes d’Ossétie du Sud et d’Abkhazie', 'Russia (armed forces, air force, Black Sea Fleet); South Ossetian and Abkhaz separatist forces' FROM wars w WHERE w.name = 'Guerre russo-géorgienne'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'georgie', 2, 'Géorgie', 'Georgia', 'Forces armées géorgiennes (armée de terre, armée de l’air et défense antiaérienne, marine) et forces du ministère de l’Intérieur', 'Georgian armed forces (army, air force and air defence, navy) and Interior Ministry forces' FROM wars w WHERE w.name = 'Guerre russo-géorgienne'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerre russo-géorgienne' AND s.side_key NOT IN ('russie', 'georgie');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'russie'), role = 'Les Su-24M frappent les aérodromes géorgiens (trois An-2 détruits à Marneuli le 8 août) et l’artillerie ; des Su-24MR photographient probablement la gorge de Kodori. Deux Su-24M sont perdus : l’un par un missile portable géorgien près de Chindisi le 9 août, l’autre par un tir ami le 11.', role_en = 'Su-24Ms struck Georgian airfields (three An-2s destroyed at Marneuli on 8 August) and artillery; Su-24MRs probably photographed the Kodori Gorge. Two Su-24Ms were lost: one to a Georgian shoulder-launched missile near Shindisi on 9 August, the other to friendly fire on the 11th.', sources = 'https://www.cast.ru/files/The_Tanks_of_August_sm_eng.pdf
