INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2008-04-20', 'day', 'Un drone géorgien abattu au-dessus de l’Abkhazie', 'Georgian drone shot down over Abkhazia', 'Un drone de reconnaissance géorgien est abattu par un avion de combat russe. Moscou nie, et l’Abkhazie revendique le tir d’un de ses L-39.', 'A Georgian reconnaissance drone was shot down by a Russian warplane. Moscow denied it, and Abkhazia claimed one of its L-39s had fired the shot.', NULL::int, 'https://en.wikipedia.org/wiki/Russo-Georgian_War' FROM wars w WHERE w.name = 'Guerre russo-géorgienne'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2008-08-08', 'day', 'L’unique raid des Su-25 géorgiens', 'The Georgian Su-25s'' only raid', 'Vers 7 h, quatre Su-25 géorgiens bombardent une colonne russe et le pont de Gufti, entre Djava et Tskhinvali, sans coup au but. Ils ne revoleront plus de la guerre.', 'At about 07:00, four Georgian Su-25s bombed a Russian column and the Gufti bridge between Dzhava and Tskhinvali, scoring no direct hit. They did not fly again for the rest of the war.', (SELECT id FROM airplanes WHERE name = 'Su-25'), 'https://www.cast.ru/files/The_Tanks_of_August_sm_eng.pdf' FROM wars w WHERE w.name = 'Guerre russo-géorgienne'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2008-08-08', 'day', 'Raids sur la base aérienne de Marneuli', 'Raids on Marneuli air base', 'À 16 h 30, deux Su-24M frappent Marneuli, principale base de l’armée de l’air géorgienne, et détruisent trois An-2. La base est attaquée deux autres fois dans la soirée.', 'At 16:30 two Su-24Ms struck Marneuli, the Georgian Air Force''s main base, destroying three An-2s. The base was attacked twice more that evening.', (SELECT id FROM airplanes WHERE name = 'Su-24'), 'https://www.cast.ru/files/The_Tanks_of_August_sm_eng.pdf' FROM wars w WHERE w.name = 'Guerre russo-géorgienne'
