INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2008-08-08', 'day', 'Premier avion russe perdu, par un tir ami', 'First Russian loss, to friendly fire', 'Vers 18 h, un Su-25 du 368e régiment d’attaque est abattu par des missiles portables tirés par des soldats russes qui le prennent pour un avion géorgien. Le pilote s’éjecte.', 'Around 18:00 a Su-25 of the 368th Attack Aviation Regiment was brought down by shoulder-launched missiles fired by Russian soldiers who took it for a Georgian aircraft. The pilot ejected.', (SELECT id FROM airplanes WHERE name = 'Su-25'), 'https://www.cast.ru/files/The_Tanks_of_August_sm_eng.pdf' FROM wars w WHERE w.name = 'Guerre russo-géorgienne'
