INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2008-08-09', 'day', 'Un Tu-22M3 abattu', 'A Tu-22M3 shot down', 'Au matin, un bombardier Tu-22M3 du 52e régiment de bombardement lourd est abattu par la défense antiaérienne géorgienne au-dessus du district de Satchkhéré. Deux membres d’équipage sont tués, le copilote est capturé et le commandant disparaît.', 'In the morning a Tu-22M3 bomber of the 52nd Heavy Bomber Aviation Regiment was shot down by Georgian air defences over Sachkhere district. Two crew members were killed, the co-pilot was captured and the commander went missing.', (SELECT id FROM airplanes WHERE name = 'Tu-22M'), 'https://www.cast.ru/files/The_Tanks_of_August_sm_eng.pdf' FROM wars w WHERE w.name = 'Guerre russo-géorgienne'
