 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2008-08-09', 'day', 'Un Su-24M abattu près de Chindisi', 'A Su-24M downed near Shindisi', 'Vers 10 h 20, un Su-24M du centre d’essais en vol d’Akhtoubinsk, en mission contre l’artillerie géorgienne, est abattu par un missile portable. Le navigateur est tué, le pilote fait prisonnier.', 'At about 10:20 a Su-24M from the Akhtubinsk flight test centre, attacking Georgian artillery, was hit by a shoulder-launched missile. The navigator was killed and the pilot taken prisoner.', (SELECT id FROM airplanes WHERE name = 'Su-24'), 'https://www.cast.ru/files/The_Tanks_of_August_sm_eng.pdf' FROM wars w WHERE w.name = 'Guerre russo-géorgienne'
