INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2008-08-09', 'day', 'La piste de Kopitnari coupée', 'Kopitnari runway knocked out', 'À 11 h, quatre Tu-22M3 larguent une centaine de bombes de 250 kg sur l’aérodrome de Kopitnari, près de Koutaïssi, dont la piste est touchée en trois endroits et mise hors service.', 'At 11:00 four Tu-22M3s dropped about a hundred 250 kg bombs on Kopitnari airfield near Kutaisi, hitting the runway in three places and putting it out of action.', (SELECT id FROM airplanes WHERE name = 'Tu-22M'), 'https://www.cast.ru/files/The_Tanks_of_August_sm_eng.pdf' FROM wars w WHERE w.name = 'Guerre russo-géorgienne'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
