INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'urss-rda', 1, 'URSS et République démocratique d''Afghanistan', 'USSR and Democratic Republic of Afghanistan', 'Union soviétique (40e armée et son aviation, aviation à long rayon d''action, transport aérien militaire), République démocratique d''Afghanistan et son armée de l''air', 'Soviet Union (40th Army and its air force, Long-Range Aviation, Military Transport Aviation), Democratic Republic of Afghanistan and its air force' FROM wars w WHERE w.name = 'Guerre soviéto-afghane'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'moudjahidines', 2, 'Moudjahidines, soutenus par le Pakistan, les États-Unis et l''Arabie saoudite', 'Mujahideen, backed by Pakistan, the United States and Saudi Arabia', 'Partis moudjahidines afghans ; Pakistan, dont l''armée de l''air lors des incidents frontaliers ; États-Unis et Arabie saoudite (armes et financement), avec des armes chinoises et britanniques', 'Afghan mujahideen parties; Pakistan, including its air force in the border incidents; the United States and Saudi Arabia (weapons and funding), with Chinese and British arms' FROM wars w WHERE w.name = 'Guerre soviéto-afghane'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
