INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1979-12-25', 'day', 'Le pont aérien vers Kaboul et Bagram', 'The airlift to Kabul and Bagram', 'La 40e armée franchit la frontière et des avions de transport déposent la 103e division aéroportée à Kaboul et à Bagram ; un Il-76 s''écrase près de Kaboul avec 37 parachutistes à bord.', 'The 40th Army crosses the border and transports land the 103rd Airborne Division at Kabul and Bagram; an Il-76 crashes near Kabul with 37 paratroopers on board.', (SELECT id FROM airplanes WHERE name = 'Iliouchine Il-76'), 'https://en.wikipedia.org/wiki/List_of_Soviet_aircraft_losses_during_the_Soviet%E2%80%93Afghan_War' FROM wars w WHERE w.name = 'Guerre soviéto-afghane'
