INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'russie', 1, 'Russie', 'Russia', 'Forces fédérales russes (armée, armée de l’air, défense aérienne, troupes du ministère de l’Intérieur, FSB) et, dans la seconde guerre, forces tchétchènes prorusses', 'Russian federal forces (army, air force, air defence, Interior Ministry troops, FSB) and, in the second war, pro-Russian Chechen forces' FROM wars w WHERE w.name = 'Guerres de Tchétchénie'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'tchetchenie', 2, 'Indépendantistes tchétchènes', 'Chechen separatists', 'République tchétchène d’Itchkérie (Djokhar Doudaïev, puis Aslan Maskhadov) et groupes islamistes alliés', 'Chechen Republic of Ichkeria (Dzhokhar Dudayev, then Aslan Maskhadov) and allied Islamist groups' FROM wars w WHERE w.name = 'Guerres de Tchétchénie'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Guerres de Tchétchénie' AND s.side_key NOT IN ('russie', 'tchetchenie');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'russie'), role = 'Seul capable de bombarder au radar par mauvais temps, le Su-24 frappe en 1994-1995 les ponts de l’Argoun et des cibles dans Grozny ; des Su-24MR assurent la reconnaissance. En 1999, il bombarde Elistanji à la bombe à sous-munitions ; un Su-24 est abattu près de Grozny en octobre.', role_en = 'The only aircraft able to bomb by radar in bad weather, the Su-24 hit the Argun bridges and targets in Grozny in 1994-1995, while Su-24MRs flew reconnaissance. In 1999 it dropped cluster bombs on Elistanzhi; one Su-24 was shot down near Grozny in October.', sources = 'https://web.archive.org/web/20130517020721/http://mashar.free.fr/mil_avi.htm
https://www.raf.mod.uk/what-we-do/centre-for-air-and-space-power-studies/aspr/apr-vol4-iss4-2-pdf/
