INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1994-12-01', 'month', 'Les Tu-22M3 sur les arrières de Grozny', 'Tu-22M3s over Grozny''s approaches', 'Des Tu-22M3 frappent les axes et les concentrations de combattants vers Argoun, Goudermes et Chali, et éclairent Grozny la nuit avec des bombes éclairantes.', 'Tu-22M3s struck routes and fighter concentrations towards Argun, Gudermes and Shali, and lit up Grozny at night with illumination bombs.', (SELECT id FROM airplanes WHERE name = 'Tu-22M'), 'https://web.archive.org/web/20130517020721/http://mashar.free.fr/mil_avi.htm' FROM wars w WHERE w.name = 'Guerres de Tchétchénie'
