INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1994-12-01', 'day', 'L’aviation de Doudaïev détruite au sol', 'Dudayev''s air arm destroyed on the ground', 'Les bombardements russes commencent ouvertement : des Su-25 attaquent les aérodromes de Kalinovskaïa, Khankala et Grozny et y détruisent en trois jours les avions d’entraînement tchétchènes.', 'Russian bombing began openly: Su-25s attacked the airfields at Kalinovskaya, Khankala and Grozny, destroying the Chechen training aircraft within three days.', (SELECT id FROM airplanes WHERE name = 'Su-25'), 'https://www.raf.mod.uk/what-we-do/centre-for-air-and-space-power-studies/aspr/apr-vol4-iss4-2-pdf/' FROM wars w WHERE w.name = 'Guerres de Tchétchénie'
