INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1994-12-11', 'day', 'Entrée des troupes russes en Tchétchénie', 'Russian troops enter Chechnya', 'Environ 40 000 soldats russes franchissent la frontière en trois colonnes pour encercler Grozny, cinq jours après un accord entre Doudaïev et le ministre de la Défense Pavel Gratchev pour éviter l’usage de la force.', 'Some 40,000 Russian troops crossed the border in three columns to blockade Grozny, five days after Dudayev and Defence Minister Pavel Grachev had agreed to avoid the use of force.', NULL::int, 'https://en.wikipedia.org/wiki/First_Chechen_War' FROM wars w WHERE w.name = 'Guerres de Tchétchénie'
