INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'commonwealth', 1, 'Royaume-Uni, Commonwealth et Malaisie', 'United Kingdom, Commonwealth and Malaya', 'Royaume-Uni, Fédération de Malaisie, Australie, Nouvelle-Zélande, avec des contingents gurkhas, fidjiens, kényans, du Nyassaland et des deux Rhodésies', 'United Kingdom, Federation of Malaya, Australia, New Zealand, with Gurkha, Fijian, Kenyan, Nyasaland and Northern and Southern Rhodesian contingents' FROM wars w WHERE w.name = 'Insurrection malaise'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'insurges', 2, 'Armée de libération des peuples malais', 'Malayan National Liberation Army', 'Parti communiste malais et sa branche armée, sans aviation', 'Malayan Communist Party and its armed wing, with no air arm' FROM wars w WHERE w.name = 'Insurrection malaise'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Insurrection malaise' AND s.side_key NOT IN ('commonwealth', 'insurges');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'commonwealth'), role = 'En action avec le 656e escadron à partir de septembre 1955, l’AOP.9 rejoint les AOP.6 pour la reconnaissance à vue, la liaison et le marquage des cibles au fumigène, qui guide les Venom, Canberra et Lincoln sur des camps invisibles sous la canopée.', role_en = 'In action with No. 656 Squadron from September 1955, the AOP.9 joined the AOP.6 in visual reconnaissance, liaison and smoke-marking targets, guiding Venoms, Canberras and Lincolns onto camps hidden under the canopy.', sources = 'https://en.wikipedia.org/wiki/Auster_AOP.9
https://www.rafmuseum.org.uk/documents/Research/RAF-Historical-Society-Journals/Journal-21-Seminar-Malaya-Korea-Kuwait-1961.pdf'
