INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1948-06-16', 'day', 'Meurtres de Sungai Siput', 'Sungai Siput murders', 'Trois directeurs européens de plantations sont assassinés dans l’État de Perak ; l’état d’urgence est proclamé dans toute la Malaisie le 18 juin.', 'Three European plantation managers are murdered in Perak; a state of emergency is declared across Malaya on 18 June.', NULL::int, 'https://awm.gov.au/atwar/malayan-emergency' FROM wars w WHERE w.name = 'Insurrection malaise'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
