INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'coalition', 1, 'Coalition puis OTAN', 'Coalition, then NATO', 'France, Royaume-Uni, États-Unis, Italie, Canada, Belgique, Danemark, Norvège, Pays-Bas, Espagne, Grèce, Turquie, Suède, Qatar, Émirats arabes unis, Jordanie', 'France, United Kingdom, United States, Italy, Canada, Belgium, Denmark, Norway, Netherlands, Spain, Greece, Turkey, Sweden, Qatar, United Arab Emirates, Jordan' FROM wars w WHERE w.name = 'Intervention en Libye'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'kadhafi', 2, 'Régime de Kadhafi', 'Gaddafi regime', 'Forces armées de la Jamahiriya arabe libyenne restées fidèles à Mouammar Kadhafi', 'Armed forces of the Libyan Arab Jamahiriya loyal to Muammar Gaddafi' FROM wars w WHERE w.name = 'Intervention en Libye'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
