INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2011-02-21', 'day', 'Deux Mirage F1 libyens se posent à Malte', 'Two Libyan Mirage F1s land in Malta', 'Deux colonels de l’armée de l’air libyenne, qui disent avoir reçu l’ordre de bombarder les manifestants de Benghazi, posent leurs Mirage F1 à Malte. Les appareils ne seront rendus à la Libye qu’en février 2012.', 'Two Libyan air force colonels, who said they had been ordered to bomb protesters in Benghazi, landed their Mirage F1s in Malta. The aircraft were not returned to Libya until February 2012.', (SELECT id FROM airplanes WHERE name = 'Mirage F1'), 'https://en.wikipedia.org/wiki/Free_Libyan_Air_Force' FROM wars w WHERE w.name = 'Intervention en Libye'
