INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'onu-coalition', 1, 'ONU et coalition', 'UN and coalition', 'États-Unis, France, Italie, Allemagne, Nouvelle-Zélande, Pakistan, Inde, Belgique, Canada, Australie et une vingtaine d’autres pays (UNITAF puis ONUSOM II)', 'United States, France, Italy, Germany, New Zealand, Pakistan, India, Belgium, Canada, Australia and some twenty other countries (UNITAF, then UNOSOM II)' FROM wars w WHERE w.name = 'Intervention en Somalie'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'milices', 2, 'Milices somaliennes', 'Somali militias', 'Alliance nationale somalienne (SNA) du général Aidid et autres factions claniques', 'General Aidid''s Somali National Alliance (SNA) and other clan factions' FROM wars w WHERE w.name = 'Intervention en Somalie'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Intervention en Somalie' AND s.side_key NOT IN ('onu-coalition', 'milices');
