INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'brigade-2506', 1, 'Brigade 2506 et CIA', 'Brigade 2506 and CIA', 'Exilés cubains de la Brigade 2506 et de la Fuerza Aérea de Liberación, organisés et soutenus par la CIA, avec des aviateurs américains sous contrat', 'Cuban exiles of Brigade 2506 and the Fuerza Aérea de Liberación, organised and backed by the CIA, with American contract airmen' FROM wars w WHERE w.name = 'Invasion de la baie des Cochons'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'cuba', 2, 'Cuba', 'Cuba', 'Forces armées révolutionnaires de Fidel Castro, dont la Fuerza Aérea Revolucionaria, milices et police nationale', 'Fidel Castro''s Revolutionary Armed Forces, including the Fuerza Aérea Revolucionaria, militia and national police' FROM wars w WHERE w.name = 'Invasion de la baie des Cochons'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Invasion de la baie des Cochons' AND s.side_key NOT IN ('brigade-2506', 'cuba');
UPDATE airplane_wars aw SET side_id = NULL::int, role = 'Côté exilés, les B-26B de la Fuerza Aérea de Liberación frappent les aérodromes le 15 avril puis appuient le débarquement ; sans escorte, plusieurs sont abattus, dont deux à équipage américain le 19. Côté castriste, les B-26C de la FAR attaquent la flotte le 17 ; l’un est abattu.', role_en = 'For the exiles, Fuerza Aérea de Liberación B-26Bs struck the airfields on 15 April and then supported the landing; unescorted, several were shot down, two with American crews on the 19th. For Castro, FAR B-26Cs attacked the fleet on the 17th; one was shot down.', sources = 'https://en.wikipedia.org/wiki/Douglas_A-26_Invader
