SELECT w.id, DATE '1960-03-17', 'day', 'Eisenhower approuve le plan de la CIA', 'Eisenhower approves CIA plan', 'La CIA présente au Conseil de sécurité nationale son plan pour renverser Castro ; Eisenhower l’approuve, avec un budget de 13 millions de dollars.', 'The CIA presents its plan to overthrow Castro to the National Security Council; Eisenhower approves it, with a $13 million budget.', NULL::int, 'https://en.wikipedia.org/wiki/Bay_of_Pigs_Invasion' FROM wars w WHERE w.name = 'Invasion de la baie des Cochons'
