INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'etats-unis', 1, 'États-Unis et Caraïbes', 'United States and Caribbean', 'États-Unis (Joint Task Force 120) et force de paix caribéenne (pays de l’OECO, Barbade, Jamaïque)', 'United States (Joint Task Force 120) and Caribbean Peace Force (OECS states, Barbados, Jamaica)' FROM wars w WHERE w.name = 'Invasion de la Grenade'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'grenade', 2, 'Grenade et Cuba', 'Grenada and Cuba', 'Armée révolutionnaire populaire du Conseil militaire révolutionnaire et ouvriers et militaires cubains', 'Revolutionary Military Council''s People''s Revolutionary Army, with Cuban workers and military personnel' FROM wars w WHERE w.name = 'Invasion de la Grenade'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Invasion de la Grenade' AND s.side_key NOT IN ('etats-unis', 'grenade');
