INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1983-10-19', 'day', 'Maurice Bishop fusillé', 'Maurice Bishop executed', 'Libéré par la foule, Bishop gagne Fort Rupert, où l’armée tire sur ses partisans ; il est capturé et fusillé. Hudson Austin forme un Conseil militaire révolutionnaire.', 'Freed by a crowd, Bishop goes to Fort Rupert, where troops fire on his supporters; he is captured and shot. Hudson Austin forms a Revolutionary Military Council.', NULL::int, 'https://www.govinfo.gov/content/pkg/GOVPUB-D114-PURL-gpo29688/pdf/GOVPUB-D114-PURL-gpo29688.pdf' FROM wars w WHERE w.name = 'Invasion de la Grenade'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1983-10-21', 'day', 'L’Independence dérouté', 'Independence diverted', 'Le groupe aéronaval de l’USS *Independence*, qui faisait route vers le Liban, est dérouté vers la Grenade avec une unité amphibie des Marines.', 'The USS *Independence* carrier group, bound for Lebanon, is diverted towards Grenada along with a Marine amphibious unit.', NULL::int, 'https://www.govinfo.gov/content/pkg/GOVPUB-D114-PURL-gpo29688/pdf/GOVPUB-D114-PURL-gpo29688.pdf' FROM wars w WHERE w.name = 'Invasion de la Grenade'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1983-10-22', 'day', 'Les Caraïbes appellent à l’aide', 'Caribbean states call for help', 'Au nom de l’Organisation des États de la Caraïbe orientale, Eugenia Charles demande officiellement l’intervention des États-Unis ; Ronald Reagan penche aussitôt pour l’action.', 'On behalf of the Organisation of Eastern Caribbean States, Eugenia Charles formally asks the United States to intervene; Ronald Reagan leans at once towards action.', NULL::int, 'https://www.govinfo.gov/content/pkg/GOVPUB-D114-PURL-gpo29688/pdf/GOVPUB-D114-PURL-gpo29688.pdf' FROM wars w WHERE w.name = 'Invasion de la Grenade'
