INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1983-10-25', 'day', 'Les Rangers sautent sur Point Salines', 'Rangers jump on Point Salines', 'À 5 h 30, les Rangers sautent des MC-130E et des C-130 à très basse altitude, sous le feu antiaérien, sur la piste barrée par les Cubains ; l’aérodrome est pris à 7 h 35.', 'At 5:30 a.m. the Rangers jump from MC-130Es and C-130s at very low altitude, under anti-aircraft fire, onto the runway the Cubans have blocked; the airfield is secured at 7:35.', (SELECT id FROM airplanes WHERE name = 'C-130 Hercules'), 'https://www.govinfo.gov/content/pkg/GOVPUB-D114-PURL-gpo29688/pdf/GOVPUB-D114-PURL-gpo29688.pdf' FROM wars w WHERE w.name = 'Invasion de la Grenade'
