SELECT w.id, DATE '1983-10-25', 'day', 'La 82e division arrive en C-141', '82nd Airborne arrives by C-141', 'À partir de 14 heures, des C-141 partis de Pope posent à Point Salines les parachutistes de la 82e division aéroportée, un avion à la fois.', 'From 2 p.m., C-141s from Pope land the paratroopers of the 82nd Airborne Division at Point Salines, one aircraft at a time.', (SELECT id FROM airplanes WHERE name = 'C-141 Starlifter'), 'https://www.govinfo.gov/content/pkg/GOVPUB-D114-PURL-gpo29688/pdf/GOVPUB-D114-PURL-gpo29688.pdf' FROM wars w WHERE w.name = 'Invasion de la Grenade'
