SELECT w.id, DATE '1983-10-27', 'day', 'Tir fratricide d’un A-7', 'A-7 friendly fire', 'Appelé par une équipe de liaison des Marines, un A-7 mitraille par erreur le poste de commandement de la 2e brigade de la 82e division : dix-sept blessés, dont un mourra.', 'Called in by a Marine liaison team, an A-7 strafes the 82nd Airborne''s 2nd Brigade command post by mistake: seventeen wounded, one of whom later dies.', (SELECT id FROM airplanes WHERE name = 'A-7 Corsair II'), 'https://www.govinfo.gov/content/pkg/GOVPUB-D114-PURL-gpo29688/pdf/GOVPUB-D114-PURL-gpo29688.pdf' FROM wars w WHERE w.name = 'Invasion de la Grenade'
