INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'etats-unis', 1, 'États-Unis', 'United States', 'États-Unis (Commandement Sud, Joint Task Force South)', 'United States (Southern Command, Joint Task Force South)' FROM wars w WHERE w.name = 'Invasion du Panama'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'panama', 2, 'Forces de défense du Panama', 'Panama Defense Forces', 'Forces de défense du Panama du général Noriega et bataillons de la dignité', 'General Noriega''s Panama Defense Forces and Dignity Battalions' FROM wars w WHERE w.name = 'Invasion du Panama'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Invasion du Panama' AND s.side_key NOT IN ('etats-unis', 'panama');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis'), role = 'Huit AC-130 (AC-130H du 16th SOS, AC-130A de réserve du 711th SOS) assurent l’essentiel de l’appui feu : ils réduisent la défense antiaérienne de Torrijos-Tocumen et de Rio Hato avant les sauts, puis tirent sur la Comandancia. Leurs équipages reçoivent le trophée Mackay.', role_en = 'Eight AC-130s (16th SOS AC-130Hs and reserve 711th SOS AC-130As) provided most of the fire support, silencing the air defences at Torrijos-Tocumen and Rio Hato before the drops, then firing on the Comandancia. Their crews won the Mackay Trophy.', sources = 'https://www.hurlburt.af.mil/News/Article-Display/Article/205288/operation-just-cause-still-important-20-years-later/
https://aircommando.org/first-fight-special-tactics-in-panama-1989/
https://www.afsoc.af.mil/News/Article-Display/Article/4013673/lessons-learned-memories-of-operation-just-cause-remain-vivid-for-hurlburt-guns/
https://en.wikipedia.org/wiki/Lockheed_AC-130
https://www.jcs.mil/Portals/36/Documents/History/Monographs/Just_Cause.pdf'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'AC-130 Spectre' AND w.name = 'Invasion du Panama'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis'), 'Huit AC-130 (AC-130H du 16th SOS, AC-130A de réserve du 711th SOS) assurent l’essentiel de l’appui feu : ils réduisent la défense antiaérienne de Torrijos-Tocumen et de Rio Hato avant les sauts, puis tirent sur la Comandancia. Leurs équipages reçoivent le trophée Mackay.', 'Eight AC-130s (16th SOS AC-130Hs and reserve 711th SOS AC-130As) provided most of the fire support, silencing the air defences at Torrijos-Tocumen and Rio Hato before the drops, then firing on the Comandancia. Their crews won the Mackay Trophy.', 'https://www.hurlburt.af.mil/News/Article-Display/Article/205288/operation-just-cause-still-important-20-years-later/
