UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'etats-unis'), role = 'L’EC-135L 61-0269 de relais radio, basé à Grissom (Indiana), effectue selon son musée « de nombreuses missions » pendant *Just Cause*, sans que leur nature soit précisée.', role_en = 'EC-135L radio-relay aircraft 61-0269, based at Grissom, Indiana, flew many missions during *Just Cause* according to its museum, which does not say what they involved.', sources = 'https://www.hmdb.org/m.asp?m=311048
