INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'russie', 1, 'Russie', 'Russia', 'Russie ; Biélorussie (territoire et aérodromes ouverts à l’invasion) ; Iran (drones Shahed) ; Corée du Nord (troupes à partir de 2024)', 'Russia; Belarus (territory and airfields opened to the invasion); Iran (Shahed drones); North Korea (troops from 2024)' FROM wars w WHERE w.name = 'Invasion russe de l''Ukraine'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'ukraine', 2, 'Ukraine', 'Ukraine', 'Ukraine, armée par ses soutiens occidentaux : États-Unis, Royaume-Uni, France, Pays-Bas, Danemark, Norvège, Belgique, Pologne, Slovaquie, Australie, Turquie (drones TB2)', 'Ukraine, armed by its Western backers: United States, United Kingdom, France, Netherlands, Denmark, Norway, Belgium, Poland, Slovakia, Australia, Turkey (TB2 drones)' FROM wars w WHERE w.name = 'Invasion russe de l''Ukraine'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Invasion russe de l''Ukraine' AND s.side_key NOT IN ('russie', 'ukraine');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'ukraine'), role = 'Les États-Unis incluent des Puma dans leur aide du 1er avril 2022. La 148e brigade d’artillerie des troupes d’assaut aérien les emploie pour repérer et régler les tirs sur des cibles situées à 45 km et plus, dont des S-300, sur le front de Zaporijjia.', role_en = 'The United States included Pumas in its 1 April 2022 aid package. The 148th Air Assault Artillery Brigade used them to locate and adjust fire on targets 45 km away or more, including S-300s, on the Zaporizhzhia front.', sources = 'https://en.wikipedia.org/wiki/AeroVironment_RQ-20_Puma
https://armyinform.com.ua/2024/05/13/148-artbrygada-pokazala-yak-palyt-voroga-v-tylu-reportazh-pro-robotu-na-amerykanskyh-bpla/'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'AeroVironment RQ-20 Puma' AND w.name = 'Invasion russe de l''Ukraine'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'ukraine'), 'Les États-Unis incluent des Puma dans leur aide du 1er avril 2022. La 148e brigade d’artillerie des troupes d’assaut aérien les emploie pour repérer et régler les tirs sur des cibles situées à 45 km et plus, dont des S-300, sur le front de Zaporijjia.', 'The United States included Pumas in its 1 April 2022 aid package. The 148th Air Assault Artillery Brigade used them to locate and adjust fire on targets 45 km away or more, including S-300s, on the Zaporizhzhia front.', 'https://en.wikipedia.org/wiki/AeroVironment_RQ-20_Puma
https://armyinform.com.ua/2024/05/13/148-artbrygada-pokazala-yak-palyt-voroga-v-tylu-reportazh-pro-robotu-na-amerykanskyh-bpla/');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'ukraine'), role = 'Les États-Unis envoient 700 Switchblade 300 en 2022, employés pour la première fois début mai dans la région de Kharkiv, puis des Switchblade 600 antichars, engagés au printemps 2023. Le brouillage russe réduit ensuite l’emploi du modèle 300.', role_en = 'The United States sent 700 Switchblade 300s in 2022, first used in early May in Kharkiv Oblast, then anti-armour Switchblade 600s, in combat from spring 2023. Russian jamming then reduced the use of the 300.', sources = 'https://en.wikipedia.org/wiki/AeroVironment_Switchblade'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'AeroVironment Switchblade' AND w.name = 'Invasion russe de l''Ukraine'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'ukraine'), 'Les États-Unis envoient 700 Switchblade 300 en 2022, employés pour la première fois début mai dans la région de Kharkiv, puis des Switchblade 600 antichars, engagés au printemps 2023. Le brouillage russe réduit ensuite l’emploi du modèle 300.', 'The United States sent 700 Switchblade 300s in 2022, first used in early May in Kharkiv Oblast, then anti-armour Switchblade 600s, in combat from spring 2023. Russian jamming then reduced the use of the 300.', 'https://en.wikipedia.org/wiki/AeroVironment_Switchblade');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'ukraine'), role = 'Les An-124 d’Antonov Airlines, compagnie d’État ukrainienne, acheminent l’aide occidentale : en mai 2022, ils emportent d’Australie des obusiers M777 et des blindés Bushmaster. Un An-124 en révision est criblé de balles à Hostomel.', role_en = 'The An-124s of Antonov Airlines, a Ukrainian state company, carried Western aid: in May 2022 they flew M777 howitzers and Bushmaster armoured vehicles from Australia. An An-124 under overhaul was riddled with bullets at Hostomel.', sources = 'https://mezha.ua/en/2022/04/03/hostomel-aircraft-losses-mriya-antey-ruslan/
https://australianaviation.com.au/2022/05/antonov-124-carries-bushmasters-to-ukraine/'
