UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'russie'), role = 'Selon une source anonyme citée par RIA Novosti en septembre 2022, l’un des deux Tu-214R de renseignement électronique et optique a servi, après révision, à repérer des centres de commandement, des radars et des colonnes ukrainiennes.', role_en = 'According to an anonymous source quoted by RIA Novosti in September 2022, one of the two Tu-214R electronic and optical intelligence aircraft was used, after an overhaul, to locate Ukrainian command posts, radars and columns.', sources = 'https://www.mk.ru/politics/2022/09/24/samolyotrazvedchik-tu214r-pomog-vskryt-ukrainskie-voennye-obekty.html'
  FROM airplanes a, wars w
 WHERE aw.id_airplane = a.id AND aw.id_wars = w.id AND a.name = 'Tupolev Tu-214R' AND w.name = 'Invasion russe de l''Ukraine'
   AND (aw.side_id, aw.role, aw.role_en, aw.sources) IS DISTINCT FROM ((SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'russie'), 'Selon une source anonyme citée par RIA Novosti en septembre 2022, l’un des deux Tu-214R de renseignement électronique et optique a servi, après révision, à repérer des centres de commandement, des radars et des colonnes ukrainiennes.', 'According to an anonymous source quoted by RIA Novosti in September 2022, one of the two Tu-214R electronic and optical intelligence aircraft was used, after an overhaul, to locate Ukrainian command posts, radars and columns.', 'https://www.mk.ru/politics/2022/09/24/samolyotrazvedchik-tu214r-pomog-vskryt-ukrainskie-voennye-obekty.html');
