INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2022-02-24', 'day', 'Assaut sur Hostomel', 'Assault on Hostomel', 'Après une vague de missiles contre les radars et les bases ukrainiennes, des hélicoptères russes venus de Biélorussie déposent des parachutistes sur l’aéroport Antonov ; les Il-76 de renfort ne peuvent pas s’y poser.', 'After a wave of missiles against Ukrainian radars and bases, Russian helicopters from Belarus land paratroopers at Antonov Airport; the reinforcing Il-76s cannot land there.', (SELECT id FROM airplanes WHERE name = 'Iliouchine Il-76'), 'https://en.wikipedia.org/wiki/Battle_of_Antonov_Airport' FROM wars w WHERE w.name = 'Invasion russe de l''Ukraine'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2022-02-27', 'day', 'L’An-225 détruit', 'The An-225 destroyed', 'Ukroboronprom annonce la destruction de l’An-225 *Mriya*, le plus gros avion du monde, dans son hangar d’Hostomel pendant les combats pour l’aéroport.', 'Ukroboronprom announces that the An-225 *Mriya*, the world’s largest aircraft, has been destroyed in its Hostomel hangar during the battle for the airport.', NULL::int, 'https://en.wikipedia.org/wiki/Antonov_An-225_Mriya' FROM wars w WHERE w.name = 'Invasion russe de l''Ukraine'
