SELECT w.id, DATE '2022-05-07', 'day', 'Raid sur l’île aux Serpents', 'Raid on Snake Island', 'Des TB2 ukrainiens détruisent un hélicoptère Mi-8 et des lance-missiles Tor sur l’île occupée, ouvrant la voie à un bombardement à très basse altitude par deux Su-27.', 'Ukrainian TB2s destroy a Mi-8 helicopter and Tor missile launchers on the occupied island, clearing the way for a very low-level bombing run by two Su-27s.', (SELECT id FROM airplanes WHERE name = 'Bayraktar TB2'), 'https://en.wikipedia.org/wiki/Baykar_Bayraktar_TB2' FROM wars w WHERE w.name = 'Invasion russe de l''Ukraine'
