INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2022-09-13', 'day', 'Premiers drones Shahed', 'First Shahed drones', 'L’Ukraine abat un premier drone d’attaque iranien Shahed 136, rebaptisé Geran-2 par la Russie. Dès octobre, ces drones frappent en masse le réseau électrique ukrainien.', 'Ukraine shoots down a first Iranian Shahed 136 attack drone, renamed Geran-2 by Russia. From October these drones strike the Ukrainian power grid en masse.', NULL::int, 'https://en.wikipedia.org/wiki/HESA_Shahed_136' FROM wars w WHERE w.name = 'Invasion russe de l''Ukraine'
