SELECT w.id, DATE '2024-01-14', 'day', 'Un A-50 abattu', 'An A-50 shot down', 'Un avion radar A-50 est abattu au-dessus de la mer d’Azov et un Il-22 touché parvient à se poser à Anapa. Un second A-50 est abattu le 23 février.', 'An A-50 radar aircraft is shot down over the Sea of Azov and a damaged Il-22 manages to land at Anapa. A second A-50 is shot down on 23 February.', (SELECT id FROM airplanes WHERE name = 'Beriev A-50'), 'https://en.wikipedia.org/wiki/2024_Sea_of_Azov_Beriev_A-50_shootdown' FROM wars w WHERE w.name = 'Invasion russe de l''Ukraine'
