INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '2025-06-01', 'day', 'Opération *Toile d’araignée*', 'Operation *Spiderweb*', 'Des drones lancés depuis des camions frappent cinq bases russes, jusqu’en Sibérie. Le SBU revendique 41 avions touchés ; des responsables américains en comptent une vingtaine, dont une dizaine détruits.', 'Drones launched from trucks strike five Russian bases, as far as Siberia. The SBU claims 41 aircraft hit; US officials count about twenty, ten of them destroyed.', (SELECT id FROM airplanes WHERE name = 'Tu-95'), 'https://en.wikipedia.org/wiki/Operation_Spiderweb' FROM wars w WHERE w.name = 'Invasion russe de l''Ukraine'
