INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'turquie', 1, 'Turquie', 'Turkey', 'Turquie, combattants chypriotes turcs', 'Turkey, Turkish Cypriot fighters' FROM wars w WHERE w.name = 'Invasion turque de Chypre'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
INSERT INTO war_sides (war_id, side_key, position, name, name_en, members, members_en)
SELECT w.id, 'grece-chypre', 2, 'Grèce et Chypriotes grecs', 'Greece and Greek Cypriots', 'Grèce (junte des colonels), Garde nationale chypriote', 'Greece (the colonels’ junta), Cypriot National Guard' FROM wars w WHERE w.name = 'Invasion turque de Chypre'
ON CONFLICT ON CONSTRAINT uq_war_sides_key DO UPDATE
   SET position = EXCLUDED.position, name = EXCLUDED.name, name_en = EXCLUDED.name_en,
       members = EXCLUDED.members, members_en = EXCLUDED.members_en
 WHERE (war_sides.position, war_sides.name, war_sides.name_en, war_sides.members, war_sides.members_en)
       IS DISTINCT FROM (EXCLUDED.position, EXCLUDED.name, EXCLUDED.name_en, EXCLUDED.members, EXCLUDED.members_en);
DELETE FROM war_sides s USING wars w
 WHERE s.war_id = w.id AND w.name = 'Invasion turque de Chypre' AND s.side_key NOT IN ('turquie', 'grece-chypre');
UPDATE airplane_wars aw SET side_id = (SELECT s.id FROM war_sides s WHERE s.war_id = aw.id_wars AND s.side_key = 'turquie'), role = 'Principal chasseur-bombardier turc, le F-100 appuie le débarquement et frappe autour de Nicosie ; le 21 juillet, 28 F-100D participent par erreur à l’attaque qui coule le destroyer turc *Kocatepe*. Il ouvre aussi la seconde offensive le 14 août.', role_en = 'Turkey’s main fighter-bomber, the F-100 supported the landings and struck around Nicosia; on 21 July, 28 F-100Ds took part in the mistaken attack that sank the Turkish destroyer *Kocatepe*. It also opened the second offensive on 14 August.', sources = 'https://en.wikipedia.org/wiki/North_American_F-100_Super_Sabre
