INSERT INTO war_events (war_id, event_date, date_precision, title, title_en, body, body_en, airplane_id, source)
SELECT w.id, DATE '1974-07-15', 'day', 'Coup d’État à Nicosie', 'Coup in Nicosia', 'La Garde nationale, commandée par des officiers grecs, renverse le président Makarios et installe Nikos Sampson, partisan du rattachement à la Grèce.', 'The National Guard, led by Greek officers, overthrows President Makarios and installs Nikos Sampson, a supporter of union with Greece.', NULL::int, 'https://en.wikipedia.org/wiki/Turkish_invasion_of_Cyprus' FROM wars w WHERE w.name = 'Invasion turque de Chypre'
