SELECT w.id, DATE '1963-12-10', 'day', 'Grenade à Khormaksar, état d''urgence', 'Grenade at Khormaksar, state of emergency', 'Une grenade lancée sur le haut-commissaire Sir Kennedy Trevaskis, sur le tarmac de l''aéroport, blesse mortellement son adjoint George Henderson. L''état d''urgence est proclamé dans toute l''Arabie du Sud.', 'A grenade thrown at High Commissioner Sir Kennedy Trevaskis on the airport tarmac mortally wounded his assistant George Henderson. A state of emergency was declared across South Arabia.', NULL::int, 'http://www.radfanhunters.co.uk/Ksar-1963.htm' FROM wars w WHERE w.name = 'Urgence d''Aden'
ON CONFLICT ON CONSTRAINT uq_war_events DO UPDATE
   SET date_precision = EXCLUDED.date_precision, title_en = EXCLUDED.title_en, body = EXCLUDED.body,
       body_en = EXCLUDED.body_en, airplane_id = EXCLUDED.airplane_id, source = EXCLUDED.source
 WHERE (war_events.date_precision, war_events.title_en, war_events.body, war_events.body_en, war_events.airplane_id, war_events.source)
       IS DISTINCT FROM (EXCLUDED.date_precision, EXCLUDED.title_en, EXCLUDED.body, EXCLUDED.body_en, EXCLUDED.airplane_id, EXCLUDED.source);
